const e=[{id:1,code:"FIRE-101",icon:"Flame",accent:"#ea580c",title:"زانستێ ئاگری و داینامیکا سۆتنێ",subtitle:"Fire Science & Combustion Dynamics",summary:"شیکارکرنا کیمیایی و فیزیایی یا ئاگری: هەرەما ئاگری، شێوازێن گوهاستنا گەرمیێ، قۆناغێن گەشەکرنێ، و دیاردەیێن Flashover و Backdraft.",blocks:[{body:`دەستپێک: ئاگر نە تەنێ دیاردەیەکا دیتنی یە، بەلکو د زانستێن ئەندازیاری و کیمیایێ دا وەک پرۆسەیەکا ئۆکسیدبوونا بلەز (Rapid Oxidation) دهێتە ناسین، کو تێدا وزە ب شێوەیێ گەرمی و ڕووناهییێ ئازاد دبیت. مرۆڤایەتییێ ژ سەردەمێن کەڤن ئاگر بۆ پێشئێخستنا شارستانییەتێ بکار ئینایە، بەلێ ئەگەر ئاگر ب دروستی نەهێتە کۆنترۆلکرن، دبیتە هێزەکا وێرانکەر. بۆ ئەندازیارێن سەلامەتیێ و شارەزایێن بەرگرییا شارستانی، تێگەهشتن ژ داینامیکا سۆتنێ نە تەنێ پێدڤییە، بەلکو بنەمایێ سەرەکی یێ پاراستنا ژیان و سامانی یە.

سروشتێ زانستی یێ ئاگری: ئاگر کارلێکەکا کیمیایی یا ئالۆزە ژ جۆرێ گەرمی-ئازادکەر (Exothermic Reaction). ئەڤ پرۆسەیە پێدڤی ب هەڤسەنگییەکا دروست د ناڤبەرا سێ یان چار ڕەگەزێن سەرەکی دا هەیە. جیاوازیا د ناڤبەرا ئاگرەکێ کۆنترۆلکری و کارەساتەکا ئاگری دا، گرێدایی تێگەهشتنا مە یە ل سەر شێوازێ بەلاڤبوونا گەرمیێ و گوهۆڕینێن فیزیایی یێن ماددەیان.

ئارمانجا ڤێ مۆدیوولێ: ئەم دێ ژ ئاستێ ناسینا ئاسایی یا ئاگری دەرباز بین بەرەڤ ڤەکۆلینەکا هوورتر ل سەر: (١) کیمیایا سۆتنێ: چەوا مۆلیکولێن ماددەی تێک دچن و دبنە غازێن سۆتێنەر؛ (٢) فیزیایا گوهاستنا وزەیێ: چەوانیا لڤینا گەرمیێ ب ڕێکا گەهاندن، هەلگرتن و تیشکدانێ؛ (٣) ڕەفتارێ ئاگری د جهێن داخستی دا: شیکارکرنا دیاردەیێن کوژەک وەک Flashover و Backdraft. ئەڤ پێزانینە بنەمانە بۆ هەر قوتابییەکێ زانکۆیێ یان ئەندازیارەکێ کو دڤێت ب شێوازەکێ زانستی سیستەمێن پاراستنێ و ستراتیژییێن ئاگرکوژاندنێ دیزاین بکەت.`},{heading:"١. تیۆریا هەرەما ئاگری: شیکارکرنا داینامیکی (The Fire Tetrahedron)",body:"ل ئاستێ ئەکادیمی و ئەندازیاری، ئەم ژ تێگەهێ «سێگۆشەیا ئاگری» دەرباز دبین و پشت ب «هەرەما ئاگری» (Fire Tetrahedron) دبەستین. جیاوازیا سەرەکی ئەوە کو هەرەم نیشان ددەت کا چەوا ئاگرێ گڕدار (Flaming Combustion) وەک پرۆسەیەکا کیمیایی یا بەردەوام کار دکەت. ئەگەر ئێک ژ ڤان چار ڕەگەزان بهێتە لادان، یان هەڤسەنگیا وان تێک بچیت، ئاگر دێ ڤەمریت.",points:["ماددێ سۆتێنەر (Fuel / Reducing Agent): دشێت د هەر سێ حالەتێن فیزیکی دا بیت (ڕەق، شل، غاز). تێبینییەکا زانستی یا گرنگ: ماددەیێن ڕەق و شل ب خوە ب گڕ ناسۆژن؛ ماددێ ڕەق پێدڤی ب شیکاربوونا ب گەرمیێ (Pyrolysis) هەیە و ماددێ شل پێدڤی ب هەلمبوونێ (Vaporization) هەیە. ڕێژەیا ڕووبەری بەرامبەر بارستەیێ (Surface-to-Mass Ratio) گەلەک گرنگە: هندی ماددە هوورتر بیت، بلەزتر دچیتە د پرۆسەیا سۆتنێ دا.","ماددێ ئۆکسیدکەر (Oxidizing Agent): د پترییا بارودۆخان دا، ئۆکسجینا هەوایێ (نێزیکی ٢١٪) سەرچاڤەیا سەرەکی یە. ب گشتی، ئەگەر ڕێژەیا ئۆکسجینێ ژ نێزیکی ١٦٪ کێمتر ببیت، سۆتنا گڕدار (Flaming) لاواز دبیت یان ڕادوەستیت و دبیتە سۆتنا بێ گڕ (Smoldering). تێگەهەکێ پێشکەفتی: هندەک ماددە (وەک Ammonium Nitrate) ب خوە ماددێن ئۆکسیدکەرن و ئۆکسجینێ ددەنە ئاگری، ژبەرهندێ ڤەمراندنا وان گەلەک زەحمەتە.","گەرمی (Heat / Activation Energy): ئەو وزەیە یا کو سۆتنێ دەست پێ دکەت و بەردەوام دکەت. ڤەگەڕانا گەرمیێ (Thermal Feedback) دیاردەیەکا فیزیایی یە کو تێدا ئاگر گەرمییێ دزڤڕینیتەڤە بۆ وی ماددێ سۆتێنەر یێ کو هێشتا نەسۆتی. پلەیا گڕگرتنا خوەکار (Autoignition Temperature) کێمترین پلەیا گەرمیێ یە کو ماددە تێدا ب بێ پشکۆ یان گڕ ب خوە ئاگر دگریت.","کارلێکا زنجیرەیی یا کیمیایی (Uninhibited Chemical Chain Reaction): ئەڤ ڕەگەزە ئاگری ژ گڕەکا دەمکی دگوهۆڕیت بۆ سۆتنەکا بەردەوام. ڕادیکالێن ئازاد (Free Radicals) وەک H و O و OH ب لەزەکا مەزن دگەل مۆلیکولێن نوو کارلێک دکەن و وزەیێ ئازاد دکەن. هندەک ماددەیێن ڤەمراندنێ (وەک Halon و تۆزا کیمیایی یا هشک - Dry Chemical) ڤان ڕادیکالان ژ ناڤ دبەن و ب ڤی ڕەنگی کارلێکا زنجیرەیی دشکێنن.","تێبینییێن زانستی: فشارا هەلمێ (Vapor Pressure): هندی بلندتر بیت، ماددە زووتر هەلمێ بەرددەت و زووتر ئاگر دگریت. سنوورێن سۆتنێ (Flammability Limits): ئاگر تەنێ د ناڤبەرا ڕێژەیەکا گونجای یا سۆتەمەنی و هەوایێ دا دروست دبیت؛ ئەگەر غاز گەلەک زێدە بیت (Rich) یان گەلەک کێم بیت (Lean)، ئاگر دروست نابیت."]},{heading:"٢. شێوازێن گوهاستنا گەرمیێ (Heat Transfer Mechanisms)",body:"ئاگر ل جهەکێ دیارکری نامینیت، بەلکو ب سێ ڕێکێن جودا بەلاڤ دبیت و وزەیێ دگوهێزیتە ماددەیێن دی. تێگەهشتن ژ ڤان میکانیزمان بۆ ئەندازیاران گەلەک گرنگە دا کو بزانن ئاگر چەوا مەزن دبیت و چەوا دشێن ڕێگرییێ لێ بکەن:",points:["گەهاندن (Conduction): گوهاستنا گەرمیێ یە ب ڕێکا بەرکەفتنا ڕاستەوخۆ د ناڤ ماددەیێن ڕەق دا. بۆ نموونە، ئەگەر لایەکێ دەرگەهەکێ ئاسنی یان دیوارەکێ کانزایی ژ ئاگری گەرم ببیت، گەرمی د ناڤ ماددەی دا دگەهیتە لایێ دی و دشێت ماددەیێن وی لایی ژی بگەهینیتە پلەیا گڕگرتنێ. کانزا (وەک ئاسن، مس، ئەلەمنیۆم) گەرمییێ گەلەک باش دگەهینن (Thermal Conductivity یا بلند)، بەلێ دار، پلاستیک و کۆنکریت کێمتر دگەهینن. ئەڤە ئێک ژ ئەگەرانە کو دیوارێن دژە-ئاگر ژ ماددەیێن کێم-گەهێنەر دهێنە دروستکرن.","هەلگرتن (Convection): گوهاستنا گەرمیێ یە ب ڕێکا لڤینا شلەمەنی یان غازان. هەوایێ گەرم و غازێن سۆتنێ ژ هەوایێ سار سڤکترن، ژبەرهندێ بەرەڤ سەری دچن (یاسایا Buoyancy). ئەڤە ئێک ژ مەترسیدارترین شێوازانە د ئاڤاهیێن داخستی دا، چونکی هەوایێ گەرم، دوکێل و غازێن ژەهراوی ل بن سەقفی کۆم دبن و دشێن بگەهنە ٦٠٠–٨٠٠ پلەیێن سیلیزی. دەمێ ئەڤ چینا گەرم دگەهیتە ماددەیێن ل سەری، وان دگەهینیتە خالا گڕگرتنێ، و دبیتە ئەگەرێ بەلاڤبوونا ئاگری بۆ ژوور و نهۆمێن دی.","تیشکدان (Radiation): گوهاستنا وزەیا گەرمیێ یە ب شێوەیێ شەپۆلێن ئەلەکترۆمەگنەتیسی (Electromagnetic Waves)، ب تایبەتی تیشکێن ژێر-سۆر (Infrared). تیشکدان پێدڤی ب بەرکەفتنا ڕاستەوخۆ یان ب هەوایێ نینە؛ وزە د ڤالاهیێ (Vacuum) دا ژی دهێتە گوهاستن. ژبەرهندێ ئاگرەکێ مەزن دشێت ئاڤاهییەکێ نێزیک بگەهینیتە پلەیا گڕگرتنێ بێ کو گڕ بگەهیتێ. ژ بەر ڤێ چەندێ، ئاگرکوژ جلوبەرگێن پاراستنێ یێن تایبەت لبەر دکەن و مەودایەکێ سەلامەت ژ ئاگری دپارێزن."]},{heading:"٣. قۆناغێن گەشەکرنا ئاگری (Stages of Fire Development)",body:"هەر ئاگرەک، ژ ئاگرەکێ بچووک ل سەر سۆبەیێ هەتا ئاگرێ ئاڤاهییەکێ مەزن، ب گشتی ب چار قۆناغێن ستاندارد دا دەرباز دبیت. ناسینا ڤان قۆناغان بۆ ئاگرکوژان گەلەک گرنگە دا کو بزانن کەنگی و ب کیش ستراتیژی دەستێوەردانێ بکەن:",points:["قۆناغا دەستپێکێ (Incipient Stage): ئەڤە سەرەتاییترین قۆناغا ئاگری یە. پلەیا گەرمیێ هێشتا نزمە، دوکێل هەیە بەلێ کێمە، و ئاگر هێشتا بچووکە و ل جهەکێ دیارکری یە. ل ڤێ قۆناغێ، ئاگر ب ساناهی ب تەمرینکەکا دەستی دهێتە کۆنترۆلکرن. ڕێژەیا ئۆکسجینێ هێشتا نێزیکی ٢١٪ یە. ئەڤە باشترین دەمە بۆ ڤەمراندنێ چونکی ئاگر هێشتا بچووکە.","قۆناغا گەشەکرنێ (Growth Stage): ئاگر ب لەز مەزن دبیت؛ گەرمی زێدە دبیت، دوکێل گەلەک دبیت، و گڕ دگەهیتە ماددەیێن نێزیک. پلەیا گەرمیێ دگەهیتە چەند سەد پلەیێن سیلیزی و هەوایێ گەرم ل بن سەقفی کۆم دبیت. ل ڤێ قۆناغێ، مەترسییا Rollover هەیە: گڕگرتنا غازێن نەسۆتی یێن د چینا گەرم یا بن سەقفی دا، کو ب شێوەیێ زمانێن گڕێ ل بن سەقفی بەلاڤ دبن. ئەگەر دەستێوەردان نەهێتە کرن، ئاگر ب لەز دچیتە قۆناغا پاشتر.","قۆناغا گەشەکرنا تەمام (Fully Developed Stage): گەرمترین و مەترسیدارترین قۆناغە. پشتی Flashover، هەمی ماددەیێن سۆتێنەر یێن ژوورێ ئاگر گرتینە و پێکڤە دسۆژن. پلەیا گەرمیێ دشێت ژ ١٠٠٠ پلەیێن سیلیزی پتر بیت. گڕ ژ دەرگەهـ و پەنجەرەیان دەردکەڤیت و دوکێلا ڕەش هەمی جهی دگریت. چوونا ناڤ ژوورێ ل ڤێ قۆناغێ گەلەک مەترسیدارە و تەنێ ب پاراستنا تەمام و ب پلانەکا تاکتیکی دهێتە کرن. ئاگر پترییا ئۆکسجینا هەی بکار دئینیت، ژبەرهندێ سۆتن ب هەوایێ دهێتە سنووردارکرن (Ventilation-Limited).","قۆناغا کێمبوونێ (Decay Stage): پشتی کو پترییا سۆتەمەنیێ سۆتی یان ئۆکسجین کێم بوو، ئاگر هێدی هێدی لاواز دبیت و پلەیا گەرمیێ دادکەڤیت، بەلێ هێشتا مەترسییەکا مەزن هەیە: Backdraft. ئەگەر ژوورەک تژی غازێن سۆتێنەر یێن نەسۆتی بیت و کەسەک ژنشکەکێ ڤە دەرگەهی ڤەکەت و ئۆکسجین بهێتە ژوورێ، دشێت تەقینەکا مەزن چێببیت کو هەمی کەسێن نێزیک بکوژیت."]},{heading:"٤. دیاردەیێن مەترسیدار (Dangerous Fire Phenomena)",body:"د زانستێ ئاگری دا، دوو دیاردەیێن کوژەک هەنە کو هەر ئەندازیارەک و ئاگرکوژەک دڤێت ب تەمامی ئاگەهداری وان بیت:",points:["Flashover: گڕگرتنا ژنشکەکێ ڤە یا هەمی ماددەیێن سۆتێنەر یێن ژوورەکێ پێکڤە. ب گشتی دەمێ پلەیا گەرمیا چینا غازێ ل بن سەقفی دگەهیتە نێزیکی ٥٠٠–٦٠٠ پلەیێن سیلیزی ڕوودەت، و تیشکدانا گەرمیێ (Radiant Heat) ژ سەقفی هەمی ماددەیێن ژوورێ دگەهینیتە خالا گڕگرتنێ. ئەڤ گوهۆڕینە د ماوەیەکێ گەلەک کورت دا (چەند چرکەیان) ڕوودەت و ژووری دکەتە کووچکەکا ئاگری. نیشانێن Flashover: دوکێلا ڕەش و ستوور ل بن سەقفی، زمانێن گڕێ ل بن سەقفی (Rollover)، دەرکەفتنا دوکێلێ ژ کەلوپەلان، و گەرمییەکا ژنشکەکێ ڤە یا توند. دەمێ ئاگرکوژ ڤان نیشانان دبینن، دڤێت ئێکسەر ژوورێ بهێلن یان ب ئاڤێ چینا غازێ سار بکەن.","Backdraft: تەقینەکا ئاگری یە کو ڕوودەت دەمێ ئۆکسجین ژنشکەکێ ڤە دهێتە ناڤ ژوورەکا گەرم کو ئۆکسجین تێدا کێم بوویە، بەلێ هێشتا غازێن سۆتێنەر و گەرمی تێدا گەلەکن. ئەڤ ژوورە وەک بۆمبەکێ یە کو چاڤەڕێی ئۆکسجینێ یە. دەمێ دەرگەهـ دهێتە ڤەکرن، هەوایێ تازە دچیتە ژوور، غازێن سۆتێنەر ب ئێکجاری گڕ دگرن و تەقین چێدبیت و گڕەکا مەزن بەرەڤ دەرڤە دهاڤێژیت. نیشانێن Backdraft: دوکێلا زەر-قاوەیی، پەنجەرەیێن ڕەشبووی ب دوکێلێ، گەرمبوونا دەرگەهی، لڤینا پالدان و ڤەکێشانا دوکێلێ (Pulsating Smoke)، و دەنگەکێ فیکەیی ژ ژوورێ. ل ڤان حالەتان دەرگەهـ ب ساناهی نەهێتە ڤەکرن؛ پێدڤییە پێشی ژ جهێ هەرە بلند هەوا بهێتە دەرئێخستن (Vertical Ventilation) یان دەرگەهـ ب شێوەیەکێ کۆنترۆلکری و ژ لایەکێ پاراستی بهێتە ڤەکرن."]},{heading:"٥. شیکاربوونا ب گەرمیێ (Pyrolysis)",body:"Pyrolysis ئەو پرۆسەیا کیمیایی یە کو تێدا ماددەیێن ڕەق ب گەرمیێ دشکێن و دبنە غازێن سۆتێنەر. ب زمانێ زانستی، ماددێ ڕەق ب خوە ب گڕ ناسۆژیت؛ ئەو غازێن ژ Pyrolysis پەیدا دبن دسۆژن. بۆ نموونە، دار ب خوە گڕ ناگریت، بەلێ دەمێ دگەهیتە پلەیێن بلند یێن گەرمیێ (نێزیکی ٢٠٠–٣٠٠ پلەیێن سیلیزی)، مۆلیکولێن وێ دشکێن و هەلمێن سۆتێنەر (Volatile Gases) پەیدا دکەن، و ئەڤ هەلمە گڕ دگرن و دسۆژن. پاشماوەیا ڤێ پرۆسەیێ خەلووزە (Char) کو پترییا وێ کاربۆنە.",points:["ماددەیێن پلاستیکی ل دەمێ Pyrolysis غازێن گەلەک ژەهراوی بەرهەم دئینن، وەک هایدرۆجین سیانید (HCN) و مۆنۆکسیدا کاربۆنێ (CO).","ماددەیێن وەک ئیسفەنجا مۆبیلیان (Foam) و پۆلیستایرین گەلەک ب لەز دچنە د پرۆسەیا Pyrolysis دا و غازێن مەترسیدار بەرهەم دئینن.","زانینا پلەیا Pyrolysis یا ماددەیان (Pyrolysis Temperature) بۆ دیزاینا ماددەیێن ئاڤاهی و مۆبیلیان گرنگە، دا کو ب زەحمەت ئاگر بگرن."]},{heading:"٦. بەرهەمێن سۆتنێ و ژەهراویبوون (Products of Combustion)",body:"دەمێ ماددە دسۆژن، غازێن جودا جودا بەرهەم دهێن کو هندەک ژ وان کوژەکن:",points:["مۆنۆکسیدا کاربۆنێ (CO): غازەکا بێ بێهن و بێ ڕەنگە بەلێ گەلەک ژەهراوی یە. دگەل هیمۆگلۆبینا خوینێ گرێ ددەت و ڕێگرییێ ل گوهاستنا ئۆکسجینێ بۆ شانە و مێشکی دکەت. پترییا مرنێن ئاگران ژبەر هەلمژینا دوکێل و غازێن ژەهراوی (وەک CO و HCN) ڕوودەن، نە ژبەر سۆتنا جەستەی.","کاربۆن دایۆکساید (CO₂): ل ڕێژەیێن کێم غازەکا ژەهراوی نینە، بەلێ ل ڕێژەیێن بلند ب خوە ژەهراوی دبیت و هەروەسا دبیتە ئەگەرێ خەندقینێ (Asphyxiation) چونکی جهێ ئۆکسجینێ دگریت.","هایدرۆجین سیانید (HCN): غازەکا گەلەک کوژەکە کو ژ سۆتنا پلاستیک، ئیسفەنج و هندەک قوماشان بەرهەم دهێت. ل چڕییێن بلند دشێت د ماوەیەکێ گەلەک کورت دا بکوژیت.","هایدرۆجین کلۆراید (HCl): غازەکا خوارەرە (Corrosive) کو ژ سۆتنا PVC (پلاستیکێ بۆری و وایەران) بەرهەم دهێت و زیانێ دگەهینیتە سییان و چاڤان.","دوکێل (Smoke): دوکێل تەنێ ڕەنگەک نینە؛ تژی تەنۆلکێن هوور (Particulates)، غاز و ماددەیێن کیمیایی یە. دوکێل دشێت ببیتە ئەگەرێ خەندقینێ، کۆرەبوونا دەمکی و زیانا سییان."]},{heading:"٧. پۆلێنکرنا ئاگری: سیستەمێ NFPA و سیستەمێ ئەورووپی EN 2",body:"بۆ هلبژارتنا تەمرینکا دروست، دڤێت پۆلێنکرنا ئاگری بزانی. ل ڤێرە سیستەمێ ئەمریکی NFPA (NFPA 10) دهێتە بکارئینان، و جیاوازییێن سیستەمێ ئەورووپی EN 2 ل هەر خالەکێ هاتینە دیارکرن. هەر پۆلەک پێدڤی ب شێوازەکێ تایبەت یێ ڤەمراندنێ هەیە:",points:["Class A (هەردوو سیستەم) - ماددەیێن ڕەق: دار، کاغەز، قوماش، پلاستیکێن ئاسایی. ڤەمراندن: سارکرن ب ئاڤێ (Cooling). تەمرینکێن ئاڤێ، کەفێ (Foam) و تۆزا ABC گونجاینە.","Class B - شلەمەنییێن سۆتێنەر: بەنزین، نەفت، ڕەنگ، سۆلڤێنت (ل NFPA غازێن سۆتێنەر ژی د ناڤ پۆلا B دا نە؛ ل EN 2 غاز پۆلا C نە). ڤەمراندن: خەندقاندن (Smothering) ب کەفێ یان CO₂ یان تۆزا ABC. ڕژاندنا ئاڤێ ب ستوونەکا ڕاستەوخۆ نەگونجایە چونکی شلەمەنییا سۆتی بەلاڤ دکەت.","Class C (NFPA) - ئاگرێ ئامێرێن کارەبایێ یێن ب کارەبا ڤە گرێدای: پانێل، وایەر، ئامێر. ڤەمراندن: ماددەیێن کارەبا نەگەهێن (Non-conductive) وەک CO₂ یان تۆزا کیمیایی. ئەگەر سەلامەت بیت، پێشی کارەبایێ ببڕە. ل سیستەمێ EN 2، کارەبا پۆلەکا جودا نینە و پۆلا C بۆ غازێن سۆتێنەرە.","Class D (هەردوو سیستەم) - کانزایێن سۆتێنەر: مەگنیسیۆم، تیتانیۆم، سۆدیۆم، پۆتاسیۆم، لیتیۆم (کانزا). ڤەمراندن: تۆزا تایبەت یا پۆلا D (وەک تۆزا ل سەر بنەمایێ گرافیت یان سۆدیۆم کلۆراید) یان خیزا هشک. ئاڤ گەلەک مەترسیدارە چونکی دشێت کارلێکەکا توند و تەقین چێبکەت. تێبینی: باترییێن لیتیۆم-ئایۆن (Lithium-ion) لیتیۆما کانزایی تێدا نینە؛ بۆ ئاگرێ وان ئاڤ و سارکرنا بەردەوام پێشنیار دهێتە کرن.","Class K (NFPA) / Class F (EN 2) - ڕۆن و زەیتێن چێشتلێنانێ: ل مەتبەخێن ڕێستۆرانتان و مالان. ڤەمراندن: تەمرینکا Wet Chemical کو پرۆسەیا سابوونبوونێ (Saponification) دروست دکەت: ڕۆن دبیتە چینەکا وەک سابوونێ کو ئۆکسجینێ ددەتە پاش و ئاگری دڤەمرینیت. چ جاران ئاڤێ ل سەر ڕۆنێ سۆتی نەکە."]},{heading:"٨. تێبینییەکا گرنگ بۆ قوتابیان",body:"تێگەهشتن ژ هەرەما ئاگری کلیلا سەرەکی یە بۆ هلبژارتنا ماددێ ڤەمراندنێ یێ دروست. هەر ڕەگەزەک ژ چار ڕەگەزێن هەرەمێ بهێتە شکاندن، ئاگر دڤەمریت:",points:["لادانا سۆتەمەنیێ (Remove Fuel): دوورئێخستنا ماددەیێن سۆتێنەر ژ ناڤچەیا ئاگری، یان گرتنا سەرچاڤەیا غازێ.","لادانا گەرمیێ (Remove Heat): سارکرن ب ئاڤێ یان ب ماددەیێن سارکەر.","لادانا ئۆکسجینێ (Remove Oxygen): خەندقاندن و داپۆشینا ئاگری (وەک کەف یان بەتانییا ئاگری).","شکاندنا کارلێکا زنجیرەیی (Break Chain Reaction): بکارئینانا تۆزا کیمیایی یان ماددەیێن تایبەت."]}],media:[{kind:"video",src:"media/videos/uni_01_fire_dynamics.mp4",title:"داینامیکا ئاگری",description:"ڕوونکرنەکا تەمام ل سەر قۆناغێن گەشەکرنا ئاگری و چەوانیا بەلاڤبوونا وی"},{kind:"image",src:"media/images/uni_01_tetrahedron.png",title:"هەرەما ئاگری",description:"دیاگراما تەمام یا هەرەما ئاگری و چار ڕەگەزێن وێ یێن سەرەکی"},{kind:"video",src:"media/videos/uni_01_flashover.mp4",title:"دیاردەیا Flashover",description:"تاقیکرنەکا تاقیگەهی کو Flashover نیشان ددەت"},{kind:"image",src:"media/images/uni_01_heat_transfer.png",title:"شێوازێن گوهاستنا گەرمیێ",description:"Conduction، Convection و Radiation ب وێنەیان"},{kind:"video",src:"media/videos/uni_01_backdraft.mp4",title:"مەترسییا Backdraft",description:"چەوانیا ناسینا نیشانێن مەترسیێ"},{kind:"image",src:"media/images/uni_01_fire_classes.png",title:"پۆلێنکرنا ئاگری",description:"خشتەیا پۆلێن ئاگری ل دویڤ NFPA و EN 2، ب ڕەنگ و نیشانان"},{kind:"video",src:"media/videos/uni_01_extinguisher_types.mp4",title:"جۆرێن تەمرینکان",description:"چەوانیا هلبژارتن و بکارئینانا تەمرینکا دروست"}],quiz:[{question:"کیش ڕەگەز ل سەر سێگۆشەیا ئاگری دهێتە زێدەکرن دا کو ببیتە هەرەما ئاگری؟",options:[{text:"گەرمی",correct:!1},{text:"کارلێکا زنجیرەیی یا کیمیایی",correct:!0},{text:"ئۆکسجین",correct:!1},{text:"سۆتەمەنی",correct:!1}],explanation:"کارلێکا زنجیرەیی یا کیمیایی (Chemical Chain Reaction) ڕەگەزێ چارێ یە کو هەرەما ئاگری پێ تەمام دبیت. ئەڤ پرۆسەیە ئاگری بەردەوام دکەت و دهێلیت کو ب خوە بەلاڤ ببیت."},{question:"Flashover پترییا جاران د کیش قۆناغا ئاگری دا ڕوودەت؟",options:[{text:"Incipient",correct:!1},{text:"Growth",correct:!0},{text:"Fully Developed",correct:!1},{text:"Decay",correct:!1}],explanation:"Flashover ب گشتی د دووماهییا قۆناغا Growth دا ڕوودەت و ئاگری دبەتە قۆناغا Fully Developed؛ دەمێ پلەیا گەرمیێ بلند دبیت و هەمی ماددە نێزیکی خالا گڕگرتنێ دبن."},{question:"کیش غاز پترین کەسان ل ئاگران دکوژیت؟",options:[{text:"ئۆکسجین",correct:!1},{text:"مۆنۆکسیدا کاربۆنێ (CO)",correct:!0},{text:"نیترۆجین",correct:!1},{text:"هایدرۆجین",correct:!1}],explanation:"مۆنۆکسیدا کاربۆنێ (CO) سەرەکیترین غازا کوژەکە ل ئاگران، چونکی بێ بێهن و بێ ڕەنگە و ب لەز گوهاستنا ئۆکسجینێ د خوینێ دا ڕادوەستینیت."},{question:"Pyrolysis چییە؟",options:[{text:"ڤەمراندنا ئاگری",correct:!1},{text:"شیکاربوونا ماددەی ب گەرمیێ بۆ هەلمێن سۆتێنەر",correct:!0},{text:"تەقین",correct:!1},{text:"سارکرن",correct:!1}],explanation:"Pyrolysis پرۆسەیەکا کیمیایی یە کو تێدا ماددە ب گەرمیێ دشکێن و دبنە غازێن سۆتێنەر؛ ئەڤ غازە گڕ دگرن و دسۆژن."},{question:"بۆ ئاگرێ Class B (شلەمەنییێن سۆتێنەر)، کیش تەمرینک باشترە؟",options:[{text:"ئاڤ",correct:!1},{text:"کەف (Foam) یان CO₂",correct:!0},{text:"ئاخ",correct:!1},{text:"هەوا",correct:!1}],explanation:"ئاگرێ شلەمەنییێن سۆتێنەر (Class B) پێدڤی ب خەندقاندنێ هەیە. کەف یان CO₂ گونجاینە چونکی ئۆکسجینێ ژێ دبڕن. ئاڤ نەگونجایە چونکی شلەمەنییا سۆتی بەلاڤ دکەت."},{question:"کیش ژ ڤان نیشانەکا Backdraft یە؟",options:[{text:"دوکێلا سپی",correct:!1},{text:"دوکێلا زەر-قاوەیی و گەرمبوونا دەرگەهی",correct:!0},{text:"ساربوونا ژوورێ",correct:!1},{text:"ڕووناهی",correct:!1}],explanation:"Backdraft نیشانێن تایبەت هەنە: دوکێلا زەر-قاوەیی، گەرمبوونا دەرگەهی، و لڤینا پالدان و ڤەکێشانا دوکێلێ. ئەڤە نیشان ددەت کو غازێن سۆتێنەر د ژوورێ دا هەنە و چاڤەڕێی ئۆکسجینێ نە."}]},{id:2,code:"CHEM-202",icon:"FlaskConical",accent:"#9333ea",title:"سەلامەتییا ماددەیێن کیمیایی (HazMat)",subtitle:"Hazardous Materials Management & Chemical Safety",summary:"ناسینا ماددەیێن مەترسیدار، سیستەمێ جیهانی یێ GHS، ئەلماسا NFPA 704، بەرسڤدانا ڕژانا کیمیایی ل تاقیگەهـ و کارگەهان، و خوپاراستن.",blocks:[{body:`د جیهانا ئەڤرۆ دا، ئەم ڕۆژانە هەزاران ماددەیێن کیمیایی بکار دئینین: ل تاقیگەهان، کارگەهان، نەخۆشخانەیان و تەنانەت ل مالان. بەلێ گەلەک ژ ڤان ماددەیان مەترسیدارن ئەگەر ب شێوەیەکێ نەدروست بهێنە بکارئینان یان هەلگرتن. ماددەیێن کیمیایی دشێن ژەهراوی بکەن، بسۆژینن، بتەقن، یان ماددەیێن دی بخۆن و بڕزینن (Corrosion). ژبەرهندێ، هەر کەسەکێ دگەل ماددەیێن کیمیایی کار دکەت، چ قوتابییێ تاقیگەهێ بیت، چ کارمەندێ کارگەهێ یان ئەندازیار، دڤێت ب تەمامی ئاگەهداری مەترسییان و ڕێکێن خوپاراستنێ بیت.

د ڤێ مۆدیوولێ دا، ئەم دچینە د ناڤ بابەتێ سەلامەتییا کیمیایی (Chemical Safety) دا. دێ فێر بین چەوا ماددەیان ب سیستەمێن ستاندارد وەک GHS و NFPA 704 بناسین، چەوا پەڕا داتایێن سەلامەتیێ (SDS) بخوینین، و چ هەنگاڤان ل دەمێ ڕژانا کیمیایی یان ڕووداوەکێ بهاڤێژین.`},{heading:"١. سیستەمێ جیهانی یێ ناسینا مەترسییان - GHS",body:"GHS سیستەمەکێ نێڤدەولەتی یە کو ل ژێر سەرپەرشتییا نەتەوەیێن ئێکگرتی (UN) هاتییە دانان بۆ پۆلێنکرن و نیشانکرنا ماددەیێن مەترسیدار ب ئێک شێوە ل سەرانسەری جیهانێ. نەهـ هێمایێن (Pictograms) وی ئەڤەنە:",points:["Flame (گڕ): ماددەیێن سۆتێنەر (Flammable) وەک ئەسیتۆن، بەنزین و ئەلکهول.","Skull and Crossbones (کەلەسەر): ماددەیێن گەلەک ژەهراوی (Acute Toxicity).","Corrosion (خوارن): ئەسید و بازێن کو پێستی دسۆژینن و کانزایان دخۆن.","Exploding Bomb (بۆمبا تەقی): ماددەیێن تەقەمەنی یان ناجێگیر.","Exclamation Mark (نیشانا هشیاریێ): مەترسییێن ساخلەمیێ یێن سڤکتر (وەک ئێشاندنا پێستی).","Environment (ژینگەهـ): زیان ب ژینگەها ئاڤێ و زیندەوەران.","Health Hazard (مەترسییا ساخلەمیێ): مەترسییێن درێژخایەن (وەک شێرپەنجە و زیانا سییان).","Gas Under Pressure: غازێن ل ژێر فشارێ (سلیندەر).","Oxidizer: ماددەیێن ئۆکسیدکەر کو ئاگری توندتر دکەن."]},{heading:"٢. ئەلماسا NFPA 704 (Fire Diamond)",body:"سیستەمەکێ دیتنی یە بۆ ناسینا بلەز یا مەترسییان ل سەر دەرگەهـ و کۆگەهان. هەر ئێک ژ ڕەنگێن شین، سۆر و زەر ژمارەیەکا ژ ٠ هەتا ٤ هەیە (٤ = مەترسییا هەرە بلند):",points:["شین - Health Hazard (٠–٤): مەترسییا ساخلەمیێ.","سۆر - Flammability (٠–٤): مەترسییا گڕگرتنێ.","زەر - Instability (٠–٤): ناجێگیری و کارلێککرن.","سپی - Special Hazards: W (ب ئاڤێ کارلێکەکا مەترسیدار دکەت)، OX (ئۆکسیدکەر)، SA (غازا خەندقێنەر یا سادە - Simple Asphyxiant)."]},{heading:"٣. پەڕا داتایێن سەلامەتیێ - SDS (١٦ بەش)",body:"هەر ماددەیەکێ کیمیایی یێ مەترسیدار دڤێت SDS یا خوە هەبیت. گرنگترین بەشێن وێ بۆ بەرسڤدانا تەنگاڤیێ:",points:["بەشێ ١: ناسینا ماددەی (Identification).","بەشێ ٢: ناسینا مەترسییان (Hazard Identification).","بەشێ ٣: پێکهاتە (Composition).","بەشێ ٤: هەوارهاتنا ئێکێ (First Aid).","بەشێ ٥: ڕێکارێن ئاگرکوژاندنێ (Fire-fighting Measures).","بەشێ ٦: ڕێکارێن ڕژانا نەخوازیاری (Accidental Release).","بەشێ ٧: هەلگرتن و بکارئینان (Handling and Storage).","بەشێ ٨: کۆنترۆلا بەرکەفتنێ و کەرەستەیێن خوپاراستنێ (PPE)."]},{heading:"٤. پرۆتۆکۆلا C.L.E.A.N بۆ ڕژانا کیمیایی",body:"هەنگاڤێن ڕێکخستی بۆ کۆنترۆلکرنا ڕژانەکا بچووک؛ بەری تو نێزیکی ڕژانێ ببی، ماددەی بناسە و PPE لبەر بکە. تێبینییا گرنگ: ئەگەر ڕژان مەزن بیت، ماددە نەدیار یان گەلەک ژەهراوی بیت، یان بێهن یان ئاگر هەبیت، کۆنترۆلێ ب خوە نەکە: جهی ڤالا بکە و پەیوەندیێ ب ١١٥ بکە.",points:["C - Contain: بەرگرتن و ڕێگرتن ل بەلاڤبوونا ڕژانێ.","L - Locate: دیتنا SDS و ناسینا ماددەی.","E - Evaluate: هەلسەنگاندن: ئەرێ ئەز ب سەلامەتی دشێم ب خوە پاقژ بکەم، یان پێدڤی ب تیمێ تایبەت هەیە؟","A - Access: ئامادەکرنا PPE یا گونجای و سندۆقا ڕژانێ (Spill Kit).","N - Notify: ئاگەهدارکرنا بەرپرسی و تۆمارکرنا ڕووداوی."]},{heading:"٥. کەرەستەیێن پاراستنا کەسی (PPE)",body:"جۆرێن PPE بۆ کارکرن دگەل ماددەیێن کیمیایی؛ هلبژارتنا دروست ل دویڤ بەشێ ٨ یێ SDS دبیت:",points:["دەستکێش: نیتریل یان نیۆپرین بۆ پترییا ماددەیێن کیمیایی؛ جۆرێ دروست ل دویڤ SDS و خشتەیا گونجانێ (Chemical Resistance Chart).","چاڤیلکێن سەلامەتیێ دگەل پاراستنا لایان (Side Shields)، یان چاڤیلکێن داخستی (Goggles) بۆ مەترسییا پژاندنێ.","پاراستنا هەناسێ: ماسکا N95 تەنێ تەنۆلکێن هوور ڕادگریت و چ پاراستنێ ژ هەلم و غازێن کیمیایی نادەت. بۆ هەلم و غازان، ڕێسپیراتۆرا ب فلتەرێن (Cartridges) گونجای بۆ وی ماددەی ل دویڤ SDS پێدڤییە؛ بۆ ماددەیێن نەدیار، چڕییێن بلند یان کێمییا ئۆکسجینێ، تەنێ ئامێرێ هەناسێ یێ سەربەخۆ (SCBA).","کراسێ تاقیگەهێ: دژە-ئاگر (Flame-resistant) ل جهێن ماددەیێن سۆتێنەر.","پێلاڤێن داخستی کو هەمی پێی دپارێزن."]},{heading:"٦. هەلگرتنا ماددەیێن کیمیایی (Chemical Storage)",body:"ڕێسایێن هەلگرتنا سەلامەت:",points:["جوداکرن: ئەسید ژ بازان دوور، و ماددەیێن ئۆکسیدکەر ژ ماددەیێن سۆتێنەر دوور.","پلەیا گەرمیێ: ئەگەر ماددەیێن سۆتێنەر پێدڤی ب سارکرنێ هەبن، تەنێ د سەلاجەیێن تایبەت یێن دژە-تەقینێ دا بهێنە هەلگرتن، نە د سەلاجەیێن ئاسایی دا.","قفلکرن: ماددەیێن ژەهراوی د دۆلابێن قفلکری دا.","نیشانکرن: هەمی شووشە و دەفران ب ناڤ و هێمایێن GHS.","ڕەفێن خوارێ: ماددەیێن گران و دەفرێن شووشەیی ل ڕەفێن نزم."]}],media:[{kind:"image",src:"media/images/uni_02_ghs_symbols.png",title:"هێمایێن GHS",description:"لیستا تەمام یا هێمایێن جیهانی"},{kind:"video",src:"media/videos/uni_02_spill_cleanup.mp4",title:"پاقژکرنا ڕژانێ",description:"بکارئینانا سندۆقا ڕژانێ (Spill Kit)"},{kind:"image",src:"media/images/uni_02_nfpa704.png",title:"NFPA 704",description:"ڕوونکرنا ڕەنگ و ژمارەیان"},{kind:"video",src:"media/videos/uni_02_ppe_demo.mp4",title:"لبەرکرنا PPE",description:"ڕێکا دروست یا لبەرکرن و ژبەرکرنێ"}],quiz:[{question:"ل NFPA 704، ڕەنگێ شین نیشانا چییە؟",options:[{text:"ئاگر",correct:!1},{text:"کارلێککرن",correct:!1},{text:"ساخلەمی",correct:!0},{text:"مەترسییێن تایبەت",correct:!1}],explanation:"شین نیشانا مەترسییێن ساخلەمیێ یە (Health Hazard)."},{question:"کیش بەشێ SDS باسێ هەوارهاتنا ئێکێ دکەت؟",options:[{text:"بەشێ ١",correct:!1},{text:"بەشێ ٤",correct:!0},{text:"بەشێ ٩",correct:!1},{text:"بەشێ ١١",correct:!1}],explanation:"بەشێ ٤ (Section 4) تایبەتە ب ڕێکارێن هەوارهاتنا ئێکێ (First Aid Measures)."},{question:"پیتا «C» ل C.L.E.A.N نیشانا چییە؟",options:[{text:"Clean",correct:!1},{text:"Contain",correct:!0},{text:"Call",correct:!1},{text:"Check",correct:!1}],explanation:"C = Contain: بەرگرتن و ڕێگرتن ل بەلاڤبوونا ڕژانێ."},{question:"بۆ کارێ گشتی یێ تاقیگەهێ دگەل پترییا ماددەیێن کیمیایی، کیش دەستکێش باشترین هلبژارتنە؟",options:[{text:"لاتێکس",correct:!1},{text:"نیتریل",correct:!0},{text:"پەمبوو",correct:!1},{text:"بێ دەستکێش",correct:!1}],explanation:"دەستکێشێن نیتریل بۆ پترییا ماددەیێن کیمیایی هلبژارتنەکا گشتی یا باشن؛ بەلێ بۆ هەر ماددەیەکێ تایبەت، جۆرێ دروست ل دویڤ SDS و خشتەیا گونجانێ دهێتە هلبژارتن."}]},{id:3,code:"ELEC-305",icon:"Zap",accent:"#ca8a04",title:"سەلامەتییا کارەبایێ و ڤۆلتاژا بلند",subtitle:"Electrical Safety, Arc Flash & High Voltage",summary:"شیکارکرنا مەترسییێن کارەبایێ، کارتێکرنا تەزووێ ل سەر لەشێ مرۆڤی، دیاردەیا Arc Flash، ستانداردێ LOTO، و یاسایا Ohm بۆ پاراستنێ.",blocks:[{body:"کارەبا ئێکە ژ مەزنترین دەستکەفتییێن مرۆڤایەتیێ، بەلێ د هەمان دەمی دا هێزەکا بێ دەنگ و مەترسیدارە. هەر سال ل سەرانسەری جیهانێ گەلەک کەس ب ئەگەرێ شۆکا کارەبایێ گیانێ خوە ژ دەست ددەن یان بریندار دبن. پترییا ڤان ڕووداوان ل کارگەهان، پرۆژەیێن ئاڤاهیسازیێ و تەنانەت ل مالان ژی ڕوودەن، ژبەر کەمتەرخەمی یان نەزانینێ."},{heading:"١. بنەمایێن فیزیایی و یاسایا Ohm",body:"یاسایا Ohm بنەمایێ سەرەکی یێ شیکارکرنا کارەبایێ یە:",points:["I = V / R (تەزوو = ڤۆلتاژ ÷ بەرگری).","ڤۆلتاژ: هێزا پالدانا ئەلەکترۆنان.","بەرگری: لەشێ تەڕ = بەرگرییا کێمتر = تەزوو و مەترسییا پتر.","ئەمپێر (تەزوو): ئەوە یا مرۆڤی دکوژیت، نە ڤۆلتاژ تەنێ."]},{heading:"٢. کارتێکرنا بایۆلۆژی یا تەزووێ",body:"کارتێکرنا تەزووێ ل سەر لەشی (نێزیکی، بۆ کارەبایا AC یا ٥٠–٦٠ Hz):",points:["١ mA: هەستپێکرن.","١٠–٢٠ mA: سنوورێ بەردانێ (Let-go Threshold): مرۆڤ نەشێت دەستێ خوە ژ سەرچاڤەیێ بەردەت.","٥٠–١٠٠ mA: ئەگەرا لێدانا نەڕێک یا دلی (Ventricular Fibrillation).","١٠٠+ mA: ڕاوەستانا دلی و سۆتنێن ناڤخۆیی ب ئەگەرەکا بلندتر."]},{heading:"٣. دیاردەیا Arc Flash",body:"تەقینەکا وزەیێ یە د ناڤبەرا گەهێنەران دا:",points:["گەرمی: دشێت بگەهیتە نێزیکی ١٩٬٤٠٠ پلەیێن سیلیزی (نێزیکی چار جاران گەرمتر ژ ڕووێ ڕۆژێ).","Arc Blast: پێلا فشارا هەوایێ و پارچەیێن فڕیای.","تیشکدان و ڕووناهییا توند: زیانا چاڤان، کۆرەبوونا دەمکی یان هەمیشەیی.","ئەگەرێن سەرەکی یێن برینداربوونێ: کارکرن ل سەر ئامێرێن ب کارەبا ڤە، ئامرازێن کەفتی، و نەبوونا PPE یا گونجای."]},{heading:"٤. ستانداردێ LOTO (Lockout/Tagout)",body:"پرۆتۆکۆلا سەلامەتیێ ل دەمێ چاککرنێ (ل دویڤ OSHA 1910.147):",points:["Lockout: قفلکرنا سەرچاڤەیا وزەیێ.","Tagout: کارتا هشیاریێ (ناڤ، دەم، ئەگەر).","Zero Energy: پشتڕاستبوون ب ئامێرێ پێڤانا ڤۆلتاژێ (Voltmeter) کو چ وزە نەمایە."]},{heading:"٥. کەرەستەیێن پاراستنا کەسی (Electrical PPE)",body:"کەرەستەیێن پاراستنا کەسی بۆ کارێ کارەبایێ:",points:["دەستکێشێن عازل (Class 0/1).","ڕووپۆشا دژە-قەوسێ (Arc-Rated Face Shield).","جلوبەرگێن دژە-قەوسێ (Arc-Rated).","پێلاڤێن عازل (EH Rated)."]},{heading:"٦. هەوارهاتنا ئێکێ بۆ شۆکا کارەبایێ",body:"هەنگاڤێن هەوارهاتنێ:",points:["پێشی سەرچاڤەیا کارەبایێ ببڕە؛ هەتا کارەبا نەهێتە بڕین، دەستێ خوە نەدە کەسێ بریندار.","پەیوەندیێ ب ١٢٢ (ئەمبوولانس) بکە؛ ئەگەر وایەرێن کەفتی یان ئاگر هەبن، ب ١١٥ ژی.","ئەگەر کەس بێ هش بوو و هەناسەیا ئاسایی نەبوو، ئێکسەر فشارا سنگی (CPR) دەست پێ بکە و AED بکار بینە.","سۆتنان ب ئاڤا ڕەوان یا فێنک ٢٠ خولەکان سار بکە؛ هەر کەسەکێ شۆکا کارەبایێ لێ دابیت دڤێت ب پزیشکی بهێتە پشکنین."]}],media:[{kind:"video",src:"media/videos/uni_03_loto_steps.mp4",title:"هەنگاڤێن LOTO",description:"قفلکرن و نیشانکرن"},{kind:"image",src:"media/images/uni_03_arc_flash.png",title:"سنوورێن Arc Flash",description:"مەودایێن سەلامەتیێ"},{kind:"video",src:"media/videos/uni_03_grounding.mp4",title:"Grounding",description:"گرنگییا وایەرێ عەردی"}],quiz:[{question:"کێمترین ڕێژەیا تەزووێ کو دشێت ببیتە ئەگەرێ Ventricular Fibrillation چەندە؟",options:[{text:"١ mA",correct:!1},{text:"١٠ mA",correct:!1},{text:"٥٠–١٠٠ mA",correct:!0},{text:"٥٠٠٠ mA",correct:!1}],explanation:"٥٠–١٠٠ میلی ئەمپێر دشێت ببیتە ئەگەرێ لێدانا نەڕێک یا دلی."},{question:"ئارمانجا LOTO چییە؟",options:[{text:"کێمکرنا خەرجییان",correct:!1},{text:"بڕینا وزەیێ و ڕێگرتن ل ڤەگەڕانا وێ",correct:!0},{text:"زێدەکرنا ڤۆلتاژێ",correct:!1},{text:"پاقژکرن",correct:!1}],explanation:"LOTO پشتڕاست دکەت کو ل دەمێ چاککرنێ چ وزە د ئامێری دا نەمایە."},{question:"بەرگرییا لەشی چەوا دگوهۆڕیت؟",options:[{text:"هەردەم وەک خوە دمینیت",correct:!1},{text:"ب تەڕبوونێ زێدە دبیت",correct:!1},{text:"ب تەڕبوونێ کێم دبیت",correct:!0},{text:"چ پەیوەندی نینە",correct:!1}],explanation:"دەمێ پێست تەڕ دبیت، بەرگری کێم دبیت و تەزوو و مەترسی زێدە دبن."}]},{id:4,code:"MED-401",icon:"HeartPulse",accent:"#e11d48",title:"هەوارهاتنا ئێکێ یا پێشکەفتی و فشارا سنگی (CPR)",subtitle:"Advanced First Aid, CPR & Trauma Management",summary:"پرۆتۆکۆلا DRABCDE، ڤەژاندنا دل و سییان (CPR) ل دویڤ ڕێنماییێن AHA 2025، بکارئینانا ئامێرێ AED، ڕاگرتنا خوینبەربوونا مەترسیدار (Stop the Bleed)، و پۆلێنکرنا برینداران (Triage).",blocks:[{body:"هەوارهاتنا ئێکێ نە تەنێ کارەکێ مرۆڤانە یە، بەلکو زانستەکێ هوورە کو د ناڤبەرا ژیان و مرنێ دا بڕیارێ ددەت. د بوارێ تەنگاڤیێ دا، ئەم باسێ «دەمژمێرا زێڕین» (Golden Hour) و «دەهـ خولەکێن پلاتینی» (Platinum Ten Minutes) دکەین: هندی بریندار زووتر بگەهیتە چارەسەرییێ، شانسێ ڕزگاربوونێ پتر دبیت. د هەمی حالەتێن پزیشکی دا، پەیوەندیێ ب ١٢٢ (ئەمبوولانس) بکە."},{heading:"١. پرۆتۆکۆلا DRABCDE",body:"زنجیرەیا سەرەکی یا هەلسەنگاندنا برینداری:",points:["D - Danger: پشکنینا مەترسیێ بۆ تە و بۆ برینداری.","R - Response: ئاستێ هشیاریێ (AVPU).","A - Airway: ڤەکرنا ڕێکا هەناسێ ب Head Tilt یان Jaw Thrust.","B - Breathing: پشکنینا هەناسەدانا ئاسایی، نە پتر ژ ١٠ چرکەیان؛ ئەگەر کەس بێ هش بوو و هەناسەیا ئاسایی نەبوو، ئێکسەر CPR دەست پێ بکە ب فشارێن سنگی (ڕێزبەندییا C-A-B).","C - Circulation: پشکنینا خوینبەربوونا مەترسیدار و نیشانێن شۆکێ (پشکنینا نەبزا Carotid بۆ کارمەندێن پزیشکی).","D - Disability: پشکنینا ئاستێ هشیاریێ، چاڤان و لڤینا دەست و پێیان.","E - Exposure: پشکنینا گشتی یا لەشی و داپۆشین بۆ پاراستنێ ژ سەرمایێ."]},{heading:"٢. CPR ب کوالیتییەکا بلند",body:"ڕێنماییێن AHA 2025:",points:["جه: نیڤا خوارێ یا هەستیێ سنگی.","کویراتی: ٥–٦ سم بۆ هەمی مەزنان؛ نێزیکی ٥ سم بۆ زارۆکان؛ نێزیکی ٤ سم بۆ ساڤایان (سێیەکا کویراتییا سنگی). بۆ ساڤایان: هەردوو تبلێن مەزن ب دەورلێگرتنا سنگی، یان بنێ ئێک دەستی؛ ڕێکا دوو تبلان ئێدی ناهێتە پێشنیارکرن.","لەز: ١٠٠–١٢٠ فشار د خولەکێ دا.","Recoil: پشتی هەر فشارەکێ، بهێلە سنگ ب تەمامی بزڤڕیتە جهێ خوە.","ڕێژە: ٣٠:٢ (فشار:هەناسە)؛ بۆ زارۆک و ساڤایان دگەل دوو هەوارهاتیان ١٥:٢."]},{heading:"٣. بکارئینانا AED",body:"ئامێرێ دیفیبریلاتۆرێ ئۆتۆماتیکی یێ دەرەکی:",points:["ئامێری ڤەکە و گوهێ خوە بدە ڕێنماییێن وی.","«Stand Clear»: چ کەس دەستێ خوە نەدەتە بریندار.","شۆکێ بدە، و ئێکسەر CPR دووبارە دەست پێ بکە."]},{heading:"٤. ڕاگرتنا خوینبەربوونا مەترسیدار (Stop the Bleed)",body:"پێشی سەلامەتییا جهی پشتڕاست بکە و پەیوەندیێ ب ١٢٢ بکە، پاشان ب ڤێ ڕێزبەندیێ:",points:["فشارا ڕاستەوخۆ: ب هەردوو دەستان فشارەکا ب هێز و بەردەوام ل سەر برینێ بدە. ئەگەر برین کویر بیت، برینێ ب گازێ یان قوماشەکێ پاقژ تژی بکە (Wound Packing) و فشارێ بەردەوام بکە. ئەگەر پێچان ب خوینێ تەڕ بوو، وێ لانەدە؛ پێچانەکا دی ل سەر زێدە بکە.","تۆرنیکێت (Tourniquet): بۆ خوینبەربوونا مەترسیدار یا دەست و پێیان زوو بکار بینە، ٥–٧ سم ل سەر برینێ (نە ل سەر جومگەیێ)؛ هندێ بادە هەتا خوین ڕادوەستیت، دەمێ دانانێ بنڤیسە، و چ جاران سست نەکە.","شۆک: بریندار ل سەر پشتێ درێژ بکە، گەرم داپۆشە، و چ خوارن یان ڤەخوارن نەدەیێ؛ ل حالەتێن برینداربوونێ (Trauma) پێیان بلند نەکە."]},{heading:"٥. START Triage",body:"پۆلێنکرنا برینداران ل کارەساتێن ب گەلەک بریندار:",points:["سۆر (Immediate): ژیان د مەترسیێ دایە - ئەولەوییەتا ئێکێ.","زەر (Delayed): برینا گران بەلێ دشێت کێمەکێ چاڤەڕێ بکەت.","کەسک (Minor): برینێن سڤک - دشێت ب پێیان بچیت.","ڕەش (Expectant/Deceased): پشتی ڤەکرنا ڕێکا هەناسێ ژی هەناسە نادەت."]}],media:[{kind:"video",src:"media/videos/uni_04_cpr_full.mp4",title:"CPR",description:"ڕێنماییێن AHA 2025"},{kind:"image",src:"media/images/uni_04_jaw_thrust.png",title:"Jaw Thrust",description:"بۆ گۆمانا برینداربوونا ستووی و ستوینا پشتێ"},{kind:"video",src:"media/videos/uni_04_triage_sim.mp4",title:"Triage",description:"پۆلێنکرنا برینداران"},{kind:"image",src:"media/images/uni_04_tourniquet.png",title:"تۆرنیکێت",description:"جه و شێوازێ دانانێ (٥–٧ سم ل سەر برینێ)"}],quiz:[{question:"ل گۆمانا برینداربوونا ستووی، تو چەوا ڕێکا هەناسێ ڤەدکەی؟",options:[{text:"Head Tilt",correct:!1},{text:"Jaw Thrust",correct:!0},{text:"لڤاندنا سەری",correct:!1},{text:"چ تشت",correct:!1}],explanation:"Jaw Thrust ڕێکا هەناسێ ڤەدکەت بێ کو ستوو بلڤیت."},{question:"ڕێژەیا فشاران بەرامبەر هەناسان د CPR یا مەزنان دا چەندە؟",options:[{text:"١٥:٢",correct:!1},{text:"٣٠:٢",correct:!0},{text:"١٠٠:٥",correct:!1},{text:"٣٠:١",correct:!1}],explanation:"ستاندارد بۆ مەزنان: ٣٠ فشار بەرامبەر ٢ هەناسەیان (١٥:٢ بۆ زارۆک و ساڤایان دگەل دوو هەوارهاتیان)."},{question:"ل START Triage، کەسێ کو پشتی ڤەکرنا ڕێکا هەناسێ ژی هەناسە نادەت، کیش ڕەنگی وەردگریت؟",options:[{text:"سۆر",correct:!1},{text:"زەر",correct:!1},{text:"ڕەش",correct:!0},{text:"کەسک",correct:!1}],explanation:"ڕەش (Expectant/Deceased): ئەگەر پشتی ڤەکرنا ڕێکا هەناسێ ژی هەناسە نەدا."},{question:"لەزا فشارێن سنگی د CPR دا چەندە؟",options:[{text:"٦٠–٨٠",correct:!1},{text:"٨٠–١٠٠",correct:!1},{text:"١٠٠–١٢٠",correct:!0},{text:"١٤٠–١٦٠",correct:!1}],explanation:"١٠٠–١٢٠ فشار د خولەکێ دا."}]},{id:5,code:"STRUC-500",icon:"Building2",accent:"#0891b2",title:"ئەندازیارییا سەلامەتییا ئاڤاهیان",subtitle:"Building Safety, Fire Codes & Life Safety Systems",summary:"کۆدێن ئەندازیاری (IBC/NFPA)، سیستەمێن ئاگەهدارکرن و ئاگرکوژاندنێ، دەرگەهێن دژە-ئاگر، و دیزاینا ڕێڕەوێن دەرکەفتنا تەنگاڤیێ.",blocks:[{body:"ئاڤاهی نە تەنێ جهەکێ ژیان و کاری یە، بەلکو دڤێت وەک «سیستەمەکێ پاراستنا ژیانێ» بهێتە دیزاینکرن. گەلەک کارەساتێن ئاگری نیشان ددەن کو کێماسییێن ئەندازیاری، وەک دەرکەفتنێن گرتی یان نەبوونا دابەشکرنا ئاگری، ڕێگرییێ ل دەرکەفتنا بلەز دکەن و ژمارەیا قوربانییان زێدە دکەن. ژبەر هندێ، دیزاینا دروست کو سیستەمێن ئاگەهدارکرنێ، ئاگرکوژاندنا ئۆتۆماتیکی و ماددەیێن دژە-ئاگر بگریتە خوە، دشێت د ناڤبەرا ژیان و مرنێ دا جیاوازییێ دروست بکەت. د ڤێ مۆدیوولێ دا، ئەم دێ باسێ کۆدێن نێڤدەولەتی یێن وەک NFPA 101 و IBC کەین."},{heading:"١. کۆدێن ئاڤاهیسازیێ و سەلامەتییا جیهانی",body:"کۆد (Code) زنجیرەکا ڕێسایێن تەکنیکی یە کو ستانداردێن دیزاین و ئاڤاکرنێ دیار دکەت. دوو کۆدێن سەرەکی ل گەلەک وەلاتان دهێنە پەیڕەوکرن:",points:["IBC (International Building Code): کۆدا نێڤدەولەتی یا ئاڤاهیسازیێ یە کو لایەنێن ستراکچەری، پاراستنا ژ ئاگری و سەلامەتییا ژیانێ دگریتە خوە (کارەبا و میکانیک ب کۆدێن جودا وەک NEC و IMC دهێنە ڕێکخستن). ئەڤ کۆدە دیار دکەت کا ستوون و دیوارێن ئاڤاهی دڤێت چەند دەمژمێران بەرگرییێ ل هەمبەر ئاگری بکەن (Fire-Resistance Rating).","NFPA 101 (Life Safety Code): تایبەتە ب پاراستنا ژیانا مرۆڤی. ئەڤ ستانداردە ڕێنماییان ل سەر پانییا دەرگەهان، درێژییا ڕێڕەوان و ڕووناهییا تەنگاڤیێ (Emergency Lighting) ددەت.","جۆرێن ئاڤاکرنێ (Construction Types): IBC ئاڤاهییان دابەش دکەتە سەر پێنج جۆران. جۆرێ ئێکێ (Type I) کو ژ کۆنکریت و ئاسنێ پاراستی یە، بلندترین بەرگری هەیە، و جۆرێ پێنجێ (Type V) کو ژ دارێ یە، کێمترین بەرگری هەیە.","بارێ ئاکنجیبوونێ (Occupant Load): هەژمارکرنا پترین ژمارەیا کەسێن کو دشێن د ئێک دەمی دا د ئاڤاهی دا هەبن، دا کو بهێتە زانین کا چەند دەرکەفتن (Exits) و چەند پانی پێدڤی نە."]},{heading:"٢. دابەشکرنا ئاگری و دیوارێن دژە-ئاگر (Compartmentation)",body:"ئارمانجا ڤێ ستراتیژیێ ئەوە کو ئاڤاهی بهێتە دابەشکرن بۆ چەند پشکێن جودا (Fire Compartments) دا کو ئاگر نەشێت ب ساناهی ژ پشکەکێ بچیتە یا دی:",points:["Fire Walls: دیوارێن تایبەتن کو ل دویڤ دەمژمێران (ب گشتی ٢ هەتا ٤ دەمژمێران) دهێنە هەلسەنگاندن. ئەڤ دیوارە ناهێلن گەرمی و غازێن سۆتێنەر د ناڤبەرا پشکێن ئاڤاهی دا بلڤن.","Fire Doors: دەرگەهێن دژە-ئاگر کو دڤێت ب خوە بهێنە داخستن (Self-closing) و چ جاران ب کۆسپەکێ ڤەکری نەهێنە هێلان. ئەڤ دەرگەهە ڕێگرییێ ل چوونا دوکێلێ بۆ ناڤ پلەکانان (Stairwells) دکەن.","Fire Dampers: دەرگەهۆکێن ئۆتۆماتیکی د ناڤ بۆرییێن هەواگوهۆڕینێ (HVAC) دا، کو ل دەمێ بلندبوونا گەرمیێ ب خوە دهێنە داخستن دا کو دوکێل و ئاگر ب ڕێکا بۆرییان بەلاڤ نەبن.","Firestopping: گرتنا هەمی کون و قەلشێن ناڤ دیوار و بنمالان، کو کابلێن کارەبایێ یان بۆری تێڕا دچن، ب ماددەیێن دژە-ئاگر."]},{heading:"٣. سیستەمێن ئاگرکوژاندنا ئۆتۆماتیکی (Suppression Systems)",body:"ئەڤ سیستەمە بێ دەستێوەردانا مرۆڤی کار دکەن و دبنە ئەگەرێ کۆنترۆلکرنا بلەز یا ئاگری:",points:["Automatic Sprinklers: ئێک ژ کاریگەرترین سیستەمانە؛ ل دویڤ ڕاپۆرتا NFPA (U.S. Experience with Sprinklers)، ل مالێن خودان Sprinkler ڕێژەیا مرنێ ل ئاگران نێزیکی ٨٩٪ کێمتر بوو. تەنێ ئەو سەرێن (Heads) کار دکەن یێن گەرمی گەهشتییێ.","Sprinkler Bulbs: ڕەنگێ شلەمەنییا ناڤ بلبا شووشەیی پلەیا گەرمیا شکاندنا وێ دیار دکەت (سۆر = ٦٨ پلەیێن سیلیزی، کو باوترین جۆرە).","Dry Pipe و Wet Pipe: ل جهێن گەلەک سار (وەک کۆگەهێن سارکری) سیستەمێ Dry Pipe دهێتە بکارئینان دا کو ئاڤ د ناڤ بۆرییان دا نەقەرسیت.","Clean Agent Systems: بکارئینانا غازێن وەک FM-200 (HFC-227ea) یان FK-5-1-12 (ناڤێ بازرگانی Novec 1230) ل ژوورێن سێرڤەران و مۆزەخانەیان، دا کو ئاڤ زیانێ نەگەهینیتە ئامێر و بەلگەنامەیان."]},{heading:"٤. سیستەمێن ئاگەهدارکرنێ (Fire Alarm Systems)",body:"ئەڤە مێشکێ سەلامەتییا ئاڤاهی یە، و ئەرکێ وی دیتنا ئاگری و ئاگەهدارکرنا خەلکی یە (NFPA 72):",points:["FACP (Control Panel): ناڤەندا کۆنترۆلێ یە کو سیگنالان ژ هەستەڤەران وەردگریت و فەرمانا لێدانا زەنگان و ئاگەهدارکرنا ناڤەندا ئاگرکوژاندنێ ددەت.","Smoke Detectors: دوو جۆرێن سەرەکی هەنە: Photoelectric کو بۆ ئاگرێن هێدی و دوکێلدار باشترە، و Ionization کو بۆ ئاگرێن بلەز و گڕدار باشترە.","Notification: بکارئینانا زەنگێن بلند (Horns) دگەل ڕووناهییێن فلاشێ (Strobes) بۆ وان کەسێن کێشەیا گوهـ هەی.","Emergency Power: ل دەمێ بڕینا کارەبایێ، سیستەم دڤێت ل سەر باترییان کار بکەت: ٢٤ دەمژمێران ل حالەتێ ئامادەباشیێ و پاشان ٥ خولەکان ل حالەتێ زەنگلێدانێ (NFPA 72)."]},{heading:"٥. ڕێڕەوێن دەرکەفتنا تەنگاڤیێ (Means of Egress)",body:"دیزاینکرنا ڕێکا دەرکەفتنێ ژ هەر خالەکا ئاڤاهی بۆ دەرڤە پێدڤی ب پەیڕەوکرنا ڤان خالان هەیە:",points:["Exit Access: ڕێکا ژ ناڤ ژوورێ هەتا دەرگەهێ دەرکەفتنێ. دڤێت چ ئاستەنگ (کورسی، مێز، کەلوپەل) د ڤان ڕێڕەوان دا نەبن.","Exit Capacity: پانییا دەرگەهـ و پلەکانان دڤێت ل دویڤ ژمارەیا خەلکی بیت. ب گشتی پانییا ڕێڕەوان لایێ کێم ١.١٢ مەتر (٤٤ ئینچ) یە، و ٠.٩١ مەتر (٣٦ ئینچ) تەنێ بۆ جهێن ب کێمتر ژ ٥٠ کەسان (IBC).","Direction of Travel: دەرگەهێن دەرکەفتنێ یێن ٥٠ کەس یان پتر بکار دئینن (و جهێن مەترسییا بلند) دڤێت بەرەڤ ئاراستەیا دەرکەفتنێ (Outward) ڤەببن دا کو پالەپەستۆیا خەلکی دەرگەهی نەگریت. هەمی دەرگەهێن دەرکەفتنێ دڤێت ژ ناڤڤە بێ کلیل ڤەببن.","Exit Signs: نیشانێن دەرکەفتنێ یێن ڕووناهیدار کو د تاریاتیێ دا ژی دیار بن، و دڤێت ژ هەمی ئاراستەیان بهێنە دیتن.","Dead-end Corridors: درێژییا ڕێڕەوێن گرتی (کو ناگەهنە دەرکەفتنەکێ) ب گشتی نابیت ژ ٦ مەتران (٢٠ پێ) پتر بیت؛ ل هندەک ئاڤاهیێن خودان Sprinkler دشێت پتر بیت."]},{heading:"٦. سەلامەتی ل ئاڤاهیێن بلند (High-Rise Safety)",body:"ئاڤاهیێن کو نهۆما وان یا ئاکنجی ژ ٢٣ مەتران (٧٥ پێ) بلندتر بیت، مەترسییێن تایبەت هەنە، ژبەر هندێ پێدڤی ب ڤان سیستەمان هەیە:",points:["Smoke Control: سیستەمێ فشارکرنا هەوایێ (Pressurization) د ناڤ پلەکانان دا، دا کو دوکێل نەچیتە ژوور و خەلک نەخەندقن.","Fire Command Center: ژوورەکا تایبەت ل نهۆما عەردی کو تیمێن ئاگرکوژاندنێ بکار دئینن بۆ کۆنترۆلکرنا سیستەمێن هەمی ئاڤاهی.","Fire Service Access Elevator: ئەسانسۆرێن تایبەت کو ل دەمێ تەنگاڤیێ تەنێ ئاگرکوژ دشێن بکار بینن.","Area of Refuge: جهێن پاراستی ل نهۆمێن بلند بۆ وان کەسێن خودان پێدڤییێن تایبەت کو نەشێن ب پلەکانان بهێنە خوارێ."]}],media:[{kind:"video",src:"media/videos/uni_05_sprinkler_test.mp4",title:"تاقیکرنا Sprinkler",description:"چەوانیا شکاندنا بلبا شووشەیی ل ژێر کارتێکرنا گەرمیێ"},{kind:"image",src:"media/images/uni_05_egress_plan.png",title:"پلانا دەرکەفتنێ",description:"دیزاینا ستاندارد بۆ ڕێڕەوێن دەرکەفتنێ ل دویڤ NFPA"},{kind:"video",src:"media/videos/uni_05_fire_damper.mp4",title:"کارکرنا Fire Damper",description:"ڕێگرتن ل بەلاڤبوونا ئاگری د ناڤ بۆرییێن هەواگوهۆڕینێ دا"}],quiz:[{question:"ل دویڤ کۆدێن ئەندازیاری، دەرگەهێن دەرکەفتنا تەنگاڤیێ (Exit Doors) یێن جهێن قەرەبالغ دڤێت بەرەڤ کیش لای ڤەببن؟",options:[{text:"بەرەڤ ژوورڤە",correct:!1},{text:"بەرەڤ دەرڤە (ئاراستەیا دەرکەفتنێ)",correct:!0},{text:"ب شێوەیێ خشۆک (Sliding)",correct:!1},{text:"چ جیاوازی نینە",correct:!1}],explanation:"دڤێت بەرەڤ دەرڤە (ئاراستەیا دەرکەفتنێ) ڤەببن دا کو ئەگەر پالەپەستۆیا خەلکی هەبیت، دەرگەهـ ب ساناهی ڤەببیت و نەبیتە ئاستەنگ. دەرگەهـ دڤێت ژ ناڤڤە بێ کلیل ڤەببیت."},{question:"ئارمانجا سەرەکی ژ سیستەمێ Pressurization د ناڤ پلەکانان (Stairwells) دا چییە؟",options:[{text:"سارکرنا ئاڤاهی",correct:!1},{text:"ڕێگرتن ل چوونا دوکێلێ بۆ ناڤ ڕێکا دەرکەفتنێ",correct:!0},{text:"زێدەکرنا ڕووناهییێ",correct:!1},{text:"ڤەمراندنا ئاگری ب هەوایێ",correct:!1}],explanation:"ئەڤ سیستەمە د پلەکانان دا فشارەکا هەوایێ یا بلندتر دروست دکەت دا کو دوکێل نەشێت بچیتە ژوور، و ب ڤی ڕەنگی ڕێکا دەرکەفتنێ پاقژ دمینیت."},{question:"ڕەنگێ سۆر ل بلبا شووشەیی یا Sprinkler نیشانا چییە؟",options:[{text:"پلەیا گەرمیا ٦٨ پلەیێن سیلیزی",correct:!0},{text:"پلەیا گەرمیا ١٤١ پلەیێن سیلیزی",correct:!1},{text:"تەنێ بۆ جوانیێ یە",correct:!1},{text:"نیشانا هەبوونا غازێ یە",correct:!1}],explanation:"ڕەنگێ سۆر باوترین جۆرە و ل پلەیا ٦٨ پلەیێن سیلیزی دشکێت و ئاڤێ دپژینیت."},{question:"ل دویڤ IBC، کیش جۆرێ ئاڤاکرنێ (Construction Type) بلندترین بەرگرییا دژی ئاگری هەیە؟",options:[{text:"Type V (Wood Frame)",correct:!1},{text:"Type III (Ordinary)",correct:!1},{text:"Type I (Fire-Resistive)",correct:!0},{text:"Type IV (Heavy Timber)",correct:!1}],explanation:"Type I ژ کۆنکریت و ئاسنێ پاراستی دهێتە ئاڤاکرن و دهێتە دیزاینکرن دا کو چەند دەمژمێران ل هەمبەر ئاگرەکێ توند بەرگرییێ بکەت بێ کو هەرفیت."}]},{id:6,code:"LAW-600",icon:"Scale",accent:"#475569",title:"یاسا و بەرپرسیارییا یاسایی",subtitle:"Legal Responsibilities, Liability & Compliance",summary:"شیکارکرنا ئەرک و مافێن یاسایی، سزایێن کەمتەرخەمیێ، یاسایا بەرگرییا شارستانی ل عێراقێ، و بەرپرسیارییا دامەزراوەیان ل هەمبەر کارەساتان.",blocks:[{body:`سەلامەتی نە تەنێ ئەرکەکێ ئەخلاقی یە، بەلکو ئەرکەکێ یاسایی یێ گرنگە. ل پترییا وەلاتان، یاسا ب ڕوونی دیار دکەت کو خودانێن ئاڤاهیان، ڕێڤەبەر، ئەندازیار و تەنانەت کارمەندێن ئاسایی ژی بەرپرسیارییا یاسایی هەیە بۆ پشتڕاستبوون ژ هەبوونا ژینگەهەکا سەلامەت. ئەگەر کەمتەرخەمی ڕوو بدەت و ببیتە ئەگەرێ زیانێ بۆ کەسەکی، دشێت ببیتە ئەگەرێ سزایێن یاسایی یێن مەزن (شارستانی و تاوانکاری)، ژ قەرەبووکرنا ماددی هەتا زیندانکرنێ.

د ڤێ مۆدیوولێ دا، ئەم دێ باسێ بنەمایێن یاسایی یێن سەلامەتیێ کەین، دێ یاسایا بەرگرییا شارستانی یا عێراقێ ناسین، و دێ تێگەهین کا مرۆڤ چەوا دشێت خوە و دامەزراوەیا خوە ب ڕێکا پەیڕەوکرنا ستانداردان ژ داواکارییێن یاسایی بپارێزیت. تێبینی: ئەڤ مۆدیوولە ڕاوێژکارییا یاسایی نینە؛ بۆ هەر پرسەکا یاسایی ڤەگەڕە نڤیسینگەها یاسایی یا ڕێڤەبەرییا بەرگرییا شارستانی.`},{heading:"١. ئەرکێ چاڤدێریێ (Duty of Care)",body:"بنەمایێ «ئەرکێ چاڤدێریێ» (Duty of Care) ئێکە ژ کۆلەکێن سەرەکی یێن یاسایێن بەرپرسیاریێ. ل دویڤ ڤی بنەمایی، هەر کەسەک یان لایەنەک کو کۆنترۆلا جهەکێ یان چالاکییەکێ هەبیت، بەرپرسە ژ پاراستنا سەلامەتییا وان کەسێن دهێنە وی جهی یان بەشداری د وێ چالاکیێ دا دکەن:",points:["خودانێن ئاڤاهیان: بەرپرسن ژ دابینکرنا سیستەمێن ئاگرکوژاندن و ئاگەهدارکرنێ، و دیارکرنا ڕێڕەوێن دەرکەفتنا تەنگاڤیێ.","ڕێڤەبەر و سەرپەرشتیار: دڤێت ڕاهێنانا سەلامەتیێ بۆ کارمەندان دابین بکەن و پشتڕاست ببن کو کەرەستەیێن پاراستنا کەسی (PPE) ب دروستی دهێنە بکارئینان.","ئەندازیار و تەکنیسیەن: بەرپرسن ژ دیزاینا سەلامەت و ئەنجامدانا پشکنینێن خولی (Inspections) بۆ هەمی ئامێران ل دویڤ کۆد و ستانداردێن پەسەندکری.","مەرجێن ئەرکی: بۆ کو ئەڤ ئەرکە ل سەر تە بهێتە چەسپاندن، ب گشتی سێ خال پێدڤینە: ١. مەترسی یا پێشبینیکری بیت؛ ٢. پەیوەندییەکا نێزیک د ناڤبەرا تە و کەسێ زیانلێکەفتی دا هەبیت؛ ٣. دانانا ڤی ئەرکی ل سەر تە دادپەروەرانە و گونجای بیت (Fair, Just and Reasonable)."]},{heading:"٢. کەمتەرخەمی و شکاندنا یاسایێ (Negligence)",body:"کەمتەرخەمی ئەو حالەتە یە کو تێدا کەسەک ئەرکێ خوە یێ یاسایی یێ پاراستنێ جێبەجێ ناکەت و ژبەر هندێ کەسەکێ دی زیانێ دبینیت. ل دویڤ یاسایا هەڤپشک (Common Law)، بۆ سەلماندنا کەمتەرخەمیێ ل دادگەهێ، چار ڕەگەز پێدڤینە. ل یاسایا شارستانی یا عێراقێ ژی هەمان بنەما ب سێ ڕەگەزان دهێتە دیارکرن: خەلەتی (تەعەدی)، زیان، و پەیوەندییا ئەگەری د ناڤبەرا وان دا:",points:["١. هەبوونا ئەرکی (Duty): دڤێت بهێتە سەلماندن کو تە ئەرکەکێ یاسایی بەرامبەر وی کەسی هەبوو.","٢. شکاندنا ئەرکی (Breach): تە کارێ پێدڤی ئەنجام نەدایە (بۆ نموونە: تە پشکنینا تەمرینکێن ئاگری نەکرییە).","٣. زیان (Harm/Damage): دڤێت زیانەکا ڕاستەقینە ڕوو دابیت (لەشی، ماددی یان دەروونی).","٤. پەیوەندییا ئەگەری (Causation): دڤێت شکاندنا ئەرکێ تە ڕاستەوخۆ ببیتە ئەگەرێ وێ زیانێ (بۆ نموونە: ئەگەر تە سیستەمێ ئاگەهدارکرنێ چاک کربا، بریندار دا بشیابا دەرکەڤیت).","بەرگرییا یاسایی: کەسێ تۆمەتبار دشێت بەرگرییێ ژ خوە بکەت ئەگەر بسەلمینیت کو زیانلێکەفتی ب خوە مەترسی قبوول کربوو (Assumption of Risk)، یان کو زیان ژ ئەگەرەکێ نەچاڤەڕێکری یێ ژ دەستێ مرۆڤی دەرڤە پەیدا بوو (Force Majeure)."]},{heading:"٣. یاسایا بەرگرییا شارستانی ل عێراقێ و هەرێما کوردستانێ",body:"سیستەمێ یاسایی یێ سەلامەتیێ ب چەند یاسا و ڕێنماییێن فەرمی دهێتە ڕێکخستن:",points:["یاسایا بەرگرییا شارستانی یا عێراقی ژمارە (٤٤) یا سالا ٢٠١٣: یاسایا سەرەکی یا بەرگرییا شارستانی ل عێراقێ یە و جهێ یاسایا کەڤن ژمارە (٦٤) یا سالا ١٩٧٨ گرتییە. ئەڤ یاسایە ئەرکێ پشکنینا جهان و چاڤدێرییا پەیڕەوکرنا ڕێکارێن سەلامەتیێ ددەتە ڕێڤەبەرییا گشتی یا بەرگرییا شارستانی. بکارئینانا وێ ل هەرێما کوردستانێ دڤێت دگەل نڤیسینگەها یاسایی یا ڕێڤەبەرییێ بهێتە پشتڕاستکرن.","ڕەزامەندییا نەخشەیێن ئاڤاهیان: ل دویڤ یاسایێ، شارەوانی نەخشەیێن ئاڤاهیان بۆ بەرگرییا شارستانی دفرێکن دا کو ڕێکارێن پێشگرتن و ڤەمراندنا ئاگری بهێنە پشکنین بەری مۆلەتا ئاڤاکرنێ.","پشکنین و سزا: ڕێڤەبەرییا بەرگرییا شارستانی یا دهۆکێ پشکنینێ ل پرۆژەیێن ئاکنجیبوون و بازرگانی دکەت؛ سەرپێچی دشێت ببیتە ئەگەرێ داخستنا جهی و سزایێن دارایی یان زیندانێ ل دویڤ یاسایێ.","مۆلەتا سەلامەتیێ: ل دویڤ یاسایێ، بەری دانا مۆلەتا چالاکییا بازرگانی یان پیشەسازی (ب تایبەتی هەلگرتن و بکارئینانا ماددەیێن مەترسیدار)، ڕەزامەندییا بەرگرییا شارستانی پێدڤییە."]},{heading:"٤. بەرپرسیارییا یاسایی یا دامەزراوەیان (Corporate Liability)",body:"کۆمپانیا وەک «کەسایەتییەکا یاسایی» بەرپرسە ل هەمبەر ڕووداوێن د پرۆژەیێن وێ دا ڕوودەن:",points:["بەرپرسیارییا ل جهێ کەسەکێ دی (Vicarious Liability): کۆمپانیا بەرپرسە ژ خەلەتییێن کارمەندێن خوە ئەگەر ل دەمێ دەوامێ و د ناڤ کارێ فەرمی دا بن.","بەرپرسیارییا ڕاستەوخۆ: ئەگەر کۆمپانیایێ ڕاهێنانا پێدڤی نەدابیتە کارمەندان یان ئامێرێن کەڤن و نەسەلامەت بکار ئینابن، ب شێوەیەکێ ڕاستەوخۆ تۆمەتبار دبیت.","زیانێن دارایی: ژبلی قەرەبووکرنا زیانلێکەفتییان، کۆمپانیا تووشی زیانێن ناڤ و دەنگی (Reputation) و بلندبوونا بهایێ بیمەیێ (Insurance) دبیت."]},{heading:"٥. ستراتیژییێن پاراستنا یاسایی (Protection Strategies)",body:"بۆ پاراستنا ژیانێ و پاراستنا یاسایی، دڤێت ئەندازیار و ڕێڤەبەر ڤان خالان جێبەجێ بکەن:",points:["تۆمارکرن (Documentation): ڕێسایا زێڕین دبێژیت: «ئەگەر نەهاتبیتە نڤیسین، یانی ڕوو نەدایە». هەمی پشکنین، چاککرن و ڕاهێنانان ب ڕێکەفت و ئیمزا تۆمار بکە.","ڕاهێنانا بەردەوام: پشتڕاست ببە کو هەمی کارمەند جۆرێن تەمرینکێن ئاگری دناسن و پرۆتۆکۆلا دەرکەفتنێ دزانن.","پشکنینێن ناڤخۆیی: بەری هاتنا تیمێن حکومی، ب خوە پشکنینێن خولی ئەنجام بدە بۆ دیتنا کێماسییێن سەلامەتیێ.","گرێبەستێن فەرمی: د ناڤبەرا خودانی و بەلێندەران دا، دڤێت بەرپرسیارییا هەر لایەکی ل سەر بابەتێ سەلامەتیێ ب ڕوونی هاتبیتە نڤیسین."]},{heading:"٦. ئەخلاق و بەرپرسیارییا پیشەیی",body:"ژبلی یاسایێ، ئەندازیاری ئەرکەکێ ئەخلاقی هەیە کو نابیت بهێتە ژبیرکرن:",points:["ئەخلاقێ ئەندازیاری: پاراستنا ژیانا مرۆڤان ل پێشیا قازانجێ ماددی یە. چ جاران بڕیارێن کو سەلامەتیێ دئێخنە مەترسیێ قبوول نەکە، تەنانەت ئەگەر ژ لایێ ڕێڤەبەرییێ ڤە فشار ل سەر تە هەبیت.","ڕاپۆرتکرن: ئەرکێ تە یێ ئەخلاقی یە کو هەر مەترسییەکا هەی ب ڕوونی ڕاپۆرت بکەی بەری کارەسات ڕوو بدەت."]}],media:[{kind:"image",src:"media/images/uni_06_negligence_chart.png",title:"بازنەیا کەمتەرخەمیێ",description:"چار ڕەگەزێن یاسایی بۆ سەلماندنا کەمتەرخەمیێ ل دادگەهێ"},{kind:"video",src:"media/videos/uni_06_legal_brief.mp4",title:"بەرپرسیارییا یاسایی",description:"شیکارکرنا کەیسەکا ڕاستەقینە یا کارەساتەکا ئاگری ل دویڤ یاسایێن عێراقێ"},{kind:"image",src:"media/images/uni_06_documentation_log.png",title:"نموونەیا تۆمارکرنێ",description:"چەوانیا تۆمارکرنا پشکنینێن سەلامەتیێ بۆ پاراستنا یاسایی"}],quiz:[{question:"کیش ژ ڤان ڕەگەزان مەرج «نینە» بۆ سەلماندنا کەمتەرخەمیێ (Negligence) ل دادگەهێ؟",options:[{text:"هەبوونا ئەرکی (Duty)",correct:!1},{text:"نیازا خراب (Criminal Intent)",correct:!0},{text:"زیان (Harm)",correct:!1},{text:"پەیوەندییا ئەگەری (Causation)",correct:!1}],explanation:"کەمتەرخەمی (Negligence) پێدڤی ب نیازا خراب نینە؛ تەنانەت ئەگەر تە ب ئەنقەست زیان نەگەهاندبیت، بەلێ تە ئەرکێ خوە یێ پاراستنێ جێبەجێ نەکربیت، تو ژ لایێ یاسایی ڤە بەرپرسی."},{question:"مەبەست ژ «Vicarious Liability» چییە؟",options:[{text:"بەرپرسیارییا کەسی یا کارمەندی",correct:!1},{text:"بەرپرسیارییا دامەزراوەیێ ل سەر کارێن کارمەندێن خوە",correct:!0},{text:"یاسایا ئاگرکوژاندنێ",correct:!1},{text:"قەرەبووکرنا ژینگەهێ",correct:!1}],explanation:"ئەڤ زاراوە نیشان ددەت کو دامەزراوە یان کۆمپانیا بەرپرسە ژ کار و خەلەتییێن کارمەندێن خوە ل دەمێ جێبەجێکرنا ئەرکێن وان."},{question:"ل عێراقێ، کیش یاسا بەرگرییا شارستانی و ڕێکارێن سەلامەتییا دامەزراوە و ئاڤاهییان ڕێک دئێخیت؟",options:[{text:"یاسایا ژمارە ٦٤ یا ١٩٧٨",correct:!1},{text:"یاسایا بەرگرییا شارستانی ژمارە ٤٤ یا ٢٠١٣",correct:!0},{text:"یاسایا ژمارە ٧ یا ٢٠٠٥",correct:!1},{text:"یاسایا هاتنوچوونێ",correct:!1}],explanation:"یاسایا بەرگرییا شارستانی ژمارە ٤٤ یا سالا ٢٠١٣ یاسایا سەرەکی یا بەرگرییا شارستانی یە ل عێراقێ؛ یاسایا ژمارە ٦٤ یا ١٩٧٨ ب ڤێ یاسایێ هاتییە هەلوەشاندن. بکارئینانا وێ ل هەرێما کوردستانێ دگەل نڤیسینگەها یاسایی یا ڕێڤەبەرییێ پشتڕاست بکە."},{question:"ڕێسایا زێڕین د پاراستنا یاسایی دا دبێژیت: «ئەگەر نەهاتبیتە نڤیسین...»؟",options:[{text:"یانی نە گرنگە",correct:!1},{text:"یانی دێ پاشی هێتە کرن",correct:!1},{text:"یانی ب ڕاستی ڕوو نەدایە",correct:!0},{text:"یانی یاسایی یە",correct:!1}],explanation:"ل دادگەهێ، تۆمارکرن و نڤیسین ب هێزترین بەلگەنە؛ هەر کارەکێ نەهاتبیتە تۆمارکرن، وەسا دهێتە هەژمارتن کو نەهاتییە کرن."}]},{id:7,code:"PSYCH-700",icon:"BrainCircuit",accent:"#0d9488",title:"دەروونناسیا کارەساتان و ڕەفتارێ مرۆڤی",subtitle:"Disaster Psychology, Crowd Dynamics & Crisis Leadership",summary:"شیکارکرنا کاردانەڤەیا بایۆلۆژی و دەروونی یا مرۆڤی ل دەمێ کارەساتان، ڕێڤەبرنا قەرەبالغیێ، و بنەمایێن سەرکردایەتییا تەنگاڤیێ.",blocks:[{body:"ل دەمێ کارەساتێن مەزن، چ ئاگر بیت، عەردەهەژین یان تەقین، ڕەفتارێ مرۆڤی ب خوە دشێت ببیتە ئەگەرەکێ سەرەکی یێ قوربانییان: دوودلی، قەرەبالغی ل سەر ئێک دەرگەهی، و فشارا خەلکی ل سەر دەرکەفتنان. بۆ نموونە، ل ئاگرێ یانەیا «The Station» ل ئەمریکا (٢٠٠٣)، ١٠٠ کەس مرن؛ ل دویڤ ڤەکۆلینا NIST، پترییا خەلکی هەول دا ژ دەرگەهێ سەرەکی یێ کو پێ هاتبوونە ژوور دەرکەڤن، و ل وێرێ قەرەبالغی و گرتنا دەرگەهی چێبوو، هەرچەندە دەرکەفتنێن دی ژی هەبوون. تێگەهشتن ژ دەروونناسیا قەرەبالغیێ ئەرکەکێ سەرەکی یێ هەر سەرکردەیەکێ بەرگرییا شارستانی یە بۆ ڕێڤەبرنا بلەز و کێمکرنا قوربانییان."},{heading:"١. کاردانەڤەیا بایۆلۆژی بەرامبەر مەترسییێ (Fight-Flight-Freeze)",body:"دەمێ مێشک هەست ب مەترسییەکا ژیانێ دکەت، سیستەمێ دەماری یێ سیمپاسەتیک (Sympathetic Nervous System) چالاک دبیت و لەش هۆرمۆنێن ئەدرینالین و کۆرتیزۆلێ بەرددەت، و ئەڤە دبیتە ئەگەرێ چەند جۆرێن کاردانەڤێ:",points:["Fight (شەڕ): ئامادەبوونا لەشی بۆ بەرگریێ. ل کارەساتان، ئەڤە دشێت ببیتە ئەگەرێ ڕەفتارێن توند دگەل کەسێن دی بۆ دەربازبوونێ.","Flight (ڕەڤین): هەولدانا دوورکەفتنا بلەز. ئەڤە دشێت ببیتە ئەگەرێ پالدانا قەرەبالغیێ بەرەڤ ئێک ئاراستە.","Freeze (ڕاوەستان/جەمدین): کەس نەشێت بلڤیت یان بڕیارێ بدەت و وەک پەیکەرەکێ ل جهێ خوە دمینیت. ئەڤە ئێک ژ مەترسیدارترین حالەتانە چونکی کەس د ناڤ مەترسیێ دا دمینیت.","Fawn (گونجاندن): هەولدانا کەسی بۆ ڕازیکرنا لایێ مەترسیدار، یان پەیڕەوکرنا کۆمێ بێ هزرکرن.","گوهۆڕینێن مێشکی: ل دەمێ ترسێ، بەشێ Amygdala کۆنترۆلێ دگریت و بەشێ Prefrontal Cortex کو بەرپرسە ژ بڕیاردانا ژیرانە لاواز دبیت. ئەڤە دبیتە ئەگەرێ «دیتنا تونێلی» (Tunnel Vision): تەنێ دیتنا ئێک ئارمانجێ و پشتگوهـ ئێخستنا دەرکەفتنێن دی."]},{heading:"٢. دەروونناسیا قەرەبالغیێ و ڕەفتارێ کەریێ (Herd Behavior)",body:"مرۆڤ ل دەمێ تەنگاڤیێ گەلەک جاران بێ هزرکرن لاسایییا پرانییێ دکەت، و ئەڤە دشێت ببیتە ئەگەرێ کارەساتان. تێبینی: ڤەکۆلینێن کارەساتان نیشان ددەن کو ترسا بێ کۆنترۆل (Panic) کێمترە ژ وێ یا خەلک هزر دکەن؛ پترییا خەلکی ب ژیرانە ڕەفتار دکەن، بەلێ کێمییا زانیاری و ڕێنماییان دوودلی و قەرەبالغیێ دروست دکەت:",points:["Herd Behavior (ڕەفتارێ کەریێ): ئەگەر کەسەک بڕەڤیت، گەلەک کەس دێ ل دویڤ ڕەڤن تەنانەت ئەگەر نەزانن بۆچی. ئەڤە ترسێ وەک ڤایرۆسەکێ بەلاڤ دکەت.","Funnel Effect (دیاردەیا قیفێ): کۆمبوونا هەمی خەلکی ل سەر ئێک دەرگەهی (گەلەک جاران ئەو دەرگەهێ پێ هاتینە ژوور)، کو دبیتە ئەگەرێ خەندقین و پێلێکرنا کەسان.","Panic Contagion: بەلاڤبوونا ترسێ ب لەز د ناڤ خەلکی دا، کو دەستهەلاتا سەرکردایەتیێ لاواز دکەت.","Deindividuation: دەمێ کەس دبیتە پشکەک ژ کۆمەکا مەزن، هەستێ بەرپرسیارییا کەسی کێم دبیت و دشێت ڕەفتارێن بێ کۆنترۆل بکەت."]},{heading:"٣. سەرکردایەتییا قەیرانان (Crisis Leadership)",body:"سەرکردایەتی ل دەمێ کارەساتان پێدڤی ب ئارامی و فەرمانێن ڕاستەوخۆ هەیە بۆ ڕێگرتن ل ترسێ:",points:["ئامادەبوونا ئارام (Calm Presence): سەرکردە دڤێت ب ئارامی باخڤیت و ڕەفتار بکەت؛ ئەگەر سەرکردە ترسا خوە نیشان بدەت، خەلک دێ ترسن.","فەرمانێن کورت و ڕوون: ل جهێ ئاخفتنێن درێژ، فەرمانێن وەک «بچنە لایێ ڕاستێ»، «ڕاوەستن»، «ل دویڤ من وەرن» بکار بینە.","ئاماژەیێن دەستی (Hand Signals): ل دەمێ دەنگەدەنگا بلند، ئاماژەیێن دەستی یێن ڕوون بکار بینە بۆ ئاراستەکرنا خەلکی.","جوداکرنا کەسێن ترسیای (Isolating Panickers): ئەو کەسێن هاوار دکەن و ترسێ بەلاڤ دکەن، دڤێت ب نەرمی ژ کۆمێ بهێنە جوداکرن دا کو کارتێکرنێ ل سەر یێن دی نەکەن."]},{heading:"٤. هاریکارییا دەروونی یا ئێکێ (Psychological First Aid - PFA)",body:"مۆدێلێ RAPID (ژ زانکۆیا Johns Hopkins) بۆ کێمکرنا برینا دەروونی یا قوربانییان دهێتە بکارئینان: R گوهداریکرنا ڤەگێڕانێ، A هەلسەنگاندنا پێدڤییان، P ئەولەوییەتدان، I دەستێوەردان، D ڕەوانەکرن بۆ خزمەتگوزارییێن پێدڤی. خالێن سەرەکی:",points:["R - Reflective Listening: گوهداریکرن و ڤەگێڕانا هەستێن کەسی؛ ڕێ بدە قوربانی خەمێن خوە بێژیت بێ دادوەریکرن.","A - Assessment: هەلسەنگاندنا پێدڤییێن ئێکسەر (ئاڤ، خوارن، پەیوەندی ب مالباتێ ڤە).","سەلامەتی و ئارامی (Safety & Comfort): دابینکرنا جهەکێ ئارام و دوور ژ دیمەنێن کارەساتێ.","چ نەکەین: چ جاران نەبێژە «هەمی تشت دێ باش بن» یان «ئەز دزانم تو ب چ دا دەرباز دبی»، چونکی ئەڤە بەلێنێن بێ بنەمانە و کارتێکرنا نەرێنی دکەن."]},{heading:"٥. نەخۆشییا فشارا پشتی برینا دەروونی (PTSD)",body:"نەخۆشییا فشارا پشتی برینا دەروونی (Post-Traumatic Stress Disorder) نە تەنێ بۆ قوربانییان، بەلکو بۆ تیمێن هەوارهاتنێ ژی مەترسییە:",points:["نیشان: خەونێن ترسناک (Nightmares)، دووبارە هاتنا دیمەنێن ڕووداوی (Flashbacks)، و هشیارییا زێدە (Hypervigilance).","دەم: ئەگەر نیشان پتر ژ هەیڤەکێ بەردەوام بن یان ژیانا ڕۆژانە تێک بدەن، پێدڤی ب هاریکارییا پسپۆرێن دەروونی هەیە.","بەرخۆدان (Resilience): ئامادەکارییا دەروونی بەری ڕووداوی، هەلسەنگاندنا کاری پشتی ئەرکان (Operational Debriefing)، و پشتەڤانییا هەڤکاران. ل دویڤ ڕێنماییێن WHO، دانیشتنا دەروونی یا ئێک-جاری یا بزۆری (Psychological Debriefing) بۆ ڕێگرتن ل PTSD ناهێتە پێشنیارکرن."]}],media:[{kind:"video",src:"media/videos/uni_07_crowd_dynamics.mp4",title:"داینامیکا قەرەبالغیێ",description:"شیکارکرنا چەوانیا لڤینا خەلکی ل دەمێ ترسێ"},{kind:"image",src:"media/images/uni_07_pfa_model.png",title:"مۆدێلێ RAPID",description:"هەنگاڤێن هاریکارییا دەروونی یا ئێکێ"},{kind:"video",src:"media/videos/uni_07_leadership_drill.mp4",title:"ڕاهێنانا سەرکردایەتیێ",description:"چەوانیا ئاراستەکرنا خەلکی ب دەنگی و ئاماژەیێن دەستی"}],quiz:[{question:"مەبەست ژ «Freeze» د کاردانەڤەیا بایۆلۆژی یا ترسێ دا چییە؟",options:[{text:"ڕەڤینا بلەز",correct:!1},{text:"شەڕکرن بۆ پاراستنا ژیانێ",correct:!1},{text:"جەمدین و ڕاوەستان ل جهێ خوە بێ لڤین",correct:!0},{text:"گونجاندن دگەل کۆمێ",correct:!1}],explanation:"Freeze حالەتەکێ دەروونی یە کو تێدا کەس نەشێت چ بڕیاران بدەت یان بلڤیت، و ئەڤە مەترسییا مانا د ناڤ کارەساتێ دا زێدە دکەت."},{question:"ل دویڤ پرۆتۆکۆلا PFA، کیش ڕەفتار «خەلەتە» دگەل کەسەکێ برینا دەروونی لێ دای؟",options:[{text:"گوهداریکرنا ب ئارامی",correct:!1},{text:"دابینکرنا ئاڤ و خوارنێ",correct:!1},{text:"گۆتنا ڕستەیا «هەمی تشت دێ باش بن»",correct:!0},{text:"پەیوەندیکرن ب مالباتا وی ڤە",correct:!1}],explanation:"دانا بەلێنێن بێ بنەما وەک «دێ باش بیت» کارتێکرنەکا نەرێنی هەیە و متمانەیا قوربانی کێم دکەت."},{question:"باشترین شێوازێ فەرماندانێ ل دەمێ قەیرانێ بۆ سەرکردەیەکێ بەرگرییا شارستانی چییە؟",options:[{text:"ئاخفتن ب هاوار و ترس",correct:!1},{text:"فەرمانێن کورت، ڕوون و ب دەنگەکێ ئارام",correct:!0},{text:"گوهـ نەدانە خەلکی",correct:!1},{text:"باسکرنا هوورکارییێن کیمیایی یێن کارەساتێ",correct:!1}],explanation:"خەلک پێدڤی ب ئاراستەکرنا ڕاستەوخۆ و ڕوون هەیە؛ ئارامییا سەرکردەی ترسێ د ناڤ خەلکی دا کێم دکەت."},{question:"دیاردەیا «Herd Behavior» چەوا کار دکەت؟",options:[{text:"هزرکرنا تاکەکەسی",correct:!1},{text:"لاسایییا بێ هزرکرن یا ڕەفتارێن پرانییێ",correct:!0},{text:"پەیڕەوکرنا یاسایان",correct:!1},{text:"ڕزگارکرنا کەسێن دی",correct:!1}],explanation:"مرۆڤ ل دەمێ ترسێ پتر حەز دکەت ل دویڤ خەلکی بچیت بێ کو هزر بکەت کا ئەو ڕێک دروستە یان نە."}]},{id:8,code:"ENV-800",icon:"Leaf",accent:"#16a34a",title:"سەلامەتییا ژینگەهێ و ڕێڤەبرنا پاشماوەیان",subtitle:"Environmental Safety & Waste Management",summary:"کارتێکرنا ئاگر و ماددەیێن کیمیایی ل سەر ژینگەهێ، ڕێڤەبرنا دروست یا پاشماوەیێن پزیشکی، پاراستنا سەرچاڤەیێن ئاڤێ، و بەرپرسیارییا ژینگەهی.",blocks:[{body:"دەمێ ئەم باسێ سەلامەتیێ دکەین، دڤێت نە تەنێ هزرا سەلامەتییا مرۆڤی بکەین، بەلکو سەلامەتییا ژینگەهـ و سروشتی ژی ل بەرچاڤ بگرین. هەر کارەساتەک یان ڕووداوەکێ سەلامەتیێ (وەک ئاگر یان ڕژانا کیمیایی) کارتێکرنەکا درێژخایەن ل سەر ژینگەهێ دهێلیت: دوکێل هەوایێ پیس دکەت، ئاڤا ئاگرکوژاندنێ ژەهراوی دبیت و دگەل ئاڤێن ژێرعەردی تێکەل دبیت، و پاشماوەیێن مەترسیدار پەیدا دبن. د ڤێ مۆدیوولێ دا، ئەم دێ باسێ ڕێڤەبرنا پاشماوەیان، پاراستنا ئاڤ و هەوایێ، و بەرپرسیارییا ژینگەهی یا دامەزراوەیان کەین بۆ پاراستنا نفشێن داهاتی."},{heading:"١. پاشماوەیێن پزیشکی و بایۆلۆژی (Medical Waste)",body:"ل نەخۆشخانە، کلینیک و تاقیگەهان، پاشماوەیێن تایبەت پەیدا دبن کو دشێن بەکتریا و ڤایرۆسان بگوهێزن. ئەڤ پاشماوە نابیت وەک زبلێ ئاسایی بهێنە هاڤێتن، بەلکو دڤێت ب ڕەنگان بهێنە جوداکرن. ڕەنگ ژ وەلاتەکێ بۆ وەلاتەکێ دی دگوهۆڕن؛ ل ڤێرە سیستەمێ ڕێکخراوا ساخلەمییا جیهانی (WHO) دهێتە بکارئینان، و هەردەم ڕێنماییێن ناڤخۆیی یێن نەخۆشخانەیێ پەیڕەو بکە:",points:["پاشماوەیێن تیژ (Sharps - زەر): هەمی ئەو تشتێن دشێن پێستی کون بکەن، وەک دەرزی، تیغێن نەشتەرگەریێ و شووشەیێن شکەستی. دڤێت د سندۆقێن پلاستیکی یێن ڕەق و دژە-کونبوونێ دا (Sharps Container) بهێنە کۆمکرن.","پاشماوەیێن ڤەگرتی (Infectious/Biohazard - زەر ل دویڤ WHO؛ ل هندەک وەلاتان وەک ئەمریکا سۆر): ئەو تشتێن ب خوین یان شانەیێن لەشی پیس بووین و کەرەستەیێن تاقیگەهێ. دڤێت ب ئۆتۆکلاڤێ (Autoclave) یان سۆتنا تەمام (Incineration) بهێنە نەهێلان.","پاشماوەیێن گشتی (General - ڕەش): کاغەز، کارتۆن و پلاستیکێن پاقژ کو چ مەترسییا بایۆلۆژی ل سەر نینە.","پاشماوەیێن دەرمانی و کیمیایی (Pharmaceutical/Chemical - قاوەیی ل دویڤ WHO): دەرمانێن بەسەرچووی یان پاشماوەیێن کیمیایی یێن تاقیگەهێ کو دڤێت ب ڕێکارێن تایبەت بهێنە چارەسەرکرن."]},{heading:"٢. پیسبوونا ئاڤێ ب ئەگەرێ ئاگرکوژاندنێ (Fire Runoff)",body:"ئەو ئاڤا ل دەمێ ڤەمراندنا ئاگرێن مەزن دهێتە بکارئینان، تەنێ ئاڤەکا پیس نینە، بەلکو «ژەهرەکا شل»ە کو تژی ماددەیێن کیمیایی و کانزایی یە:",points:["ماددەیێن پیسکەر: تێدا PAHs ژ سۆتنا پلاستیکی، کانزایێن گران وەک سرب و جیوە، و ماددەیێن کەفا ئاگرکوژاندنێ یێن مەترسیدار وەک PFAS هەنە، کو دبێژنێ «کیمیایێن هەروهەری» (Forever Chemicals) چونکی د ژینگەهێ دا ناهێنە شیکارکرن.","بەرگرتنا ئاڤێ (Containment): ئەندازیارێن سەلامەتیێ دڤێت بەربەستێن دەمکی دروست بکەن دا کو ئەڤ ئاڤا ژەهراوی نەچیتە ناڤ ڕێکێن ئاڤا پیس یان ڕووباران.","چارەسەرکرنا ئاڤێ: ئەڤ ئاڤە دڤێت بهێتە کۆمکرن و بۆ وێستگەهێن تایبەت یێن چارەسەرکرنا ئاڤا پیس (Wastewater Treatment) بهێتە هنارتن بەری بەردانێ."]},{heading:"٣. پیسبوونا هەوایێ و کیمیایا دوکێلێ",body:"ئاگرێن مەزن، ب تایبەتی ئاگرێن پیشەسازی و دارستانان، تەنۆلکێن گەلەک مەترسیدار دهاڤێژنە ناڤ هەوایێ:",points:["تەنۆلکێن هوور (PM2.5): پارچەیێن گەلەک بچووک کو دچنە قوولاتییا سییان و دبنە ئەگەرێ نەخۆشییێن دل و سییان و شێرپەنجەیێ.","غازێن ژەهراوی: وەک مۆنۆکسیدا کاربۆنێ (CO) و هایدرۆجین سیانید (HCN) کو ل دەمێ سۆتنا ئاڤاهییان بەرهەم دهێن و هەوایێ دەوروبەری ژەهراوی دکەن.","بارانا ترش (Acid Rain): غازێن وەک SOx و NOx دگەل بارانێ تێکەل دبن و زیانێ دگەهیننە گیا و دارستانان."]},{heading:"٤. پاشماوەیێن ئەلەکترۆنی (E-Waste)",body:"ئامێرێن ئەلەکترۆنی یێن شکەستی یان سۆتی (مۆبایل، کۆمپیوتەر) مەترسییەکا ژینگەهی یا مەزنن:",points:["کانزایێن ژەهراوی: تێدا سرب، جیوە و کادمیۆم هەنە کو ئەگەر بچنە ناڤ ئاڤ یان ئاخێ، ناهێنە شیکارکرن و بۆ ماوەیەکێ گەلەک درێژ دمینن و ساخلەمییا مرۆڤی دئێخنە مەترسیێ.","زڤڕاندن (Recycling): نابیت ئەڤ ئامێرە ل جهێن گشتی بهێنە هاڤێتن؛ دڤێت بۆ وێستگەهێن تایبەت یێن زڤڕاندنێ بهێنە هنارتن دا کو کانزایێن ب بها (زێڕ و زیڤ) ژێ بهێنە جوداکرن."]},{heading:"٥. بەرپرسیارییا ژینگەهی و ستانداردێ ISO 14001",body:"هەر دامەزراوەیەک باشترە سیستەمەکێ ڕێڤەبرنا ژینگەهی هەبیت بۆ کێمکرنا زیانان:",points:["بنەمایێ 3R: کێمکرن (Reduce)، دووبارە بکارئینان (Reuse)، و زڤڕاندن (Recycle).","ISO 14001: ستانداردەکێ نێڤدەولەتی یێ دلخوازە بۆ سیستەمێ ڕێڤەبرنا ژینگەهی (EMS)؛ دامەزراوەیێن پەیڕەو دکەن، سیاسەتەکا ژینگەهی، ئارمانجێن پێڤانبار و پشکنینێن ناڤخۆیی یێن خولی دادنێن.","چاڤدێری و پشکنین: ئەنجامدانا پشکنینێن خولی بۆ ئاخ و ئاڤا دەوروبەرێ کارگەهان بۆ پشتڕاستبوون ژ نەبوونا دەرچوونا ماددەیێن کیمیایی."]}],media:[{kind:"image",src:"media/images/uni_08_waste_colors.png",title:"سیستەمێ ڕەنگان",description:"جوداکرنا پاشماوەیێن پزیشکی ب ڕەنگان ل دویڤ WHO"},{kind:"video",src:"media/videos/uni_08_hazmat_disposal.mp4",title:"هاڤێتنا ماددەیێن مەترسیدار",description:"ڕێکارێن دروست یێن هاڤێتنا پاشماوەیێن کیمیایی"},{kind:"image",src:"media/images/uni_08_runoff_control.png",title:"کۆنترۆلکرنا ئاڤا ئاگرکوژاندنێ",description:"چەوانیا ڕێگرتن ل تێکەلبوونا ئاڤا ژەهراوی دگەل ڕووباران"}],quiz:[{question:"ل دویڤ سیستەمێ WHO، دەرزی و تیغێن پزیشکی د کیش دەفرێ دا دهێنە هاڤێتن؟",options:[{text:"کیسکا سۆر (Biohazard)",correct:!1},{text:"کیسکا ڕەش (گشتی)",correct:!1},{text:"سندۆقا ڕەق یا زەر (Sharps Container)",correct:!0},{text:"کیسکا شین",correct:!1}],explanation:"هەمی تشتێن تیژ دڤێت د سندۆقا ڕەق یا زەر (Sharps Container) دا بهێنە هاڤێتن دا کو نەبنە ئەگەرێ برینداربوون و ڤەگوهاستنا نەخۆشییان."},{question:"مەترسییا مەزن یا ئاڤا ئاگرکوژاندنێ (Fire Runoff) چییە؟",options:[{text:"تەنێ پیسە",correct:!1},{text:"ماددەیێن ژەهراوی و کانزایێن گران دگەل خوە دبەتە ناڤ ژینگەهێ",correct:!0},{text:"پلەیا گەرمیا وێ گەلەک بلندە",correct:!1},{text:"چ مەترسی نینە",correct:!1}],explanation:"ئەڤ ئاڤە ژەهر و ماددەیێن کیمیایی یێن سۆتی دگەل خوە دبەت و دشێت ئاڤێن ڕووی و ژێرعەردی ژەهراوی بکەت."},{question:"تەنۆلکێن PM2.5 د دوکێلا ئاگران دا چ مەترسیێ بۆ ساخلەمییا مرۆڤی دروست دکەن؟",options:[{text:"تەنێ ڕەنگێ پێستی دگوهۆڕن",correct:!1},{text:"دچنە قوولاتییا سییان و دبنە ئەگەرێ نەخۆشییێن گران",correct:!0},{text:"چ زیان نینە",correct:!1},{text:"بۆ هەناسەدانێ باشن",correct:!1}],explanation:"PM2.5 پارچەیێن گەلەک بچووکن کو دچنە قوولاتییا سییان و دبنە ئەگەرێ کێشەیێن درێژخایەن یێن دل و سیستەمێ هەناسێ."},{question:"مەبەست ژ (Recycle) د بنەمایێ 3R دا چییە؟",options:[{text:"سۆتنا پاشماوەیان",correct:!1},{text:"زڤڕاندن و دووبارە بەرهەمئینان ژ پاشماوەیان",correct:!0},{text:"کێمکرنا خەرجییان",correct:!1},{text:"هاڤێتن ل دەرڤەی باژێری",correct:!1}],explanation:"Recycle یانی گوهۆڕینا پاشماوەیان بۆ کەرەستەیێن نوو دا کو ژینگەهـ بهێتە پاراستن."}]},{id:9,code:"MGMT-900",icon:"Network",accent:"#2563eb",title:"سیستەمێ فەرماندەییا ڕووداوان (ICS)",subtitle:"Incident Command System & Strategic Management",summary:"سیستەمێ ستاندارد یێ ICS بۆ ڕێڤەبرنا ڕووداو و کارەساتان، هەماهەنگییا د ناڤبەرا دەزگەهان دا، و ڕێڤەبرنا سەرچاڤەیان.",blocks:[{body:"دەمێ کارەساتەکا مەزن ڕوودەت، وەک لافاو، عەردەهەژین یان ئاگرەکێ پیشەسازی، گەلەک جاران کێشەیا هەرە مەزن نە تەنێ کێمییا سەرچاڤەیانە، بەلکو نەبوونا هەماهەنگی و ڕێکخستنێ یە. گەلەک جاران دەهان تیمێن جودا (ئاگرکوژاندن، پۆلیس، ئەمبوولانس و خوەبەخش) پێکڤە دگەهنە جهێ ڕووداوی؛ بێ سیستەمەکێ ڕێکخستی، ئەڤە دبیتە ئەگەرێ تێکچوون و دووبارەبوونا کاران. سیستەمێ فەرماندەییا ڕووداوان (ICS) چارەسەرییا ڤێ کێشەیێ یە. ئەڤ سیستەمە ل سالێن حەفتییان ل ئەمریکا (بەرنامەیێ FIRESCOPE ل کالیفۆرنیا) هاتە دانان، و ئەڤرۆ پشکەکە ژ سیستەمێ نیشتمانی یێ ئەمریکی NIMS (FEMA) و ل گەلەک وەلات و ڕێکخراوان هاتییە وەرگرتن بۆ ڕێڤەبرنا قەیرانان ب شێوەیەکێ ڕێکخستی."},{heading:"١. پێنج ئەرکێن سەرەکی یێن ICS (Major Functions)",body:"سیستەمێ ICS ل سەر بنەمایێ دابەشکرنا ئەرکان کار دکەت. هەر ڕووداوەک، بچووک بیت یان مەزن، پێدڤی ب ڤان پێنج ئەرکان هەیە (ل ڕووداوێن تایبەت، ئەرکێ زانیاری و ڤەکۆلینێ - Intelligence/Investigations - دشێت وەک ئەرکەکێ شەشێ بهێتە زێدەکرن):",points:["١. Incident Commander (IC): فەرماندەیێ ڕووداوی؛ ئێک کەسە کو بڕیارێن دووماهیێ ددەت و بەرپرسە ژ دانانا ئارمانجێن سەرەکی و سەلامەتییا گشتی یا تیمان (ل ڕووداوێن ب چەند دەزگەهان، فەرماندەییا ئێکگرتی - Unified Command - دهێتە بکارئینان).","٢. Operations (کارێن مەیدانی): ئەو پشکە یا کو کارێ ڕاستەوخۆ ل مەیدانێ ئەنجام ددەت (وەک ئاگرکوژاندن، ڕزگارکرن، یان چارەسەرییا پزیشکی).","٣. Planning (پلاندانان): کۆمکرنا پێزانینان ل سەر ڕووداوی، شیکارکرنا داتایان، و نڤیسینا «پلانا کارێن ڕووداوی» (IAP) بۆ قۆناغێن داهاتی.","٤. Logistics (لۆجیستیک): دابینکرنا هەمی پێدڤییان (خوارن، ئاڤ، سۆتەمەنی، ئامێرێن پەیوەندیێ و جهێ حەوانا تیمان). بێ لۆجیستیک، تیمێن مەیدانی نەشێن بەردەوام بن.","٥. Finance/Admin (دارایی و کارگێڕی): ڕێڤەبرنا لایێ دارایی، تۆمارکرنا دەمژمێرێن کاری و خەرجییێن کەرەستەیان، و مامەلەکرن دگەل داخوازێن قەرەبووکرنێ."]},{heading:"٢. مەودایێ کۆنترۆلێ (Span of Control)",body:"ئێک ژ گرنگترین بنەمایێن ICS ئەوە کو نابیت سەرپەرشتیارەک بارەکێ زێدە ل سەر بیت. ئەڤ بنەمایە دیار دکەت کا سەرپەرشتیارەک دشێت ب باشی کۆنترۆلا چەند کەسان بکەت:",points:["ژمارەیا گونجای: ل دویڤ NIMS، هەر سەرپەرشتیارەک دڤێت کۆنترۆلا ٣ هەتا ٧ کەسان یان یەکەیان بکەت، و ڕێژەیا پێشنیارکری ١ بۆ ٥ یە.","بۆچی ٥؟ ئەگەر ژمارە ژ ٧ پتر بیت، سەرپەرشتیار کۆنترۆلێ ژ دەست ددەت و خەلەتی پەیدا دبن؛ ئەگەر ژ ٣ کێمتر بیت، سەرچاڤە ب فیڕۆ دچن.","ڕێکخستنا مۆدیوولی (Modular Organization): ICS وەک پارچەیان مەزن دبیت؛ هەر دەمێ پێدڤی بوو، پشکێن نوو دهێنە ڤەکرن دا کو مەودایێ کۆنترۆلێ د سنوورێ گونجای دا بمینیت."]},{heading:"٣. زمانێ هەڤپشک و زاراوەیێن ستاندارد",body:"ل دەمێ تەنگاڤیێ، تێنەگەهشتن دشێت ببیتە ئەگەرێ مرنێ. ICS پێدڤی دکەت کو هەمی لایەن ب زمانەکێ هەڤپشک و ڕوون باخڤن:",points:["زمانێ ڕوون (Plain Language): کۆدێن دەهـ (Ten-codes، وەک 10-4) و کۆدێن تایبەت یێن دەزگەهان ناهێنە بکارئینان؛ ئەو سیستەمەکێ کەڤنن (Legacy) و واتایا وان ژ دەزگەهەکێ بۆ یێ دی جودایە. دڤێت زمانەکێ سادە و ڕوون بهێتە بکارئینان دا کو هەمی دەزگەهـ (پۆلیس، ئاگرکوژاندن، ئەمبوولانس) تێبگەهن.","ناڤێن ستاندارد یێن پۆستان: ناڤێن پۆست و یەکەیان ل هەمی ڕووداوان دڤێت وەک ئێک بن (بۆ نموونە: Incident Commander، نە «سەرۆک» یان «بەرپرس» ل جهەکێ و ناڤەکێ دی ل جهەکێ دی).","دابەشکرنا جوگرافی: دابەشکرنا جهێ ڕووداوی بۆ دەڤەران (Divisions) بۆ کۆنترۆلکرنا هەر ناڤچەیەکێ ب جودا، و بۆ کۆمان (Groups) ل دویڤ ئەرکی."]},{heading:"٤. پلانا کارێن ڕووداوی (Incident Action Plan - IAP)",body:"IAP بەلگەنامەیەکا نڤیسکی یە کو ڕێکا کاری بۆ هەر ماوەیەکێ کاری (Operational Period) دیار دکەت:",points:["ناڤەڕۆک: پلان دیار دکەت: ئارمانج چییە؟ کێ بەرپرسە؟ کیش کەنالا ڕادیۆیێ بهێتە بکارئینان؟ و خالا پزیشکی ل کیرێ یە؟","ماوەیێ پلانێ: پترییا جاران پلان بۆ ١٢ هەتا ٢٤ دەمژمێرێن داهاتی دهێتە نڤیسین.","ئارمانجێن SMART: ئارمانج دڤێت دیار، پێڤانبار، گەهشتنبار، گونجای و ب دەمەکێ دیارکری بن (بۆ نموونە: ڤەمراندنا ئاگرێ کۆگەها باکووری د ماوەیێ ٤ دەمژمێران دا)."]},{heading:"٥. فەرماندەییا ئێکگرتی (Unified Command)",body:"دەمێ ڕووداوەک کارتێکرنێ ل سەر چەند دەزگەهان یان چەند ناڤچەیێن ئیداری دکەت، فەرماندەییا ئێکگرتی (Unified Command) دهێتە بکارئینان:",points:["هەماهەنگی: ل جهێ کو هەر دەزگەهەک ب سەربەخۆیی کار بکەت، بەرپرسێن هەمی دەزگەهان ل ئێک جهی کۆم دبن و ل سەر ئێک پلانێ ڕێک دکەڤن.","مفا: ڕێگرییێ ل ناکۆکییان دکەت و ناهێلیت ئێک کار دوو جاران ژ لایێ دوو تیمان ڤە بهێتە کرن.","ICP (Incident Command Post): جهەکێ فیزیکی یێ دیارکری یە کو فەرماندەیێن ڕووداوی لێ کۆم دبن بۆ ڕێڤەبرنا ڕووداوی."]},{heading:"٦. ب دووماهی ئینانا ئەرکی (Demobilization)",body:"ب دووماهی ئینانا ئەرکی ب شێوەیەکێ ڕێکخستی هندی دەستپێکرنێ گرنگە:",points:["پلانا ڤەکێشانێ: تیم دڤێت ب ڕێزبەندی بهێنە ڤەکێشان دا کو چ کێماسی ل مەیدانێ نەمینن و هەمی کەس و ئامێر بهێنە هەژمارتن.","After Action Review (AAR): ئەنجامدانا دانیشتنەکا هەلسەنگاندنێ پشتی ڕووداوی بۆ دیارکرنا خالێن ب هێز و لاواز، دا کو کار د داهاتیێ دا باشتر ببیت."]}],media:[{kind:"image",src:"media/images/uni_09_ics_structure.png",title:"پەیکەرێ ڕێکخستنا ICS",description:"دیاگراما پێنج ئەرکێن سەرەکی یێن فەرماندەییا ڕووداوان"},{kind:"video",src:"media/videos/uni_09_command_post.mp4",title:"بنکەیا فەرماندەییا ڕووداوی (ICP)",description:"چەوانیا ڕێڤەبرنا هەماهەنگییا مەیدانی ل دەمێ کارەساتان"},{kind:"image",src:"media/images/uni_09_span_control.png",title:"مەودایێ کۆنترۆلێ",description:"ڕوونکرنا بنەمایێ ١ سەرپەرشتیار بۆ ٥ کارمەندان"}],quiz:[{question:"ل دویڤ ICS/NIMS، ڕێژەیا پێشنیارکری یا مەودایێ کۆنترۆلێ (Span of Control) چەندە؟",options:[{text:"١٠ کەس",correct:!1},{text:"٥ کەس",correct:!0},{text:"٢ کەس",correct:!1},{text:"١٥ کەس",correct:!1}],explanation:"ل دویڤ NIMS، مەودایێ کۆنترۆلێ د ناڤبەرا ٣ و ٧ دا یە و ڕێژەیا ١ بۆ ٥ دهێتە پێشنیارکرن دا کو سەرپەرشتیار بشێت ب هووری چاڤدێرییا تیمێ بکەت."},{question:"کیش پشک بەرپرسە ژ دابینکرنا خوارن، ئاڤ و ئامێرێن پەیوەندیێ بۆ تیمان؟",options:[{text:"کارێن مەیدانی (Operations)",correct:!1},{text:"پلاندانان (Planning)",correct:!1},{text:"لۆجیستیک (Logistics)",correct:!0},{text:"دارایی (Finance)",correct:!1}],explanation:"پشکا لۆجیستیکێ بەرپرسە ژ دابینکرنا هەمی پێدڤییێن فیزیکی و خزمەتگوزارییان."},{question:"ئارمانجا سەرەکی ژ «زمانێ ڕوون» (Plain Language) د پەیوەندییان دا چییە؟",options:[{text:"بۆ کو خەلک تێنەگەهن",correct:!1},{text:"بۆ پشتڕاستبوون ژ هەماهەنگییا هەمی دەزگەهان بێ خەلەتی",correct:!0},{text:"بۆ کێمکرنا دەمژمێرێن کاری",correct:!1},{text:"بۆ جوانییا ئاخفتنێ",correct:!1}],explanation:"بکارئینانا زمانەکێ سادە و ڕوون (نە کۆد) دهێلیت کو پۆلیس، ئاگرکوژاندن و ئەمبوولانس ب دروستی ژ ئێک تێبگەهن."},{question:"کەنگێ «Unified Command» دهێتە بکارئینان؟",options:[{text:"دەمێ ڕووداوەکێ بچووک بیت",correct:!1},{text:"دەمێ تەنێ ئێک دەزگەهـ ل جهێ ڕووداوی بیت",correct:!1},{text:"دەمێ چەند دەزگەهـ یان چەند ناڤچەیێن ئیداری د ڕووداوی دا بەشدار ببن",correct:!0},{text:"چ جاران ناهێتە بکارئینان",correct:!1}],explanation:"دەمێ چەند دەزگەهـ یان چەند ناڤچەیێن ئیداری د ڕووداوەکێ دا بەشدار دبن، فەرماندەییا ئێکگرتی (Unified Command) دهێتە دانان دا کو هەمی لایەن ل سەر ئێک پلانێ کار بکەن."}]},{id:10,code:"TECH-1000",icon:"Satellite",accent:"#7c3aed",title:"تەکنۆلۆژیایا داهاتیێ و داهێنان",subtitle:"Future Technology in Emergency Response",summary:"ڕۆلێ فڕۆکەیێن بێ فڕۆکەڤان (UAVs)، ڕۆبۆتێن ئاگرکوژاندنێ، کامێرایێن گەرمیێ (Thermal)، ژیرییا دەستکرد (AI)، و سیستەمێن IoT د ڕزگارکرنێ دا.",blocks:[{body:"د دەهـ سالێن دووماهیێ دا، تەکنۆلۆژیایێ ب شێوەیەکێ بەرچاڤ شێوازێ کارێ بەرگرییا شارستانی و ڕزگارکرنێ گوهۆڕییە. ئامێرێن نوو و هەستەڤەرێن ژیر دشێن بچنە وان جهان یێن کو مرۆڤ ب زەحمەت دگەهیتێ، و ئەڤە دهێلیت پێزانینێن هوور ل سەر مەترسییان بهێنە کۆمکرن و هاریکاری بلەزتر بگەهیت. د ڤێ مۆدیوولێ دا، ئەم دێ باسێ وان تەکنۆلۆژیایان کەین یێن کو ئەڤرۆ دهێنە پێشئێخستن دا ببنە پشکەک ژ سیستەمێن پاراستنا شارستانی ل جیهانێ."},{heading:"١. فڕۆکەیێن بێ فڕۆکەڤان (Drones / UAVs)",body:"درۆن ئێکە ژ مەزنترین داهێنانان د بوارێ تەنگاڤیێ دا. ئەڤ ئامێرە دشێن کارێن مەیدانی یێن زەحمەت ئەنجام بدەن بێ کو ژیانا تیمێن ڕزگارکرنێ بکەڤیتە مەترسیێ:",points:["چاڤدێرییا ئاسمانی (Aerial Surveillance): درۆن دشێن وێنە و ڤیدیۆیێن ڕاستەوخۆ (Real-time) بۆ ناڤەندا فەرماندەییێ بفرێکن دا کو وێنەیێ گشتی یێ کارەساتێ دیار ببیت.","کامێرایێن گەرمیێ (Thermal Imaging): دیتنا کەسێن زیندی د ناڤ دارستانان دا، ل شەڤێ، یان د ناڤ دوکێلەکا ستوور دا ب ڕێکا هەستکرن ب گەرمییا لەشی.","گەهاندنا تەنگاڤیێ: هنارتنا دەرمان، کەرەستەیێن پزیشکی یان ئامێرێن پەیوەندیێ بۆ وان جهێن کو ب ئەگەرێ لافاو یان عەردەهەژینێ ڕێک لێ هاتینە گرتن.","نەخشەسازییا سێ-ڕەهەندی (3D): درۆن دشێن د دەمەکێ کورت دا نەخشەیەکا سێ-ڕەهەندی بۆ جهێ ڕووداوی دروست بکەن دا کو پلانا ڕزگارکرن و دەرکەفتنێ باشتر بهێتە دانان."]},{heading:"٢. ڕۆبۆتێن ئاگرکوژاندن و ڕزگارکرنا تەکنیکی",body:"ڕۆبۆت وەک هێزەکا پشتەڤان کار دکەن ل وان جهان یێن کو پلەیا گەرمیێ یان غازێن ژەهراوی ژ شیانا مرۆڤی دەرن:",points:["ڕۆبۆتێن ڤەمراندنێ: ئامێرێن مەزن یێن ژ دوور ڤە دهێنە کۆنترۆلکرن کو دشێن نێزیکی دلێ ئاگری ببن و ئاڤێ ب فشارەکا بلند بپژینن (وەک ڕۆبۆتێ Colossus).","ڕۆبۆتێن مار (Snake Robots): ڕۆبۆتێن باریک کو دشێن بچنە ناڤ کەلەبێن ئاڤاهیێن هەرفتی دا کو جهێ برینداران دیار بکەن.","ئێسکەپەیکەرێ دەرەکی (Exoskeletons): جلوبەرگێن میکانیکی یێن هێزدەر کو شیانێن لەشی یێن ئاگرکوژان زێدە دکەن بۆ هەلگرتنا بارێن گران ب ماندیبوونەکا کێمتر.","HazMat Robots: ڕۆبۆتێن تایبەت بۆ مامەلەکرن دگەل ماددەیێن ئەتۆمی و کیمیایی، دا کو مرۆڤ تووشی ژەهراویبوونێ نەبیت."]},{heading:"٣. ژیرییا دەستکرد و شیکارکرنا داتایێن مەزن (AI & Big Data)",body:"ژیرییا دەستکرد (Artificial Intelligence) دشێت د چەند چرکەیان دا ملیۆنان پێزانینان شیکار بکەت:",points:["پێشبینیکرنا مەترسییان: شیکارکرنا داتایێن کەشوهەوایێ و هەستەڤەران بۆ پێشبینیکرنا لافاوان یان مەترسییا ئاگرێ دارستانان بەری ڕوودانێ.","سیستەمێن بەرسڤدانا ژیر: AI دشێت هاریکارییا کارمەندێن وەرگرتنا بانگان بکەت بۆ پۆلێنکرنا پەیوەندییێن تەنگاڤیێ (١١٥) ل دویڤ گرنگیێ و هنارتنا تیمێ گونجای؛ بڕیارا دووماهیێ ل دەستێ مرۆڤی دمینیت.","دیتنا کۆمپیوتەری (Computer Vision): ناسینا ئاگر یان دوکێلێ ب ڕێکا کامێرایێن چاڤدێرییا باژێری ب شێوەیەکێ ئۆتۆماتیکی و ئاگەهدارکرنا بلەز."]},{heading:"٤. ئینتەرنێتا تشتان (IoT) و ئاڤاهیێن ژیر",body:"سیستەمێ IoT (Internet of Things) ئامێران ب تۆرەکێ ڤە گرێ ددەت دا کو ئاڤاهی ببیتە سیستەمەکێ هشیار:",points:["ئاڤاهیێن ژیر (Smart Buildings): هەستەڤەر دشێن ب شێوەیەکێ ئۆتۆماتیکی دەرگەهێن دژە-ئاگر دابخەن و سیستەمێ هەواگوهۆڕینێ ڕاوەستینن دا کو دوکێل بەلاڤ نەبیت.","ئامێرێن لبەرکری (Wearables): دەمژمێرێن ژیر بۆ تیمێن تەنگاڤیێ کو ئاستێ ئۆکسجینێ، لێدانا دلی و جهێ وان (GPS) بۆ ناڤەندا کۆنترۆلێ دفرێکن.","ترمبێلێن گرێدای: ترمبێلێن ئاگرکوژاندنێ کو دشێن ڕووناهییێن هاتنوچوونێ ب ئۆتۆماتیکی بکەنە کەسک (Traffic Signal Preemption) دا کو زووتر بگەهنە جهێ مەبەست."]},{heading:"٥. ڕاستییا گریمانەیی (VR) و ڕاستییا زێدەکری (AR)",body:"بکارئینانا تەکنۆلۆژیایا دیتنی بۆ ڕاهێنان و کارێن مەیدانی:",points:["ڕاهێنان ب VR: دهێلیت تیمێن ڕزگارکرنێ ل سەر سیناریۆیێن کارەساتێن مەزن ڕاهێنانێ بکەن بێ چ مەترسی.","AR د ناڤ کلاوان دا: هندەک کلاوێن (Helmet) نوو یێن ئاگرکوژاندنێ شاشەیەکا بچووک تێدا هەیە کو نەخشەیا ئاڤاهی و ئاستێ هەوایێ د تانکا SCBA دا د ناڤ دوکێلێ دا نیشان ددەت."]},{heading:"٦. تەکنۆلۆژیایا نانۆ و ماددەیێن نوو",body:"پێشئێخستنا کەرەستەیێن داهاتیێ بۆ پاراستنا لەشی:",points:["Nanotechnology: دروستکرنا جلوبەرگێن ئاگرکوژاندنێ یێن سڤکتر بەلێ ب بەرگرییەکا بلندتر ل هەمبەر گەرمیێ.","باترییێن نوو: باترییێن Sodium-ion یان Solid-state کو مەترسییا گڕگرتن و تەقینێ تێدا کێمترە ژ باترییێن لیتیۆم-ئایۆن یێن ئاسایی."]},{heading:"٧. ئاستەنگ و لایەنێ ئەخلاقی",body:"سەرەڕای مفایێن مەزن، تەکنۆلۆژیا چەندین پرسیارێن گرنگ پەیدا دکەت:",points:["تێچوون (Cost): بهایێ بلند یێ ڤان ئامێران ڕێگرە ل بەر وەرگرتنا وان ژ لایێ هەمی وەلاتان ڤە.","پاراستنا داتایان: مەترسییا هاککرنا سیستەمێن ئاڤاهیێن ژیر یان سیستەمێن فەرماندەییێ.","بڕیارێن AI: ئەرێ دروستە ژیرییا دەستکرد ل جهێ مرۆڤی بڕیارێ ل سەر ژیانا مرۆڤان بدەت ل دەمێ پۆلێنکرنا برینداران (Triage)؟"]}],media:[{kind:"video",src:"media/videos/uni_10_drone_thermal.mp4",title:"درۆن و دیتنا برینداران",description:"چەوانیا بکارئینانا کامێرایێن گەرمیێ بۆ دیتنا کەسان د ناڤ دارستانان دا"},{kind:"image",src:"media/images/uni_10_smart_helmet.jpg",title:"کلاوێ AR یێ ژیر",description:"نیشاندانا پێزانینێن ژینگەهێ ل سەر شاشەیا کلاوێ ئاگرکوژی"},{kind:"video",src:"media/videos/uni_10_robot_extinguish.mp4",title:"کارکرنا ڕۆبۆتێ ئاگرکوژاندنێ",description:"ڤەمراندنا ئاگرێ کارگەهەکێ ب کۆنترۆلا ژ دوور ڤە"}],quiz:[{question:"کامێرایێن گەرمیێ (Thermal Imaging) ل سەر درۆنان چەوا هاریکارییا تیمێن ڕزگارکرنێ دکەن؟",options:[{text:"بۆ وێنەگرتنا ڕەنگاوڕەنگ",correct:!1},{text:"بۆ دیتنا لەشێ مرۆڤی ب ڕێکا گەرمیێ د تاریاتی و دوکێلێ دا",correct:!0},{text:"بۆ ڤەمراندنا ئاگری",correct:!1},{text:"بۆ پەیوەندیکرن ب مۆبایلێ ڤە",correct:!1}],explanation:"لەشێ مرۆڤی ژ ژینگەها دەوروبەر گەرمترە، ژبەرهندێ کامێرایێن Thermal دشێن جهێ مرۆڤی ب ڕوونی نیشان بدەن، ب تایبەتی ل شەڤێ و د ناڤ دوکێلێ دا. ل ژێر کەڤر و کۆنکریتێ، شیانا وان سنووردارە."},{question:"مفایێ سەرەکی یێ Exoskeletons بۆ کارمەندێن بەرگرییا شارستانی چییە؟",options:[{text:"بۆ فڕینێ د هەوایێ دا",correct:!1},{text:"زێدەکرنا شیانا لەشی بۆ هەلگرتنا بارێن گران و کێمکرنا ماندیبوونێ",correct:!0},{text:"بۆ پاقژکرنا ئاڤێ",correct:!1},{text:"بۆ ڤەکۆلینا کیمیایی",correct:!1}],explanation:"ئەڤ جلوبەرگێن میکانیکی هێزێ ددەنە ماسولکەیێن مرۆڤی دا کو بشێت بریندار یان ئامێرێن گران ب ساناهیتر هەلگریت."},{question:"مەبەست ژ ئاڤاهیێ ژیر (Smart Building) د بوارێ سەلامەتیێ دا چییە؟",options:[{text:"ئاڤاهییەکێ جوانە",correct:!1},{text:"ئاڤاهییەکە کو هەستەڤەر و ئامێرێن وی ب تۆرێ ڤە گرێداینە بۆ بەرسڤدانا ئۆتۆماتیکی ل هەمبەر مەترسییان",correct:!0},{text:"ئاڤاهییەکە کو تەنێ ژ شووشەی هاتییە دروستکرن",correct:!1},{text:"ئاڤاهییەکێ بێ کارەبا یە",correct:!1}],explanation:"د ئاڤاهیێن ژیر دا، سیستەم ب خوە مەترسیێ دبینیت و بێ دەستێوەردانا مرۆڤی دەرگەهان دادخەت، هەواگوهۆڕینێ ڕادوەستینیت و تیمان ئاگەهدار دکەت."},{question:"ژیرییا دەستکرد (AI) چەوا دشێت پێشبینییا کارەساتان بکەت؟",options:[{text:"ب جادوویێ",correct:!1},{text:"ب شیکارکرنا داتایێن مەزن یێن کەشوهەوایێ و هەستەڤەرێن عەردی",correct:!0},{text:"ب تەلەفۆنکرنا خەلکی",correct:!1},{text:"نەشێت پێشبینیێ بکەت",correct:!1}],explanation:"AI پشت ب داتایێن سالێن بۆری و گوهۆڕینێن نوو دبەستیت دا کو دیار بکەت کا ئەگەرا مەترسیێ ل کیرێ پترە؛ پێشبینی ئەگەرە، نە پشتڕاستییەکا تەمام."}]},{id:11,code:"QUAKE-1100",icon:"Activity",accent:"#ea580c",title:"عەردەهەژینزانی و ئەندازیارییا سەلامەتیێ",subtitle:"Seismology & Earthquake Resistant Design",summary:"شیکارکرنا زانستی یا پلێتێن تەکتۆنیکی، شەپۆلێن عەردەهەژینێ، دیاردەیا شلبوونا ئاخێ، دیزاینا ئاڤاهیێن بەرگر، و ڕێکارا Drop, Cover, Hold On ل دەمێ لەرزینێ.",blocks:[{body:`عێراق و هەرێما کوردستانێ ل سەر ناڤچەیەکا چالاک یا عەردەهەژینێ نە، ب تایبەتی ناڤچەیێن باکوور و ڕۆژهەلات کو نێزیکی زنجیرەچیایێن زاگرۆسێ نە. ئەڤ ناڤچەیە ژ ئەنجامێ لێکدانا پلێتا عەرەبی دگەل پلێتا ئۆراسیا دروست بوویە. د ڤێ مۆدیوولێ دا، ئەم دێ ب شێوەیەکێ ئەکادیمی باسێ فیزیایا عەردەهەژینێ و ڕێکارێن ئەندازیاری یێن پاراستنا ژیان و ئاڤاهییان کەین.

پاراستنا کەسی ل دەمێ لەرزینێ (Drop, Cover, Hold On): ل جهێ خوە بکەڤە سەر عەردی (Drop)، سەر و ستوویێ خوە ل بن مێزەکا ب هێز بپارێزە (Cover)، و ب پێیێ مێزێ بگرە هەتا لەرزین ڕادوەستیت (Hold On)، دوور ژ پەنجەرە و ئامێرێن گران. نەچە بن دەرگەهی و پشت ب «سێگۆشەیا ژیانێ» (Triangle of Life) نەبەستە؛ ئەو ڕێکارێن پەسەندکری نینن. ل دەمێ لەرزینێ نەڕەڤە دەرڤە و ئەسانسۆرێ بکار نەئینە. پشتی لەرزینێ، تەنێ ئەگەر بێهنا غازێ هات یان تە دەنگێ دەرچوونێ بیست، غازێ بگرە.`},{heading:"١. میکانیزما عەردەهەژینێ و پلێتێن تەکتۆنیکی",body:"عەردەهەژین پرۆسەیەکا فیزیایی یا ئالۆزە کو ل دویڤ تیۆریا «ڤەگەڕانا لاستیکی» (Elastic Rebound) ڕوودەت:",points:["پلێتێن تەکتۆنیکی: توێکلێ عەردی ژ چەند پارچەیێن مەزن پێک دهێت کو ل سەر چینەکا نەرمتر دلڤن. پلێتا عەرەبی هەر سال نێزیکی دوو سانتیمەتران بەرەڤ باکوور-ڕۆژهەلاتێ دچیت.","ناڤەند و سەرناڤەند: ناڤەندا عەردەهەژینێ (Hypocenter) ئەو خالە یا ل بن عەردی کو وزە لێ ئازاد دبیت. سەرناڤەند (Epicenter) خالا ل سەر ڕووێ عەردی یە کو ڕاستەوخۆ دکەڤیتە سەر ناڤەندێ، کو گەلەک جاران وێرانییا هەرە مەزن ل نێزیکی وێ ڕوودەت.","هێلێن شکەستنێ (Faults): زانینا هێلێن شکەستنێ یێن وەک پشتێنا زاگرۆسێ (Zagros Fold-Thrust Belt) بۆ ئەندازیارێن شارستانی ل دەمێ دیزاینکرنا پرۆژەیان گەلەک پێدڤییە."]},{heading:"٢. شیکارکرنا شەپۆلێن عەردەهەژینێ (Seismic Waves)",body:"وزەیا عەردەهەژینێ ب شێوەیێ شەپۆلان بەلاڤ دبیت، کو دهێنە دابەشکرن بۆ سێ جۆرێن سەرەکی:",points:["شەپۆلێن P (Primary): بلەزترین شەپۆلن و وەک پالدانەکێ د ناڤ هەمی ماددەیان (ڕەق، شل و غاز) دا دچن. ئەڤە ئێکەم شەپۆلن کو ئامێرێن سیسمۆگرافی تۆمار دکەن.","شەپۆلێن S (Secondary): هێدیترن بەلێ لەرزینا وان ب هێزترە. تەنێ د ناڤ ماددەیێن ڕەق دا دچن، و لڤینا وان ستوونی ل سەر ئاراستەیا چوونێ یە (ب لایان یان سەر و خوار)، و زیانێن مەزن دگەهیننە ئاڤاهییان.","شەپۆلێن ڕووی (Surface Waves): ل سەر ڕووێ عەردی دلڤن، درێژترین ماوە دکێشن، و ئەگەرێ سەرەکی یێ وێرانییا مەزن یا باژێران نە."]},{heading:"٣. پێڤەرێن زانستی و دیاردەیا شلبوونا ئاخێ",body:"بۆ دیارکرنا هێزا عەردەهەژینێ، دڤێت جیاوازی د ناڤبەرا مەزنیێ (Magnitude) و توندیێ (Intensity) دا بهێتە کرن:",points:["پێڤەرا مەزنیێ (Magnitude): وزەیا ئازادبووی دپێڤیت. ئەڤرۆ پێڤەرا Moment Magnitude (Mw) دهێتە بکارئینان کو جهێ پێڤەرا ڕیختەری گرتییە. هەر پلەیەکا زێدە = ١٠ جاران مەزنییا شەپۆلێ ل سەر سیسمۆگرافی و نێزیکی ٣٢ جاران وزەیا پتر.","پێڤەرا مێرکالی یا گوهۆڕی (Modified Mercalli Intensity): توندییا لەرزینێ ل دویڤ کارتێکرنا وێ ل سەر مرۆڤ و ئاڤاهییان ل هەر جهەکێ دپێڤیت.","شلبوونا ئاخێ (Liquefaction): ل ناڤچەیێن ئاخا خیزی و تەڕ، لەرزین دهێلیت ئاخ تایبەتمەندییا خوە یا ڕەق ژ دەست بدەت و وەک شلەمەنیێ لێ بهێت، و ئەڤە دبیتە ئەگەرێ نقوومبوون یان وەرگەڕانا ئاڤاهییان."]}],media:[{kind:"video",src:"media/videos/uni_11_seismic_waves.mp4",title:"فیزیایا شەپۆلان",description:"شیکارکرنا لڤینا شەپۆلێن P و S د ناڤ عەردی دا"},{kind:"image",src:"media/images/uni_11_building_design.png",title:"ئەندازیارییا دژە-لەرزینێ",description:"تەکنیکا جوداکرنا بنیاتی (Base Isolation) بۆ پاراستنا ئاڤاهییان"}],quiz:[{question:"کیش جۆرێ شەپۆلان بلەزترینە و ئێکەم جار دگەهیتە وێستگەهێن سیسمۆگرافی؟",options:[{text:"S-Waves",correct:!1},{text:"P-Waves",correct:!0},{text:"Surface Waves",correct:!1},{text:"Love Waves",correct:!1}],explanation:"شەپۆلێن P (Primary) بلەزترین شەپۆلن و د ناڤ هەمی جۆرێن ماددەیان دا دچن."}]},{id:12,code:"PLAN-1200",icon:"ClipboardList",accent:"#4f46e5",title:"پلاندانانا تەنگاڤیێ و ئامادەکاری",subtitle:"Emergency Planning & Family Preparedness",summary:"دانانا پلانا دەرکەفتنا تەنگاڤیێ بۆ مالباتێ و جهێن کاری، و ئامادەکرنا پێدڤییێن سەرەکی یێن مانێ.",blocks:[{body:"پلاندانان بەری هەر کارەساتەکێ، باشترین ڕێکە بۆ کێمکرنا ترسێ و پاراستنا ژیانێ. د ڤێ مۆدیوولێ دا، ئەم دێ فێر بین چەوا پلانەکا زانستی بۆ مالبات و دامەزراوەیان دانێین کو هەمی ئەگەرێن مەترسیێ بگریتە خوە."},{heading:"١. پلانا تەنگاڤیێ یا مالباتێ",body:"هەر مالباتەک پێدڤییە ل سەر پلانەکا ڕوون ڕێک بکەڤیت:",points:["ڕێڕەوێن دەرکەفتنێ: دیارکرنا دوو ڕێکان ژ هەر ژوورەکا خانی، دا کو ئەگەر ئێک هاتە گرتن، یا دی بهێتە بکارئینان.","خالێن کۆمبوونێ: دیارکرنا دوو جهان: ئێک ل نێزیکی خانی، و ئێک ل دەرڤەی ناڤچەیێ ئەگەر زڤڕین بۆ خانی نەگونجا.","پەیوەندییا دەرەکی: هەبوونا ژمارەیا کەسەکێ نێزیک کو ل دەرڤەی باژێری دژیت، دا کو ببیتە خالا پەیوەندیێ د ناڤبەرا ئەندامێن مالباتێ دا."]},{heading:"٢. جانتایا تەنگاڤیێ (Survival Kit)",body:"دڤێت کەرەستەیێن پێدڤی بۆ لایێ کێم ٧٢ دەمژمێران (٣ ڕۆژان) ئامادە بن:",points:["ئاڤ و خوارن: نێزیکی ٤ لیتر ئاڤ بۆ هەر کەسەکی د ڕۆژێ دا، بۆ لایێ کێم ٣ ڕۆژان، دگەل خوارنا کو خراب نابیت وەک قوتیکان.","ڕووناهی و پەیوەندی: فانووس یان چرایێ دەستی، باترییێن زێدە، و ڕادیۆیەکا ب باتری بۆ گوهداریکرنا پێزانینێن فەرمی.","پێدڤییێن پزیشکی: دەرمانێن تایبەت یێن ئەندامێن مالباتێ و جانتایا هەوارهاتنا ئێکێ."]}],media:[{kind:"video",src:"media/videos/uni_12_plan_making.mp4",title:"چەوانیا دانانا پلانێ",description:"هەنگاڤێن دروستکرنا نەخشەیا دەرکەفتنێ ژ ئاڤاهی"}],quiz:[{question:"جانتایا تەنگاڤیێ دڤێت پێدڤییێن مالباتێ بۆ لایێ کێم چەند ڕۆژان دابین بکەت؟",options:[{text:"١ ڕۆژ",correct:!1},{text:"٣ ڕۆژ (٧٢ دەمژمێر)",correct:!0},{text:"١ هەفتە",correct:!1},{text:"١ مانگ",correct:!1}],explanation:"ڕێنماییێن ئامادەکاریێ (وەک Ready.gov و FEMA) ئامادەکرنا پێدڤییان بۆ لایێ کێم ٧٢ دەمژمێران (٣ ڕۆژان) پێشنیار دکەن، چونکی ل دەستپێکا کارەساتەکا مەزن هاریکاری دشێت دەرەنگ بگەهیت."}]},{id:13,code:"FLOOD-1300",icon:"Waves",accent:"#2563eb",title:"لافاو و ڕێکارێن پاراستنێ ژ ئاڤێ",subtitle:"Flood Dynamics & Water Rescue",summary:"تێگەهشتن ژ جۆرێن لافاوان، پاراستنا ترمبێلان، و بنەمایێن ڕزگارکرنا تەنگاڤیێ د ناڤ ئاڤێ دا.",blocks:[{body:"لافاو ئێکە ژ کارەساتێن هەرە بەلاڤ ل هەرێما کوردستانێ. تەنێ چەند سانتیمەترێن ئاڤا ب لڤین دشێن کارەساتێن مەزن دروست بکەن. د ڤێ مۆدیوولێ دا، ئەم دێ باسێ پاراستنا ژیانێ و ترمبێلان ل دەمێ بلندبوونا ئاڤێ کەین. چ جاران ب پێیان یان ب ترمبێلێ نەچە د ناڤ ئاڤا لافاوێ دا، و پەیوەندیێ ب ١١٥ بکە."},{heading:"١. جۆرێن لافاوان و مەترسییا وان",body:"لافاو ل دویڤ لەز و جهی دهێنە پۆلێنکرن:",points:["لافاوا ژنشکەکێ ڤە (Flash Flood): د ماوەیێ کێمتر ژ ٦ دەمژمێران دا پشتی بارانا توند ڕوودەت، و مەترسیدارترین جۆرە چونکی دەمێ ئامادەکاریێ گەلەک کێمە.","مەترسی ل سەر ترمبێلان: تەنێ ٣٠ سم ئاڤا ب لڤین بەسە بۆ ڕاکرن و برنا پترییا ترمبێلان ژ جهێ وان.","مەترسی ل سەر مرۆڤی: ١٥ سم ئاڤا ب لڤین دشێت مرۆڤی بێخیتە عەردی و ببیتە ئەگەرێ خەندقینێ."]},{heading:"٢. ڕێکارێن ڕزگارکرنێ: Reach, Throw, Row, Go",body:"ئەگەر تە کەسەک د ناڤ ئاڤێ دا دیت، پێشی پەیوەندیێ ب ١١٥ بکە، پاشان ڤان هەنگاڤان ب ڕێزبەندی جێبەجێ بکە:",points:["REACH: ب دارەکێ یان تشتەکێ درێژ بگەهە کەسی بێ کو تو بچیە ناڤ ئاڤێ.","THROW: تشتەکێ ل سەر ئاڤێ دمینیت (وەک تایەرەکێ یان وەریسەکێ ب تشتەکێ سڤک ڤە) بۆ وی بهاڤێژە.","ROW: ئەگەر بەلەمەک و ڕاهێنان هەبن، بۆ نێزیکبوونا سەلامەت بکار بینە.","GO: تەنێ تیمێن پسپۆر دشێن بچنە د ناڤ ئاڤێ دا؛ چ جاران وەک خوەبەخش نەچە د ناڤ ئاڤا لافاوێ دا."]}],media:[{kind:"video",src:"media/videos/uni_13_water_safety.mp4",title:"پاراستن ژ لافاوێ",description:"ڕێکارێن دروست بۆ مامەلەکرن دگەل هێزا ئاڤێ"}],quiz:[{question:"لایێ کێم چەند سانتیمەتر ئاڤا ب لڤین بەسە بۆ ڕاکرن و برنا ترمبێلەکا ئاسایی؟",options:[{text:"١٠ سم",correct:!1},{text:"٣٠ سم",correct:!0},{text:"١٠٠ سم",correct:!1},{text:"٥ سم",correct:!1}],explanation:"٣٠ سانتیمەتر (١٢ ئینچ) ئاڤا ب لڤین بەسە بۆ ڕاکرن و برنا پترییا ترمبێلان؛ تەنانەت ئاڤەکا کێمتر ژی دشێت کۆنترۆلا ترمبێلێ نەهێلیت."}]},{id:14,code:"GAS-1400",icon:"Fuel",accent:"#ca8a04",title:"سەلامەتییا غازێ و فیزیایا تەقینێ",subtitle:"Natural Gas & LPG Advanced Safety",summary:"شیکارکرنا چڕییا غازێ بەرامبەر هەوایێ، سنوورێن تەقینێ (LEL/UEL)، و ستراتیژییێن بەرگرییا شارستانی بۆ کۆنترۆلکرنا دەرچوونا غازێ.",blocks:[{body:"غازا سۆتێنەر د پیشەسازی و مالان دا سەرچاڤەیەکا سەرەکی یا وزەیێ یە، بەلێ ب کێمترین خەلەتی دشێت ببیتە بۆمبەکا وێرانکەر. د ڤێ مۆدیوولێ دا، ئەم دێ باسێ داینامیکا غازێ کەین: ژ چڕییا هەلمێ هەتا پلەیا گڕگرتنا خوەکار. تێگەهشتن ژ ڤان پێزانینان بۆ هەر ئەندازیارەکێ سەلامەتیێ پێدڤییە دا کو بشێت سیستەمێن پاراستنێ ل دویڤ ستانداردێن NFPA دیزاین بکەت."},{heading:"١. فیزیایا غازێ و چڕییا هەلمێ (Vapor Density)",body:"بۆ ڕێگرتن ل کۆمبوونا غازێ، دڤێت تو بزانی کا غاز ژ هەوایێ سڤکترە یان گرانترە (هەوا = ١):",points:["غازا سروشتی (Methane): ژ هەوایێ سڤکترە (نێزیکی ٠.٥٥). ئەگەر دەرچوون هەبیت، بەرەڤ سەری دچیت و ل بن سەقفی کۆم دبیت؛ ژبەرهندێ هەواگوهۆڕینا ل جهێن بلند پێدڤییە.","غازا LPG (Propane/Butane): ژ هەوایێ گرانترە (نێزیکی ١.٥ هەتا ٢). ل دەمێ دەرچوونێ، وەک ئاڤێ ل سەر عەردی و جهێن نزم (ژێرزەمین، کەندال) کۆم دبیت. ئەڤە گەلەک مەترسیدارە چونکی دشێت بگەهیتە پریسکێن سویچ و ئامێرێن نزم.","بێهندارکرنا غازێ (Mercaptan): غازا پاقژ بێ بێهنە، ژبەرهندێ کۆمپانی ماددەیێن مەرکاپتانی (وەک Ethyl Mercaptan) تێکەل دکەن دا کو مرۆڤ ب بێهنێ هەست ب مەترسیێ بکەت."]},{heading:"٢. سنوورێن تەقینێ (Flammability Limits - LEL/UEL)",body:"غاز تەنێ دەمێ دتەقیت کو ڕێژەیا وێ د هەوایێ دا د ناڤبەرا دوو سنووران دا بیت:",points:["سنوورێ خوارێ (LEL): کێمترین ڕێژەیا غازێ د هەوایێ دا کو دشێت گڕ بگریت. ئەگەر غاز ژ ڤێ کێمتر بیت، تەقین ڕوو نادەت.","سنوورێ سەرێ (UEL): بلندترین ڕێژەیا غازێ؛ ئەگەر غاز ژ ڤێ پتر بیت، ئۆکسجین بەس نینە و تەقین ڕوو نادەت (بەلێ دەمێ ب هەوایێ تێکەل دبیت و دگەهیتە د ناڤبەرا هەردوو سنووران دا، دێ گڕ گریت).","مەترسییا خەندقینێ: کۆمبوونا غازێ ل جهێن داخستی جهێ ئۆکسجینێ دگریت و دشێت ببیتە ئەگەرێ مرنەکا بێ دەنگ (Asphyxiation)."]},{heading:"٣. ڕێکارێن تەکنیکی یێن تەنگاڤیێ",body:"ل دەمێ هەستکرن ب دەرچوونا غازێ، بەرگرییا شارستانی ڤان ڕێسایان پەیڕەو دکەت:",points:["قەدەغەکرنا پریسکان: پێلێکرنا سویچێ کارەبایێ، بکارئینانا تەلەفۆنێ یان هەر ئامێرەکێ کارەبایی ل ناڤ جهی، یان هەر گڕەکا ئاشکەرا، دشێت وزەیا پێدڤی بۆ تەقینێ دابین بکەت.","جێبەجێکرن: ڤەکرنا دەرگەهـ و پەنجەرەیان (بێ پێکرنا پانکەیێن کارەبایی)، گرتنا وەلڤا سەرەکی ئەگەر ب سەلامەتی بگونجیت، دەرئێخستنا خەلکی بێ دەنگەدەنگ، و پەیوەندیکرن ب ١١٥ ژ دەرڤەی جهی."]}],media:[{kind:"video",src:"media/videos/gov_14_gas_physics.mp4",title:"داینامیکا تەقینا غازێ",description:"شیکارکرنا تاقیگەهی ل سەر سنوورێن LEL و UEL"},{kind:"image",src:"media/images/gov_14_gas_detectors.png",title:"هەستەڤەرێن پیشەسازی",description:"جۆرێن ئامێرێن دیتنا دەرچوونا غازێ ل کارگەهان"}],quiz:[{question:"بۆچی غازا LPG ل دەمێ دەرچوونێ ل سەر عەردی کۆم دبیت؟",options:[{text:"چونکی سارە",correct:!1},{text:"چونکی ژ هەوایێ گرانترە",correct:!0},{text:"چونکی بێهنەکا توند هەیە",correct:!1},{text:"چونکی غازا سروشتی یە",correct:!1}],explanation:"LPG ژ هەوایێ گرانترە (Vapor Density > 1)، ژبەرهندێ بەرەڤ خوارێ دچیت و ل جهێن نزم کۆم دبیت."}]},{id:15,code:"PLAN-1500",icon:"Landmark",accent:"#4f46e5",title:"پلاندانانا ستراتیژی یا تەنگاڤیێ",subtitle:"Institutional Emergency & Continuity Planning",summary:"دانانا پلانێن دەرکەفتنێ بۆ دامودەزگەهێن حکومی، ڕێڤەبرنا قەیرانان، و پشتڕاستبوون ژ بەردەوامییا کاران.",blocks:[{body:"پلاندانان بەری کارەساتێ، جیاوازییا د ناڤبەرا سەرکەفتن و کارەساتێ دا دیار دکەت. ئەڤ مۆدیوولە بۆ ڕێڤەبەر و ئەفسەرێن بەرگرییا شارستانی هاتییە ئامادەکرن، دا کو بزانن چەوا «پلانا بەرسڤدانا تەنگاڤیێ» (Emergency Response Plan - ERP) بۆ ئاڤاهیێن حکومی و بازرگانی دانێن."},{heading:"١. ڕەگەزێن سەرەکی یێن پلانا ERP",body:"هەر پلانەکا باش پێدڤییە ئەڤ سێ پشکە تێدا هەبن:",points:["ستراتیژییا دەرکەفتنێ (Evacuation): نەخشەکێشانا ڕێڕەوێن دەرکەفتنێ و پشتڕاستبوون کو چ ئاستەنگ د ڕێکا خەلکی و تیمێن تەنگاڤیێ دا نینن.","خالێن کۆمبوونێ (Assembly Points): دیارکرنا جهێن سەلامەت ل دەرڤەی ئاڤاهی، دوور ژ ئاڤاهی و ڕێکا ترمبێلێن تەنگاڤیێ، کو د پشکنینا ئەندازیاری دا هاتبنە پەسەندکرن.","زنجیرەیا فەرماندەییێ (Chain of Command): دیارکرنا بەرپرسیارییان: کێ فەرمانا دەرکەفتنێ ددەت و کێ پەیوەندیێ ب تیمێن دەرەکی (١١٥ و ١٢٢) دکەت."]},{heading:"٢. کەرەستەیێن مانێ و سەرچاڤەیێن بەردەوام (Survival Logistics)",body:"ئامادەکرنا کەرەستەیێن ژیانێ بۆ خولەکێن ئێکێ یێن ڕووداوی و بۆ ٧٢ دەمژمێرێن ئێکێ یێن کارەساتەکا مەزن:",points:["کەرەستەیێن پزیشکی: سندۆقێن برینان (Trauma Kit) کو کەرەستەیێن ڕاگرتنا خوینبەربوونا مەترسیدار (وەک تۆرنیکێتێ و گازا تژیکرنێ) تێدا بن.","پەیوەندییێن یەدەک: ڕادیۆیێن VHF/UHF و تەلەفۆنێن سەتەلایتی (Satellite) بۆ دەمێ بڕینا تۆرێن پەیوەندیێ.","سەرچاڤەیێن سەرەکی: ئامادەکرنا ئاڤ و وزەیا باتری یان مۆلیدەیان بۆ تیمێن کارگێڕی ل دەمێ مانا د ناڤچەیا کارەساتێ دا."]}],media:[{kind:"video",src:"media/videos/gov_15_emergency_drills.mp4",title:"ڕاهێنانێن مەیدانی",description:"چەوانیا ئەنجامدانا ڕاهێنانێن دەرکەفتنێ ل فەرمانگەهان"}],quiz:[{question:"ئارمانجا سەرەکی ژ خالێن کۆمبوونێ (Assembly Points) چییە؟",options:[{text:"بۆ نیشاندانا جوانییا ئاڤاهی",correct:!1},{text:"بۆ هەژمارتنا کارمەندان و پشتڕاستبوون ژ سەلامەتییا هەمی کەسان",correct:!0},{text:"بۆ کۆمکرنا پاشماوەیان",correct:!1},{text:"بۆ ڕاوەستاندنا ترمبێلان",correct:!1}],explanation:"خالێن کۆمبوونێ دهێنە بکارئینان دا کو بهێتە زانین کا هەمی کەس ژ ئاڤاهی دەرکەفتینە یان کەسەک د ناڤ مەترسیێ دا مایە."}]},{id:16,code:"SAR-1600",icon:"Construction",accent:"#16a34a",title:"لێگەڕیان و ڕزگارکرنا پێشکەفتی (USAR)",subtitle:"Urban Search and Rescue & Structural Collapse",summary:"تەکنیکێن ڕزگارکرنێ ژ بن کاڤلان، سیستەمێ نیشانکرنێ یێ INSARAG، و بکارئینانا ئامێرێن گوهدارکرن و لێگەڕیانێ.",blocks:[{body:"لێگەڕیان و ڕزگارکرن ل باژێران (Urban Search and Rescue - USAR) کارەکێ هەستیار و مەترسیدارە. پشتی عەردەهەژینێ یان هەرفتنا ئاڤاهیێن بلند، تیمێن پسپۆر پێدڤی ب زانیارییێن ئەندازیاری هەنە دا کو بزانن پارچەیێن کۆنکریتی چەوا دلڤن. ئەڤ مۆدیوولە ل دویڤ ڕێنماییێن نێڤدەولەتی یێن INSARAG هاتییە ئامادەکرن."},{heading:"١. قۆناغێن ڕزگارکرنێ (Phases of Rescue)",body:"پرۆسەیا ڕزگارکرنێ ب ڤێ ڕێزبەندیێ دهێتە ئەنجامدان:",points:["پشکنینا گشتی (Size-up / Reconnaissance): هەلسەنگاندنا ئاستێ زیانێ، جێگیرییا ئاڤاهی و مەترسییێن وەک غاز و کارەبایێ.","ڕزگارکرنا ل سەر ڕووی (Surface Rescue): دەرئێخستنا وان کەسێن ل بەر چاڤ و یێن ب ساناهی مرۆڤ دشێت بگەهیتە وان.","لێگەڕیان د بۆشاییان دا (Void Space Search): دیتنا برینداران د ناڤ کون و بۆشاییێن ئاڤاهیێن هەرفتی دا ب کامێرایێن هوور و ئامێرێن گوهدارکرنێ.","لادانا هلبژارتی یا کاڤلان (Selected Debris Removal): لادانا پارچەیێن دیارکری ب هووری و ب ئامرازێن دەستی و هایدرۆلیکی دا کو بگەهنە برینداران؛ پاشان لادانا گشتی یا کاڤلان ب ئامێرێن گران."]},{heading:"٢. سیستەمێ نیشانکرنێ یێ نێڤدەولەتی (INSARAG Marking)",body:"تیمێن USAR نیشانێن ستاندارد ل سەر دیوارێن ئاڤاهییان دکەن دا کو پێزانینان بۆ تیمێن پشتی خوە بهێلن:",points:["نیشانا جهێ کاری (Worksite Marking): ل دویڤ INSARAG، تیم ناسناما جهێ کاری (پیتا ناڤچەیێ و ژمارەیا جهێ کاری، وەک C-6) ل سەر ئاڤاهی دنڤیسیت دا کو هەمی تیم ب ئێک ناڤی بزانن. سیستەمێ X یێ چار-پشکی (ناڤێ تیمێ، دەم و ڕێکەفت، مەترسی، قوربانی) سیستەمێ FEMA یە ل ئەمریکا.","نیشانا قوربانییان (Victim Marking): پیتا مەزن (V) ل نێزیکی جهێ قوربانییەکێ ئەگەری یان پشتڕاستکری دهێتە نڤیسین؛ ل بن وێ، (L) دگەل ژمارەیەکێ بۆ کەسێن زیندی و (D) دگەل ژمارەیەکێ بۆ مرییان. دەمێ قوربانی دهێتە دەرئێخستن، نیشان دهێتە خێزکرن."]}],media:[{kind:"video",src:"media/videos/gov_16_search_tech.mp4",title:"تەکنۆلۆژیایا لێگەڕیانێ",description:"بکارئینانا ئامێرێن گوهدارکرنێ و ڕاداری بۆ دیتنا دەنگ و لڤینێن برینداران ل بن کاڤلان"},{kind:"image",src:"media/images/gov_16_marking_standard.png",title:"ڕێنماییێن INSARAG",description:"چەوانیا نڤیسینا پێزانینان ل سەر ئاڤاهیێن هەرفتی"}],quiz:[{question:"ل دویڤ INSARAG، پیتا (L) ل بن نیشانا (V) ل سەر دیوارێ ئاڤاهی نیشانا چییە؟",options:[{text:"دەرچوونا غازێ",correct:!1},{text:"هەبوونا کەسێن زیندی (Live)",correct:!0},{text:"هەرفتنا تەمام",correct:!1},{text:"ب دووماهی هاتنا پشکنینێ",correct:!1}],explanation:"L کورتییا Live یە؛ دگەل ژمارەیەکێ نیشان ددەت کا چەند قوربانییێن زیندی یێن پشتڕاستکری ل وی جهی هەنە."}]},{id:17,code:"TRAFFIC-1700",icon:"CarFront",accent:"#dc2626",title:"ڕووداوێن هاتنوچوونێ و دەرئێخستنا تەکنیکی",subtitle:"Advanced Vehicle Extrication & Road Safety",summary:"مامەلەکرن دگەل ڕووداوێن هاتنوچوونێ یێن توند، بکارئینانا ئامێرێن هایدرۆلیکی (Jaws of Life)، و پاراستنا ستوینا پشتێ.",blocks:[{body:"ڕووداوێن هاتنوچوونێ ئێکن ژ سەرەکیترین کارێن ڕۆژانە یێن بەرگرییا شارستانی. د ڤێ مۆدیوولێ دا، ئەم دێ باسێ قۆناغێن دەرئێخستنا برینداران ژ ناڤ ترمبێلان کەین، بێ کو زیانێن زێدەتر بگەهنە ستوینا پشتێ و ستووی. د هەمی ڕووداوێن ب بریندار دا، پەیوەندیێ ب ١١٥ و ١٢٢ بکە."},{heading:"١. سەلامەتییا جهێ ڕووداوی (Scene Safety)",body:"بەری هەر دەستێوەردانەکێ، دڤێت جهێ ڕووداوی بهێتە سەلامەتکرن:",points:["ناڤچەیا هشیاریێ: دیارکرنا ناڤچەیا مەترسیێ (Danger Zone) و دانانا نیشان و کۆنان بەری ڕووداوی ب مەودایەکێ گونجای دگەل لەزا ڕێکێ، و هەماهەنگی دگەل پۆلیسا هاتنوچوونێ (١٠٤).","جێگیرکرنا ترمبێلێ (Vehicle Stabilization): بکارئینانا پارچەیێن دار یان پالپشتان (Cribbing/Blocks) ل بن ترمبێلێ و ل پێش و پشت تایەران دا کو ل دەمێ کاری نەلڤیت.","بڕینا وزەیێ: بڕینا وایەرێ نێگەتیڤ یێ باتریێ بۆ کێمکرنا مەترسییا ئاگری و تەقینا نەخوازیاری یا کیسکێن هەوایێ (Airbags). تێبینی: کیسکێن هەوایێ دشێن پشتی بڕینا باتریێ ژی بۆ ماوەیەکێ کورت ئامادە بمینن، و ترمبێلێن هایبرید و کارەبایی سیستەمێن ڤۆلتاژا بلند هەنە."]},{heading:"٢. تەکنیکێن دەرئێخستنێ ب «Jaws of Life»",body:"بکارئینانا هێزا هایدرۆلیکی بۆ گوهۆڕینا شێوەیێ لەشێ ترمبێلێ:",points:["بڕین (Cutting): بڕینا ستوینێن (A, B, C) یێن ترمبێلێ دا کو سەقف ب تەمامی بهێتە لادان.","ڤەکرن (Spreading): ڤەکرنا دەرگەهێن چەمیای و دروستکرنا بۆشاییێ بۆ تیمێن پزیشکی.","پاراستنا ستووی: بەری هەر لڤینەکێ، سەرێ برینداری ب دەستان جێگیر بکە (Manual In-line Stabilization)، و ئەگەر پێدڤی بوو ل دویڤ پرۆتۆکۆلا پزیشکی پشتێنا ستووی (C-Collar) بکار بینە."]}],media:[{kind:"video",src:"media/videos/gov_17_extrication_tech.mp4",title:"دەرئێخستنا تەکنیکی",description:"شێوازێ بڕینا ئاسنی ب ئامێرێن هایدرۆلیکی"},{kind:"image",src:"media/images/gov_17_airbag_safety.png",title:"سەلامەتییا Airbag",description:"مەترسییێن تەقینا نەخوازیاری یا کیسکا هەوایێ ل دەمێ ڕزگارکرنێ"}],quiz:[{question:"بۆچی جێگیرکرنا ترمبێلێ (Stabilization) ئێکەم هەنگاڤە بەری دەرئێخستنا برینداری؟",options:[{text:"بۆ جوانیێ",correct:!1},{text:"دا کو ترمبێل نەلڤیت و برینێن ستووی و پشتا برینداری خرابتر نەبن",correct:!0},{text:"بۆ پاقژکرنا جادێ",correct:!1},{text:"چ گرنگی نینە",correct:!1}],explanation:"هەر لڤینەکا ترمبێلێ ل دەمێ بڕینا ئاسنی، دشێت زیانێ بگەهینیتە ستوینا پشتێ و ببیتە ئەگەرێ پەککەفتنا هەمیشەیی یا برینداری."}]},{id:18,code:"IND-1800",icon:"Factory",accent:"#4b5563",title:"سەلامەتییا پیشەسازی و کارگەهان",subtitle:"Industrial Safety & Factory Risk Management",summary:"ڕێگرتن ل ڕووداوێن پیشەسازی، ستانداردێن سەلامەتییا کاری (OSHA)، و سیستەمێ LOTO بۆ قفلکرنا وزەیێ.",blocks:[{body:"کارگەهـ و ناڤچەیێن پیشەسازی تژی مەترسییێن ئالۆزن. ل دویڤ ستانداردێن سەلامەتییا کاری (وەک OSHA ل ئەمریکا و ستانداردێ نێڤدەولەتی ISO 45001)، هەر دامەزراوەیەک دڤێت سیستەمەکێ هەلسەنگاندنا مەترسییان (Risk Assessment) هەبیت. ئەڤ مۆدیوولە فێری تە دکەت چەوا ژینگەهەکا کاری یا سەلامەت ل دویڤ بنەمایێن ئەندازیاری دابین بکەی."},{heading:"١. سیستەمێ LOTO (Lockout / Tagout)",body:"ستانداردێ سەلامەتیێ ل دەمێ چاککرنا ماشینان (OSHA 1910.147):",points:["Lockout: قفلکرنا فیزیکی یا سویچێ سەرەکی یێ کارەبایێ یان وەلڤا فشارێ.","Tagout: دانانا کارتەکا هشیاریێ ب ناڤێ وی کەسێ کار دکەت، دا کو چ کەس ماشینێ هەل نەکەت.","Zero Energy State: پشتڕاستبوون کو چ وزە (کارەبا، فشار، گەرمی یان وزەیا میکانیکی) د سیستەمی دا نەمایە بەری دەستپێکرنا کاری."]},{heading:"٢. پاراستنا ماشینان و کەرەستەیێن PPE",body:"ڕێگرتن ل بەرکەفتنا لەشی دگەل پارچەیێن لڤۆک:",points:["Machine Guarding: دانانا بەربەستێن ئاسنی ل دەوروبەرێ قایش و چەرخێن تیژ یێن ماشینان.","کەرەستەیێن پاراستنێ: بکارئینانا پێلاڤێن سەر-ئاسن (Steel-toe)، دەستکێشێن دژە-ئەسید، و پاراستنا گوهان ل وان جهێن کو دەنگ ب تێکڕایی ژ ٨٥ دیسیبێلان (dBA) د ٨ دەمژمێران دا بلندتر بیت."]}],media:[{kind:"video",src:"media/videos/gov_18_loto_training.mp4",title:"پرۆتۆکۆلا LOTO",description:"چەوانیا جێبەجێکرنا قفلکرنا وزەیێ ل کارگەهان"},{kind:"image",src:"media/images/gov_18_ppe_factory.png",title:"کەرەستەیێن PPE",description:"لیستا پێدڤییێن پاراستنێ بۆ کارمەندێن پیشەسازی"}],quiz:[{question:"مەبەست ژ «Zero Energy State» د کارێ چاککرنا ماشینان دا چییە؟",options:[{text:"بکارئینانا کارەبایەکا کێم",correct:!1},{text:"پشتڕاستبوون ژ نەمانا هەر وزەیەکا مای د ماشینێ دا، دا کو نەتەقیت و نەلڤیت",correct:!0},{text:"کارنەکرنا ماشینێ ب شەڤ",correct:!1},{text:"چ ژ ڤان",correct:!1}],explanation:"دڤێت هەمی فشار و کارەبایا هەلگرتی (د باتری و کەپاسیتەران دا) بهێتە ڤالاکرن دا کو ماشین ل دەمێ چاککرنێ ب شێوەیەکێ نەخوازیاری کار نەکەت."}]},{id:19,code:"HIGH-1900",icon:"Building",accent:"#2563eb",title:"ئاگرکوژاندن ل بالەخانێن بلند",subtitle:"High-Rise Fire Dynamics & Standpipe Operations",summary:"تایبەتمەندییێن فیزیایی یێن ئاگری ل ئاڤاهیێن بلند، سیستەمێن Standpipe، دیاردەیا Stack Effect، و ستراتیژییێن دەرکەفتنێ.",blocks:[{body:"بالەخانێن بلند (High-Rise Buildings) ئاستەنگەکا مەزنن بۆ تیمێن ئاگرکوژاندنێ، چونکی گەهشتن ب نهۆمێن سەری ب ڕێکا پەیژکێن ترمبێلان گەلەک جاران نەگونجایە. د ڤێ مۆدیوولێ دا، ئەم دێ باسێ داینامیکا هەوایێ د ئاڤاهیێن بلند دا و چەوانیا بکارئینانا سیستەمێن ناڤخۆیی یێن ئاڤێ بۆ ڤەمراندنا ئاگری ل بلندییا پتر ژ ٢٣ مەتران (٧٥ پێ) کەین."},{heading:"١. دیاردەیا Stack Effect و لڤینا دوکێلێ",body:"ل ئاڤاهیێن بلند، جیاوازییا پلەیا گەرمیێ د ناڤبەرا ناڤ و دەرڤەی ئاڤاهی دا لڤینەکا هەوایێ دروست دکەت کو دبێژنێ Stack Effect:",points:["Stack Effect: ل زستانێ، هەوایێ گەرم یێ ناڤ ئاڤاهی بەرەڤ سەری دچیت و دوکێلێ ب لەز د ناڤ پلەکان و کونێن ئەسانسۆران دا بەلاڤ دکەت.","Reverse Stack Effect: ل هاڤینێ، هەوایێ سار یێ هەواگوهۆڕینێ د کونێن ستوونی دا بەرەڤ خوارێ دچیت و دشێت دوکێلێ بەرەڤ نهۆمێن خوارێ ببەت.","دیاردەیا Mushrooming: دەمێ دوکێل دگەهیتە سەرێ ئاڤاهی یان جهەکێ گرتی، ب ئاسۆیی بەلاڤ دبیت و پاشان بەرەڤ خوارێ دزڤڕیت و نهۆمێن سەری تژی دکەت."]},{heading:"٢. ئەندازیارییا سیستەمێ Standpipe و FDC",body:"چونکی ترمبێلێن ئاگرکوژاندنێ نەشێن ب ساناهی ئاڤێ بگەهیننە نهۆمێن گەلەک بلند، پشت ب سیستەمێ بۆرییێن جێگیر (NFPA 14) دهێتە بەستن:",points:["Class I System: دەرچوونێن ئاڤێ یێن ٢.٥ ئینچی کو تەنێ تیمێن ئاگرکوژاندنێ بکار دئینن، دگەل هۆزێن خوە.","Fire Department Connection (FDC): ئەو گرێدانە یا ل دەرڤەی ئاڤاهی کو ترمبێلا ئاگرکوژاندنێ ئاڤێ تێڕا دپالدەت دا کو فشارا سیستەمی بۆ نهۆمێن بلند زێدە بکەت.","Pressure Regulating Valves: وەلڤێن ڕێکخستنا فشارێ دا کو فشارا زێدە یا ئاڤێ ل نهۆمێن خوارێ نەبیتە مەترسی بۆ ئاگرکوژان و هۆزان."]},{heading:"٣. پرۆتۆکۆلێن دەرکەفتنێ و Elevator Recall",body:"ڕێڤەبرنا خەلکی ل ئاڤاهیێن بلند پێدڤی ب پلانێن هوور هەیە بۆ پاراستنا ژیانێ:",points:["ئەسانسۆر بکار نەئینە: ل دەمێ ئاگری، ئەسانسۆر دچنە حالەتێ (Phase I Recall) و دچنە نهۆما سەرەکی و ڕادوەستن دا کو خەلک تێدا گیر نەبن؛ پاشان تەنێ ئاگرکوژ دشێن ب حالەتێ (Phase II) بکار بینن.","دەرکەفتنا قۆناغ ب قۆناغ (Phased Evacuation): پێشی دەرئێخستنا خەلکێ نهۆما ئاگری و نهۆمێن ڕاستەوخۆ ل سەر و بن وێ، پاشان نهۆمێن دی ب ڕێزبەندی.","جهێن پەنادانێ (Area of Refuge): جهێن پاراستی ل نهۆمان بۆ وان کەسێن خودان پێدڤییێن تایبەت کو نەشێن ب پلەکانان بهێنە خوارێ."]}],media:[{kind:"video",src:"media/videos/uni_19_highrise_tactics.mp4",title:"تاکتیکێن ئاڤاهیێن بلند",description:"چەوانیا ڤەمراندنا ئاگری ل نهۆمێن گەلەک بلند"},{kind:"image",src:"media/images/uni_19_standpipe_diagram.png",title:"دیاگراما Standpipe",description:"شیکارکرنا سیستەمێ بۆرییێن ئاڤێ د ناڤ ئاڤاهی دا"}],quiz:[{question:"دیاردەیا Stack Effect ل بالەخانێن بلند ب چ ئەگەری دروست دبیت؟",options:[{text:"ب ئەگەرێ تێکچوونا کارەبایێ",correct:!1},{text:"ژبەر جیاوازییا پلەیا گەرمیێ د ناڤبەرا ناڤ و دەرڤەی ئاڤاهی دا",correct:!0},{text:"ژبەر کێمییا ئاڤێ",correct:!1},{text:"تەنێ ژبەر بلندییا بالەخانێ",correct:!1}],explanation:"Stack Effect ژبەر جیاوازییا گەرمی و چڕییا هەوایێ دروست دبیت، و هەوایێ د ناڤ کونێن ستوونی (پلەکان و ئەسانسۆر) دا بەرەڤ سەری یان خوارێ دلڤینیت."}]},{id:20,code:"WILD-2000",icon:"TreePine",accent:"#ea580c",title:"ئاگرکوژاندن ل دارستان و چۆلان",subtitle:"Wildfire Dynamics & Vegetation Fire Safety",summary:"داینامیکا ئاگرێ دارستانان، کارتێکرنا کەشوهەوایێ، دیزاینا ناڤچەیا پاراستنێ (Defensible Space)، و تەکنیکێن هێلێن ڕاگرتنا ئاگری (Firebreak).",blocks:[{body:"ئاگرێن دارستان و چۆلان (Wildfires) مەترسییەکا جودانە چونکی کەشوهەوا و ئاراستەیا بای ڕاستەوخۆ کارتێکرنێ ل سەر دکەن. ل هەرێما کوردستانێ، ئاگرێن هاڤینێ هەر سال زیانێ دگەهیننە کێلگەهێن گەنمی و دارستانان. د ڤێ مۆدیوولێ دا، ئەم دێ باسێ ستراتیژییێن زانستی یێن ڕێگرتن و ڤەمراندنا ڤان ئاگران کەین."},{heading:"١. سێگۆشەیا ڕەفتارێ ئاگرێ دارستانان (Fire Behavior Triangle)",body:"ڕەفتارێ ئاگری ل دەرڤە پشت ب سێ فاکتەرێن سەرەکی دبەستیت:",points:["سۆتەمەنی (Fuel): جۆرێ دار و گیایێ هشک و ڕێژەیا شێداریێ تێدا، کو دیار دکەت ئاگر ب چ توندی بەلاڤ دبیت.","شێوەیێ عەردی (Topography): ئاگر ل سەر نشیڤان بەرەڤ سەری گەلەک بلەزتر دچیت، چونکی گەرمی و گڕ بەرەڤ سەری دچن و سۆتەمەنییا سەری پێشوەخت گەرم دکەن.","کەشوهەوا (Weather): پلەیا گەرمیێ، بایێ توند و کێمییا شێداریێ سێ فاکتەرێن سەرەکی یێن بەلاڤبوونا ئاگری نە."]},{heading:"٢. جۆرێن ئاگرێ دارستانان",body:"ئاگر ل دویڤ ئاستێ سۆتنێ دهێتە دابەشکرن:",points:["ئاگرێ ڕووی (Surface Fire): سۆتنا گیا و بەلگێن سەر عەردی، کو کۆنترۆلکرنا وی ساناهیترە.","ئاگرێ سەرێ داران (Crown Fire): مەترسیدارترین جۆرە؛ دەمێ ئاگر دگەهیتە سەرێ داران و ب هێزا بای ب لەزەکا گەلەک مەزن بەلاڤ دبیت.","پریسکێن فڕیای (Spotting): دەمێ پشکۆ و پریسکێن ئاگری ب بای دفڕن و ل جهێن دوورتر (هندەک جاران چەند کیلۆمەتر) ئاگرێن نوو دروست دکەن."]},{heading:"٣. ستراتیژییا پاراستنێ: Defensible Space",body:"بۆ پاراستنا گوند و ئاڤاهیێن نێزیکی دارستانان، ل دویڤ ڕێنماییێن CAL FIRE سێ ناڤچە دهێنە دیارکرن:",points:["Zone 0 (٠–١.٥ مەتر): ناڤچەیا بێ سۆتەمەنی؛ نابیت چ دار، گیایێ هشک یان کەلوپەلێن سۆتێنەر ل تەنیشت دیواری هەبن.","Zone 1 (١.٥–٩ مەتر): کێمکرنا چڕییا داران، پاقژکرنا بەردەوام یا بەلگێن هشک، و دوورکرنا داران ژ ئێک.","Zone 2 (٩–٣٠ مەتر): کێمکرنا سۆتەمەنیێ و لادانا چقێن خوارێ یێن داران، دا کو ئاگر ژ عەردی نەگەهیتە سەرێ داران (Ladder Fuels)."]}],media:[{kind:"video",src:"media/videos/uni_20_wildfire_behavior.mp4",title:"ڕەفتارێ ئاگری ل چیایان",description:"چەوانیا بەلاڤبوونا ئاگری ل دویڤ ئاراستەیا بای و نشیڤان"},{kind:"image",src:"media/images/uni_20_defensible_space.png",title:"نەخشەیا پاراستنێ",description:"دیارکرنا ناڤچەیێن سەلامەتیێ ل دەوروبەرێ خانییان"}],quiz:[{question:"بۆچی ئاگر ل سەر نشیڤێن چیایان بلەزتر بەلاڤ دبیت ژ عەردێ تەخت؟",options:[{text:"چونکی دار ل وێرێ پترن",correct:!1},{text:"چونکی گەرمی و گڕ بەرەڤ سەری دچن و سۆتەمەنییا سەری پێشوەخت گەرم دکەن",correct:!0},{text:"چونکی بایێ سەرێ چیای سارە",correct:!1},{text:"چ جیاوازی نینە",correct:!1}],explanation:"ل دویڤ یاسایێن فیزیایێ، گەرمی بەرەڤ سەری دچیت؛ ژبەرهندێ هندی نشیڤ (Slope) توندتر بیت، لەزا بەلاڤبوونا ئاگری بەرەڤ سەری پتر دبیت."}]},{id:21,code:"WATER-2100",icon:"LifeBuoy",accent:"#0891b2",title:"ڕزگارکرن ژ ئاڤێ و هایدرۆلۆجییا لافاوان",subtitle:"Advanced Water Rescue & Drowning Prevention",summary:"شیکارکرنا هێزا هایدرۆلیکی یا ئاڤێ، تەکنیکێن ڕزگارکرنا تەنگاڤیێ، و ڕێگرتن ل خەندقینێ.",blocks:[{body:"خەندقین (Drowning) ئێکە ژ سەرەکیترین ئەگەرێن مرنێ ل دەمێ گەشت و کارەساتان. تێگەهشتن ژ هێزا ئاڤێ و چەوانیا کارکرنا لەشی ل بن ئاڤێ (Mammalian Dive Reflex) بۆ تیمێن ڕزگارکرنێ گەلەک گرنگە. د ڤێ مۆدیوولێ دا، ئەم دێ باسێ زانستێ ڕزگارکرنێ ژ ئاڤێ و پرۆتۆکۆلێن پاراستنێ کەین. ل هەر ڕووداوەکێ ئاڤێ، پەیوەندیێ ب ١١٥ و ١٢٢ بکە."},{heading:"١. فیزیایا ئاڤا ب لەز (Swiftwater Hydrology)",body:"ئاڤا ب لەز هێزەکا گەلەک مەزن دروست دکەت کو مرۆڤ نەشێت ل هەمبەر بەرخۆ بدەت:",points:["هێزا ئاڤێ: ئەگەر لەزا ئاڤێ دوو جاران زێدە ببیت، هێزا وێ ل سەر لەشی یان ترمبێلێ چار جاران زێدە دبیت.","پالێوەر (Strainers): ئاستەنگێن وەک چقێن داران یان تۆڕان د ناڤ ئاڤێ دا کو ئاڤ تێڕا دچیت بەلێ تشتێن ڕەق (وەک مرۆڤی) دگرن، و ئەڤە دبیتە ئەگەرێ خەندقینەکا بلەز.","ئاڤا ڤەگەڕیای (Eddies): ناڤچەیێن ئارام ل پشت بەرێن مەزن کو تیمێن ڕزگارکرنێ بۆ پشوودان و نێزیکبوونێ بکار دئینن."]},{heading:"٢. ڕێسایێن زێڕین یێن ڕزگارکرنێ ژ ئاڤێ",body:"بۆ پاراستنا ژیانا ڕزگارکەری، دڤێت ئەڤ ڕێزبەندییە بهێتە پاراستن:",points:["REACH: بکارئینانا دارەکێ یان پەیژکەکێ بێ کو تو بچیە د ناڤ ئاڤێ دا.","THROW: هاڤێتنا وەریسەکێ یان تشتەکێ ل سەر ئاڤێ دمینیت (وەک تایەرەکێ).","ROW: بکارئینانا بەلەمێ بۆ نێزیکبوون ژ برینداری.","GO: دووماهی هلبژارتنە و تەنێ بۆ پسپۆرێن ڕاهێنای کو جلێن مانێ ل سەر ئاڤێ (PFD) لبەر دکەن.","HELO: بکارئینانا هەلیکۆپتەری ل لافاوێن مەزن ژ لایێ تیمێن تایبەت ڤە."]},{heading:"٣. هەوارهاتنا ئێکێ بۆ کەسێن خەندقی",body:"ئەگەر کەسەک ژ ئاڤێ هاتە دەرئێخستن، هەر چرکەیەک گرنگە:",points:["هەناسەدان: خەندقین ب بنەڕەت کێشەیەکا کێمییا ئۆکسجینێ یە؛ ئەگەر کەس بێ هش بوو و هەناسەیا ئاسایی نەبوو، CPR دەست پێ بکە و هەناسەیێن ڕزگارکرنێ (Rescue Breaths) زێدە بکە ئەگەر تو ڕاهێنای بی (ل دویڤ ERC، ب ٥ هەناسەیێن دەستپێکێ).","سەرمابوونا لەشی (Hypothermia): گەلەک جاران کەسێن ژ ئاڤێ دهێنە دەرئێخستن تووشی سەرمابوونا لەشی دبن؛ جلێن تەڕ ژێ بکە و ب هێدی گەرم بکە.","تێکچوونا درەنگ یا سییان: هەر کەسەکێ ژ ئاڤێ هاتییە دەرئێخستن و کۆخک، هەناسەتەنگی یان گێژبوون هەبیت، دڤێت ب پزیشکی بهێتە پشکنین، چونکی تێکچوونا سییان دشێت پشتی چەند دەمژمێران دیار ببیت. زاراوەیێن کەڤن وەک «Secondary/Dry Drowning» ئێدی ب شێوەیەکێ پزیشکی ناهێنە بکارئینان."]}],media:[{kind:"video",src:"media/videos/uni_21_swiftwater_rescue.mp4",title:"ڕزگارکرنا تەنگاڤیێ",description:"تەکنیکێن نێڤدەولەتی بۆ دەرئێخستنا کەسان ژ ئاڤا ب لەز"},{kind:"image",src:"media/images/uni_21_hydrology.png",title:"شیکارکرنا هێزا ئاڤێ",description:"نیشاندانا هێزا ئاڤێ ل سەر لەشێ مرۆڤی"}],quiz:[{question:"ئێکەم هەنگاڤا سەلامەت بۆ ڕزگارکرنا کەسەکێ د ناڤ ئاڤێ دا چییە؟",options:[{text:"خوە بهاڤێژە ناڤ ئاڤێ",correct:!1},{text:"REACH (گەهاندنا دارەکێ یان تشتەکی)",correct:!0},{text:"ROW (بکارئینانا بەلەمێ)",correct:!1},{text:"چاڤەڕێکرن هەتا تیم دهێن",correct:!1}],explanation:"REACH سەلامەتترین ڕێکە چونکی تو ناچیە د ناڤ ئاڤێ دا و ژیانا تە ناکەڤیتە مەترسیێ."},{question:"بۆچی دڤێت کەسێن ژ ئاڤێ ڕزگاربووی و نیشانێن وەک کۆخک یان هەناسەتەنگی هەین، بچنە نەخۆشخانێ تەنانەت ئەگەر باش دیار ببن؟",options:[{text:"بۆ پشکنینا جلوبەرگان",correct:!1},{text:"چونکی تێکچوونا سییان دشێت پشتی چەند دەمژمێران دیار ببیت",correct:!0},{text:"بۆ گوهۆڕینا ناڤێ وان",correct:!1},{text:"چ پێدڤی نینە",correct:!1}],explanation:"پشتی خەندقینێ، ئاڤا چوویە سییان دشێت هێدی هێدی تێکچوونا سییان دروست بکەت و نیشان پشتی چەند دەمژمێران دیار ببن؛ ژبەرهندێ پشکنینا پزیشکی پێدڤییە."}]},{id:22,code:"WEATHER-2200",icon:"CloudLightning",accent:"#9333ea",title:"کەشوهەوایێ توند و تەنگاڤییێن سروشتی",subtitle:"Severe Weather Emergencies & Survival",summary:"شیکارکرنا بروسکێ، بایێ توند، تەپوتۆزێ، و ڕێکارێن پاراستنا لەشی ل هەمبەر سەرما و گەرمایا توند.",blocks:[{body:"کەشوهەوایێ توند دشێت د دەمەکێ کورت دا ببیتە ئەگەرێ کارەساتێن مەزن و ژ دەستدانا ژیانێ. ل هەرێما کوردستانێ، ئەم ڕووبەڕووی بروسک، تەپوتۆزا توند، و پلەیێن گەرمیێ یێن گەلەک بلند یان نزم دبین. ناسینا نیشانێن مەترسیێ و زانینا ڕێکارێن پاراستنێ بەری ڕووداوی، کلیلا ڕزگاربوونێ یە."},{heading:"١. دیاردەیا بروسکێ (Lightning Safety)",body:"بروسک دشێت هەتا نێزیکی ٣٠٠ ملیۆن ڤۆلتان و دەهان هزار ئەمپێران هەبیت (NOAA)، ژبەرهندێ پاراستن پێدڤییە:",points:["پەناگەهـ: باشترین جه ل دەمێ بروسکێ ئاڤاهییێن داخستی یان ترمبێلێن ب سەقفێ کانزایی یێن داخستی نە.","دوورکەفتن: چ جاران ل بن دارێن بلند نەوەستە، و ژ جهێن ڤەکری و بلند و ژ ئاڤێ دوور بکەڤە.","ئەگەر تە دەنگێ گرمینێ (Thunder) بیست، تو هندە یێ نێزیکی کو بروسک دشێت ل تە بدەت: ئێکسەر بچە د ناڤ جهەکێ داخستی دا (When Thunder Roars, Go Indoors)، و ٣٠ خولەکان پشتی دووماهیک گرمینێ بمینە. یاسایا کەڤن (٣٠-٣٠) هەمان ٣٠ خولەکێن چاڤەڕێکرنێ بکار دئینا.","ئامێرێن کارەبایێ: ل مالێ، ئامێرێن هەستیار ژ کارەبایێ ڤەکە دا کو بلندبوونا ژنشکەکێ ڤە یا ڤۆلتاژی (Power Surge) زیانێ نەگەهینیتێ."]},{heading:"٢. تەپوتۆز و بایێ توند",body:"تەپوتۆز (Dust Storms) مەترسییەکا ساخلەمی و هاتنوچوونێ یا مەزنە ل ناڤچەیا مە:",points:["ئاژۆتن: ئەگەر دیتن گەلەک کێم بوو، ب تەمامی ژ جادێ دەرکەڤە و ل لایێ ڕاستێ ڕاوەستە، ڕووناهییێن ترمبێلێ ڤەمرینە و فرێنا دەستی بکێشە، دا کو ترمبێلێن دی ل دویڤ ڕووناهییێن تە نەهێن و ل تە نەدەن.","پاراستنا هەناسێ: بکارئینانا ماسکێن N95 یان پەڕۆیەکێ تەڕ بۆ کێمکرنا چوونا تەنۆلکێن هوور بۆ ناڤ سییان.","بایێ توند: ل دەمێ بایێ توند، ژ پەنجەرەیێن شووشەیی دوور بکەڤە و د ژوورێن ناڤخۆیی یێن ئاڤاهی دا بمینە."]},{heading:"٣. تەنگاڤییێن پلەیا گەرمیێ (Heat & Cold Stress)",body:"تێگەهشتن ژ حالەتێن Hypothermia و Heat Stroke بۆ هەر هەوارهاتییەکێ پێدڤییە:",points:["گەرمابوونا مەترسیدار (Heat Stroke): دەمێ پلەیا لەشی ژ ٤٠ پلەیێن سیلیزی بۆراتر دبیت و گوهۆڕینێن هشی (گێژبوون، تێکچوون) پەیدا دبن. پێست دشێت هشک و سۆر و گەرم بیت، بەلێ ل گەرمابوونا ژ کار و وەرزشێ دشێت ئارەق هەبیت. ئەڤە حالەتەکێ کوژەکە: پەیوەندیێ ب ١٢٢ بکە و ئێکسەر لەشی ب ئاڤا سار سار بکە.","سەرمابوونا لەشی (Hypothermia): دەمێ پلەیا ناڤخۆیی یا لەشی دکەڤیتە بن ٣٥ پلەیان. نیشان: لەرزینا توند، ئاخفتنا گران، و هێدیبوونا لێدانا دلی.","قەرسین (Frostbite): ڕەقبوونا شانەیێن لەشی (تبل، گوهـ، دفن) ژبەر سەرمایا گەلەک توند؛ چ جاران جهێ قەرسی نەفرکینە و ب ئاڤا گەلەک گەرم گەرم نەکە."]}],media:[{kind:"video",src:"media/videos/uni_22_weather_survival.mp4",title:"ڕێکارێن پاراستنێ",description:"چەوانیا مامەلەکرنێ دگەل بروسک و بایێ توند"},{kind:"image",src:"media/images/uni_22_heat_stroke.png",title:"نیشانێن گەرمابوونێ",description:"جیاوازییا د ناڤبەرا ماندیبوونا گەرمیێ و حالەتێ کوژەک یێ Heat Stroke دا"}],quiz:[{question:"یاسایا ٣٠-٣٠ ل دەمێ بروسکێ ئاماژەیە بۆ چ؟",options:[{text:"پلەیا گەرمیێ",correct:!1},{text:"دیارکرنا مەودایێ مەترسیێ و دەمێ چاڤەڕێکرنێ پشتی بروسکێ",correct:!0},{text:"لەزا بای",correct:!1},{text:"بڕا بارانێ",correct:!1}],explanation:"یاسایا کەڤن دبێژیت: ئەگەر دەم د ناڤبەرا بروسک و دەنگێ وێ دا کێمتر ژ ٣٠ چرکەیان بیت، دڤێت بچیە جهەکێ داخستی و ٣٠ خولەکان پشتی دووماهیک گرمینێ بمینی. ڕێنماییا نوو یا NOAA ساناهیترە: ئەگەر تە گرمین بیست، ئێکسەر بچە ژوورێ."},{question:"کیش ژ ڤان نیشانا گەرمابوونا مەترسیدار (Heat Stroke) یە؟",options:[{text:"ئارەقکرنا گەلەک تەنێ",correct:!1},{text:"بلندبوونا پلەیا لەشی بۆ سەر ٤٠ پلەیان دگەل گێژبوونێ، و پێستێ هشک و سۆر",correct:!0},{text:"لەرزینا لەشی",correct:!1},{text:"پژمین",correct:!1}],explanation:"ل دەمێ Heat Stroke، لەش کۆنترۆلا سارکرنا خوە ژ دەست ددەت و پلەیا وی ژ ٤٠ بلندتر دبیت، و ئەڤە زیانێ دگەهینیتە مێشکی. سارکرنا ئێکسەر و پەیوەندیکرن ب ١٢٢ پێدڤییە."}]},{id:23,code:"SUPP-2300",icon:"BellRing",accent:"#dc2626",title:"سیستەمێن ئاگەهدارکرن و ئاگرکوژاندنێ",subtitle:"Fire Detection & Automatic Suppression Engineering",summary:"شیکارکرنا تەکنیکی یا هەستەڤەرێن ئاگری، سیستەمێن Sprinkler، و تەکنۆلۆژیایا ڤەمراندنێ ب غازێن پاقژ.",blocks:[{body:"سیستەمێن ئۆتۆماتیکی یێن پاراستنێ هێلا ئێکێ یا بەرگریێ نە ل ئاڤاهیێن نوو. ئەڤ سیستەمە دهێنە دیزاینکرن دا کو ئاگری د قۆناغا دەستپێکێ (Incipient Stage) دا ببینن و بێ دەستێوەردانا مرۆڤی کۆنترۆل بکەن. ئەڤ مۆدیوولە بنەمایێن ئەندازیاری ل دویڤ ستانداردێن NFPA 13 (Sprinkler) و NFPA 72 (ئاگەهدارکرن) ڕوون دکەت."},{heading:"١. سیستەمێن هەستەڤەر و ئاگەهدارکرنێ (Detection)",body:"هەستەڤەر (Detectors) چاڤێن ئاڤاهی نە و ب چەند شێوازان کار دکەن:",points:["Photoelectric Smoke Detector: پشت ب تیشکا ڕووناهیێ دبەستیت؛ بۆ دیتنا ئاگرێن هێدی و دوکێلدار باشترین جۆرە.","Ionization Detector: بۆ تەنۆلکێن گەلەک بچووک یێن ئاگرێن بلەز و گڕدار هەستیارترە.","Heat Detectors: ل وان جهان بکار دهێن یێن کو دوکێل یان هەلم ب شێوەیەکێ ئاسایی لێ هەی (وەک مەتبەخ و کارگەهـ)، و ب بلندبوونا گەرمیێ کار دکەن.","Notification Appliances: بکارئینانا زەنگ و ڕووناهییێن فلاشێ بۆ ئاگەهدارکرنا هەمی ئاڤاهی."]},{heading:"٢. ئەندازیارییا سیستەمێ Sprinkler",body:"ئەڤ سیستەمە فشارا ئاڤێ بکار دئینیت بۆ کۆنترۆلکرنا ئاگری ل جهێ ڕوودانێ:",points:["بلبا شووشەیی (Bulb): پترییا سەرێن Sprinkler بلبەکا شووشەیی یا تژی شلەمەنی هەیە کو ل پلەیەکا گەرمیێ یا دیارکری دشکێت و دهێلیت ئاڤ بپژیت.","جۆرێن سیستەمی: Wet Pipe کو باوترینە و بۆری تژی ئاڤن، و Dry Pipe بۆ وان جهێن مەترسییا قەرسینا ئاڤێ لێ هەی.","ڕاستییەکا زانستی: تەنێ ئەو سەرێن دکەڤنە بن گەرمییا ئاگری ڤەدبن، نە هەمی سەرێن ئاڤاهی پێکڤە (وەک د فلمان دا دهێتە نیشاندان)."]},{heading:"٣. ڤەمراندن ب غازێن پاقژ (Clean Agent Systems)",body:"ل وان جهان یێن کو ئاڤ زیانێ دگەهینیتە کەرەستەیان (وەک ژوورێن سێرڤەران و مۆزەخانە)، غاز دهێتە بکارئینان (NFPA 2001):",points:["FM-200 و FK-5-1-12 (Novec 1230): ئەڤ غازە ب شێوەیەکێ سەرەکی گەرمیێ ڤەدکێشن و هەتا ڕادەیەکێ کارلێکا زنجیرەیی ژی دشکێنن، و چ پاشماوە ل دویڤ خوە ناهێلن.","CO₂ Systems: گەلەک کاریگەرن بەلێ مەترسییا خەندقینێ بۆ مرۆڤی هەیە، ژبەرهندێ ب گشتی تەنێ ل جهێن بێ مرۆڤ، دگەل ئاگەهدارکرنا بەری بەردانێ و قفلکرنا سیستەمی (NFPA 12) دهێنە بکارئینان.","Saponification: ڕێکا ڤەمراندنا ئاگرێ مەتبەخان (Class K ل NFPA، Class F ل EN 2) ب گوهۆڕینا ڕۆنێ سۆتی بۆ ماددەیەکێ وەک سابوونێ."]}],media:[{kind:"video",src:"media/videos/uni_23_sprinkler_physics.mp4",title:"فیزیایا Sprinkler",description:"شیکارکرنا کارکرنا ئۆتۆماتیکی یا سیستەمێ ئاڤێ"},{kind:"image",src:"media/images/uni_23_detector_types.png",title:"جۆرێن هەستەڤەران",description:"بەراوردکرنا کارکرنا هەستەڤەرێن دوکێل و گەرمیێ"}],quiz:[{question:"کیش جۆرێ هەستەڤەرێن دوکێلێ (Smoke Detector) بۆ ناسینا ئاگرێن هێدی و دوکێلدار باشترە؟",options:[{text:"Ionization Detector",correct:!1},{text:"Photoelectric Detector",correct:!0},{text:"Heat Detector",correct:!1},{text:"Flame Detector",correct:!1}],explanation:"هەستەڤەرێن Photoelectric ب ڕێکا تیشکا ڕووناهیێ گەلەک ب لەز هەست ب دوکێلا ستوور دکەن، کو تایبەتمەندییا ئاگرێن هێدی یە."},{question:"ل سیستەمێ Sprinkler یێ ستاندارد، ئەرێ هەمی سەرێن ئاڤێ پێکڤە ڤەدبن؟",options:[{text:"بەلێ، هەمی پێکڤە کار دکەن",correct:!1},{text:"نەخێر، تەنێ ئەو سەرێ گەرمی تێدا دگەهیتە پلەیا شکاندنا بلبا وی ڤەدبیت",correct:!0},{text:"تەنێ ئەگەر تیمێن ئاگرکوژاندنێ فەرمانێ بدەن",correct:!1},{text:"تەنێ ب شەڤ",correct:!1}],explanation:"سیستەمێ ستاندارد ب شێوەیەکێ جهی کار دکەت؛ هەر سەرەک ب سەربەخۆیی کار دکەت دا کو زیانێن ئاڤێ ل جهێن دی کێم ببن."}]},{id:24,code:"EVAC-2400",icon:"Tent",accent:"#0d9488",title:"دەرئێخستنا ب کۆم و ڕێڤەبرنا پەناگەهان",subtitle:"Mass Evacuation Strategy & Shelter Operations",summary:"ستراتیژییێن دەرئێخستنا ب کۆم ل کارەساتێن مەزن، ڕێکخستنا کەمپێن هاریکاریێ، و پەیڕەوکرنا ستانداردێن نێڤدەولەتی یێن پەناگەهان (Sphere).",blocks:[{body:"ل دەمێ کارەساتێن مەزن وەک عەردەهەژینێن وێرانکەر یان لافاوێن بەرفرەهـ، دەرئێخستنا هزاران کەسان بۆ جهێن سەلامەت پێدڤی ب پلانەکا لۆجیستیکی یا ئالۆز هەیە. ڕێڤەبرنا پەناگەهان نە تەنێ دابینکرنا جهی یە، بەلکو دابینکرنا ساخلەمی، ئاسایش و کەرامەتا مرۆڤی یە ل دویڤ ستانداردێن نێڤدەولەتی (وەک Sphere Handbook). ئەڤ مۆدیوولە بنەمایێن ڕێکخستنا خەلکی و پەناگەهان ڕوون دکەت."},{heading:"١. پلاندانانا ستراتیژی یا دەرئێخستنێ",body:"پرۆسەیا دەرئێخستنا خەلکی دڤێت ل دویڤ قۆناغێن ڕێکخستی بیت دا کو تێکچوون دروست نەبیت:",points:["دیارکرنا ڕێڕەوێن دەرئێخستنێ: نەخشەکێشانا ڕێکێن سەرەکی و یەدەک، و دیارکرنا وان ڕێکان یێن کو تەنێ بۆ ترمبێلێن تەنگاڤیێ هاتینە تەرخانکرن.","ڕێڤەبرنا هاتنوچوونێ: هەماهەنگی دگەل پۆلیسا هاتنوچوونێ (١٠٤) بۆ ڕێگرتن ل قەرەبالغی و گرتنا ڕێکێن دەرکەفتنێ.","سیستەمێ ئاگەهدارکرنا گشتی: بکارئینانا بلندگۆیان، SMS، ڕادیۆ و تەلەفزیۆنێن ناڤخۆیی بۆ ئاگەهدارکرنا خەلکی ب دەمێ دەستپێکرنا دەرئێخستنێ."]},{heading:"٢. ڕێڤەبرنا پەناگەهـ و کەمپێن تەنگاڤیێ",body:"ل دویڤ ستانداردێن نێڤدەولەتی (Sphere)، هەر پەناگەهەک دڤێت ڤان مەرجان جێبەجێ بکەت:",points:["پۆلێنکرنا جهی: جوداکرن د ناڤبەرا پەناگەهێن کورتخایەن (وەک قوتابخانە و هۆلێن وەرزشی) و کەمپێن درێژخایەن (وەک کەمپێن چادران) دا.","تۆمارکرن و داتابەیس: نڤیسینا لیستا ناڤێن هەمی ئاوارەیان، و تۆمارکرنا مالباتان و کەسێن تنێ (ب تایبەتی زارۆکێن بێ سەرپەرشت) ب جودا بۆ پاراستنا ئاسایشێ.","ساخلەمی و پاقژی: دابینکرنا لایێ کێم ١٥ لیتر ئاڤ بۆ هەر کەسەکی د ڕۆژێ دا (بۆ ڤەخوارن، خوارنچێکرن و پاقژیا کەسی)، و ئێک توالێت بۆ هەر ٢٠ کەسان (ل دەستپێکا تەنگاڤیێ، ئێک بۆ ٥٠ کەسان وەک کێمترین ئاست)."]},{heading:"٣. چاڤدێرییا کۆمێن هەستیار (Vulnerable Groups)",body:"ل دەمێ کارەساتان، هندەک کۆم پێدڤی ب پاراستنەکا تایبەت هەیە:",points:["پیر و کەسێن خودان پێدڤییێن تایبەت: دابینکرنا ڕێڕەوێن گونجای بۆ کورسییێن چەرخدار و دابینکرنا دەرمانێن نەخۆشییێن درێژخایەن.","زارۆک: دروستکرنا جهێن تایبەت یێن پاراستی (Child-Friendly Spaces) دا کو ژ برینێن دەروونی و مەترسییان دوور بن.","ژنێن دووگیان: دابینکرنا تیمێن پزیشکی یێن تایبەت ل پەناگەهی بۆ حالەتێن زایینێ یێن ژنشکەکێ ڤە."]}],media:[{kind:"video",src:"media/videos/uni_24_shelter_org.mp4",title:"ڕێکخستنا کەمپان",description:"چەوانیا دابەشکرنا چادر و خزمەتگوزارییان ل دویڤ ستانداردێن نێڤدەولەتی"},{kind:"image",src:"media/images/uni_24_evac_map.png",title:"نەخشەیا دەرئێخستنێ",description:"نموونەیا پلانا دەرئێخستنا باژێرەکی ل دەمێ لافاوێ"}],quiz:[{question:"ل دویڤ ستانداردێن مرۆڤانە (Sphere)، هەر کەسەک ل پەناگەهی لایێ کێم پێدڤی ب چەند لیتر ئاڤێ هەیە د ڕۆژێ دا؟",options:[{text:"٢ لیتر",correct:!1},{text:"٥ لیتر",correct:!1},{text:"١٥ لیتر",correct:!0},{text:"٥٠ لیتر",correct:!1}],explanation:"ستانداردێ Sphere دیار دکەت کو لایێ کێم ١٥ لیتر بۆ ڤەخوارن، پاقژی و خوارنچێکرنێ پێدڤییە."},{question:"ئارمانجا سەرەکی ژ (Child-Friendly Spaces) ل کەمپان چییە؟",options:[{text:"بۆ نڤستنا زارۆکان",correct:!1},{text:"بۆ پاراستنا زارۆکان ژ برینێن دەروونی و دابینکرنا جهەکێ یاریێ یێ پاراستی",correct:!0},{text:"بۆ کۆمکرنا خوارنێ",correct:!1},{text:"بۆ فێربوونا زمانان",correct:!1}],explanation:"ئەڤ جهە دهێنە دانان دا کو زارۆک د ژینگەهەکا ئارام دا بن و پشتی کارەساتێ تووشی توندوتیژی یان کێشەیێن دەروونی نەبن."}]},{id:25,code:"TECH-2500",icon:"Mountain",accent:"#475569",title:"ڕزگارکرنا تەکنیکی و مەیدانی",subtitle:"Technical Rescue: Rope, Confined Space & Structural Collapse",summary:"ڕزگارکرن ب وەریسان، ڕزگارکرن ل جهێن تەنگ و بلند، و ئەندازیارییا جێگیرکرنا ئاڤاهیێن هەرفتی.",blocks:[{body:"ڕزگارکرنا تەکنیکی (Technical Rescue) ئاستەکێ پێشکەفتی یێ کارێ بەرگرییا شارستانی یە کو تێدا تیمێن تایبەت ب بکارئینانا ئامێرێن ئەندازیاری و سیستەمێن میکانیکی برینداران ڕزگار دکەن. ئەڤ کارە پێدڤی ب پلاندانانەکا هوور و زانینا فیزیایێ هەیە دا کو نەبیتە ئەگەرێ زیانێن زێدەتر بۆ بریندار یان تیمی."},{heading:"١. ڕزگارکرن ب وەریسان (Rope Rescue)",body:"بکارئینانا سیستەمێن وەریسان ل دویڤ ستانداردێ NFPA 2500 (کو جهێ NFPA 1670، NFPA 1858 و NFPA 1983 یێن بەری نوکە گرتییە):",points:["دوو سیستەم: بکارئینانا هێلا سەرەکی (Main Line) و هێلا پاراستنێ (Belay Line)؛ هەردەم دڤێت دوو سیستەم هەبن دا کو ئەگەر ئێک پچڕا، یا دی بریندار و ڕزگارکەری بپارێزیت.","مفایێ میکانیکی (Mechanical Advantage): بکارئینانا سیستەمێن ٣:١ یان ٥:١ ب ڕێکا قەرقەران (Pulleys) بۆ بلندکرنا بریندار یان بارێن گران ب کێمترین هێزا ماسولکەیان.","گرێکێن سەرەکی: بکارئینانا گرێکێن وەک Figure 8 on a bight و Double Fisherman's کو ل بن بارێ گران ناخلیسکن."]},{heading:"٢. ڕزگارکرن ل جهێن تەنگ (Confined Space Rescue)",body:"جهێن وەک تانکێن سۆتەمەنیێ، بۆرییێن ئاڤا پیس و کونێن ژێرعەردی مەترسییێن بێ دەنگن (OSHA 1910.146):",points:["پشکنینا هەوایێ: بەری چوونە ژوور، دڤێت ئاستێ ئۆکسجینێ (لایێ کێم ١٩.٥٪)، غازێن سۆتێنەر (کێمتر ژ ١٠٪ ژ LEL)، و غازێن ژەهراوی وەک H₂S و CO بهێنە پشکنین.","ڕۆلێن تیمێ: تیم دبیتە سێ بەش: Entrant (ئەوێ دچیتە ژوور)، Attendant (ئەوێ ژ دەرڤە چاڤدێریێ دکەت و چ جاران ناچیتە ژوور)، و Supervisor (فەرماندە).","هەواگوهۆڕینا ب پانکەیان (Forced Ventilation): بکارئینانا پانکەیێن هەوایێ بۆ دەرئێخستنا غازێن ژەهراوی و ئینانا هەوایێ پاقژ بەری چوونا تیمێ و ل دەمێ کاری."]},{heading:"٣. ڕزگارکرن ل هەرفتنا ئاڤاهییان (Structural Collapse)",body:"جێگیرکرنا ئاڤاهیێن هەرفتی دا کو تیم بشێن ب سەلامەتی بچنە د ناڤ بۆشاییان دا:",points:["Shoring (پالپشتکرن): بکارئینانا دار و ستوینێن ئاسنی بۆ ڕاگرتنا سەقف و دیوارێن ل بەر هەرفتنێ.","ئامێرێن لێگەڕیانێ: بکارئینانا ئامێرێن گوهدارکرنێ یێن دەنگی و لەرزینی بۆ گوهلێبوونا لێدان و دەنگێن برینداران، و ئامێرێن ڕاداری بۆ دیتنا هەناسە و لڤینێن وان ل بن کاڤلان.","تیمێن K9: بکارئینانا سەیێن ڕاهێنای بۆ دیتنا بێهنا مرۆڤێن زیندی د ناڤ کاڤلێن مەزن دا."]}],media:[{kind:"video",src:"media/videos/uni_25_rope_systems.mp4",title:"سیستەمێن وەریسان",description:"شیکارکرنا سیستەمێ ٣:١ بۆ بلندکرنا برینداران ل چیایان"},{kind:"video",src:"media/videos/uni_25_confined_entry.mp4",title:"چوونە ناڤ جهێن تەنگ",description:"ڕێکارێن سەلامەتیێ و بکارئینانا ئامێرێن پشکنینا هەوایێ"},{kind:"image",src:"media/images/uni_25_shoring_types.png",title:"جۆرێن Shoring",description:"نیشاندانا شێوازێن ئەندازیاری بۆ ڕاگرتنا دیوارێن ل بەر هەرفتنێ"}],quiz:[{question:"بۆچی د ڕزگارکرنا ب وەریسان دا هەردەم پێدڤی ب دوو سیستەمان (Main و Belay) هەیە؟",options:[{text:"بۆ لەزا پتر",correct:!1},{text:"دا کو ئەگەر وەریسەک یان سیستەمەک تێک چوو، یا دی ژیانا بریندار و تیمێ بپارێزیت",correct:!0},{text:"بۆ هندێ کەرەستە زێدە بن",correct:!1},{text:"تەنێ بۆ دیمەنەکێ جوان",correct:!1}],explanation:"ل دویڤ ستانداردێن نێڤدەولەتی، سیستەمێ Belay (یەدەک) مەرجەکێ سەرەکی یێ سەلامەتیێ یە ل بلندییان."},{question:"کێمترین ڕێژەیا ئۆکسجینێ کو چوونە ناڤ جهەکێ تەنگ بێ ئامێرێ هەناسێ ڕێپێدای بیت، چەندە؟",options:[{text:"١٠٪",correct:!1},{text:"١٦٪",correct:!1},{text:"١٩.٥٪",correct:!0},{text:"٢١٪",correct:!1}],explanation:"ئەگەر ئۆکسجین ژ ١٩.٥٪ کێمتر بیت، کەشەکێ کێم-ئۆکسجین (Oxygen-Deficient) هەیە و تیم نابیت بێ ئامێرێ هەناسێ یێ سەربەخۆ (SCBA) بچیتە ژوور."}]},{id:26,code:"COMM-2550",icon:"Radio",accent:"#2563eb",title:"پەیوەندییێن تەنگاڤیێ و سیستەمێن هنارتنا تیمان",subtitle:"Emergency Communications & Radio Dispatch Systems",summary:"سیستەمێن پەیوەندییا ڕادیۆیی، پرۆتۆکۆلا وەرگرتن و هنارتنا بانگان (Dispatch)، هەماهەنگییا ناڤبەرا دەزگەهان (Interoperability)، و بکارئینانا زمانێ ڕوون (Plain Language).",blocks:[{body:"پەیوەندییا کاریگەر ستوینا سەرەکی یا هەر ڕێڤەبرنەکا کارەساتان یە. د ڤێ مۆدیوولێ دا، ئەم دێ باسێ سیستەمێن ڕادیۆیی یێن دیجیتال و ئەنالۆگ، پرۆتۆکۆلا Dispatch، و چەوانیا هەماهەنگیێ د ناڤبەرا دەزگەهێن جودا (پۆلیس، ئاگرکوژاندن، ئەمبوولانس) دا کەین. تێگەهشتن ژ ڤان سیستەمان بۆ هەر ئەفسەرەکێ بەرگرییا شارستانی پێدڤییە."},{heading:"١. سیستەمێن ڕادیۆیی (Radio Systems)",body:"جۆرێن سیستەمێن پەیوەندییا بێتەل:",points:["VHF/UHF: فریکوێنسییێن باو بۆ پەیوەندییا ناڤخۆیی؛ ب گشتی VHF بۆ ناڤچەیێن ڤەکری و UHF بۆ ناڤ ئاڤاهییان باشترە.","Trunked Radio: سیستەمەکێ (ئەڤرۆ ب گشتی دیجیتال) کو چەندین فریکوێنسییان ب شێوەیەکێ ئۆتۆماتیکی د ناڤبەرا کۆمێن جودا دا دابەش دکەت، وەک سیستەمێن P25 ل ئەمریکا.","پەیوەندییا سەتەلایتی (Satellite Communications): بۆ ناڤچەیێن دوور یان دەمێ بڕینا تۆرێن عەردی.","LTE/FirstNet: تۆرەکا تایبەت یا تیمێن تەنگاڤیێ ل ئەمریکا کو ئەولەوییەت و کوالیتییەکا بلند ددەتە پەیوەندییان."]},{heading:"٢. پرۆتۆکۆلا وەرگرتن و هنارتنا بانگان (Dispatch Protocol)",body:"ڕێکارێن ستاندارد بۆ وەرگرتنا بانگێن تەنگاڤیێ و هنارتنا تیمان:",points:["وەرگرتنا بانگی: بکارئینانا سیستەمێ CAD (Computer Aided Dispatch) بۆ تۆمارکرنا پێزانینان ب لەز.","پۆلێنکرنا ئەولەوییەتێ: دیارکرنا ئاستێ مەترسیێ (Priority 1, 2, 3) ل دویڤ جۆرێ ڕووداوی و ناڤەڕۆکا بانگی.","پرۆتۆکۆلا EMD (Emergency Medical Dispatch): دانا ڕێنماییان ب تەلەفۆنێ بۆ بانگکەری (بۆ نموونە ڕێنماییێن CPR) هەتا گەهشتنا ئەمبوولانسێ.","دەمێ بەرسڤدانێ: ل دویڤ NFPA 1225 (بەری نوکە NFPA 1221)، ٩٠٪ ژ بانگێن تەنگاڤیێ دڤێت د ناڤ ١٥ چرکەیان دا و ٩٥٪ د ناڤ ٢٠ چرکەیان دا بهێنە بەرسڤدان؛ دەمێ گەهشتنا تیمان ل دویڤ ئارمانجێن ناڤخۆیی یێن ڕێڤەبەرییێ دهێتە پێڤان."]},{heading:"٣. زمانێ ڕوون و زاراوەیێن ستاندارد یێن ڕادیۆیێ",body:"ل دویڤ NIMS/ICS، پەیوەندییێن ڕادیۆیی ب زمانەکێ سادە و ڕوون دهێنە کرن، نە ب کۆدان، دا کو هەمی دەزگەهـ ژ ئێکدو تێبگەهن:",points:["کۆدێن دەهـ (Ten-codes): وەک 10-4 و 10-20، سیستەمەکێ کەڤن (Legacy) یە و واتایا وان ژ دەزگەهەکێ بۆ یێ دی جودایە؛ ژبەرهندێ ل ڕووداوێن هەڤپشک ناهێنە بکارئینان. ل جهێ «10-4» بێژە «تێگەهشتم»، و ل جهێ «10-20» جهێ خوە ب ناڤ و نیشان بێژە.","ئەلفوبێیا دەنگی (Phonetic Alphabet): بکارئینانا Alfa، Bravo، Charlie... بۆ ڕوونکرنا پیتان ل سەر ڕادیۆیێ.","Mayday: پەیڤا نێڤدەولەتی یا هاوارخوازیێ یە (سێ جاران دهێتە گۆتن) دەمێ ئاگرکوژەک د مەترسییەکا کوژەک دا بیت؛ هەمی کەس دڤێت کەنالێ بۆ وی ڤالا بکەن.","PAR (Personnel Accountability Report): پشکنینا هەبوونا هەمی ئەندامێن تیمێ ل جهێ کاری."]},{heading:"٤. هەماهەنگییا ناڤبەرا دەزگەهان (Interoperability)",body:"چەوانیا پەیوەندیکرنێ د ناڤبەرا دەزگەهێن جودا دا:",points:["کەنالێن هەڤپشک: دیارکرنا فریکوێنسییێن تایبەت بۆ پەیوەندییا د ناڤبەرا پۆلیس، ئاگرکوژاندن و ئەمبوولانسێ دا.","ئامێرێن گرێدانێ (Gateway Devices): ئامێرێن کو سیستەمێن جودا پێکڤە گرێ ددەن (وەک VHF دگەل UHF).","پەیوەندی د ICS دا: سەرۆکێ یەکەیا پەیوەندییان (Communications Unit Leader) بەرپرسە ژ ڕێکخستنا پلانا پەیوەندییان.","NIMS Typing: پۆلێنکرنا کەرەستەیێن پەیوەندیێ ل دویڤ ستانداردێن نیشتمانی (Type I, II, III)."]},{heading:"٥. ناڤەندێن فەرماندەییێ (Command Centers)",body:"دانانا جهێن ناڤەندی بۆ کۆنترۆلکرنا پەیوەندییان:",points:["EOC (Emergency Operations Center): ناڤەندا سەرەکی یا ڕێڤەبرنا کارەساتان ل ئاستێ باژێر یان پارێزگەهێ.","Mobile Command: ترمبێلەکا تایبەت کو وەک ناڤەندا فەرماندەییا مەیدانی کار دکەت.","Status Boards: تەختەیێن نیشاندانێ بۆ زانینا جهێ تیمان و دۆخا ڕووداوی.","Redundancy: هەبوونا سیستەمێن یەدەک ل دەمێ تێکچوونا سیستەمێ سەرەکی."]}],media:[{kind:"video",src:"media/videos/uni_26_radio_ops.mp4",title:"کارکرن ب ڕادیۆیێ",description:"بنەمایێن پەیوەندییا ڕادیۆیی و ئەلفوبێیا دەنگی"},{kind:"image",src:"media/images/uni_26_dispatch_center.png",title:"ناڤەندا وەرگرتنا بانگان",description:"ڕێکخستنا ژوورا CAD و ئامێران"}],quiz:[{question:"پەیڤا (Mayday) ل سەر ڕادیۆیێ نیشانا چییە؟",options:[{text:"دەستپێکرنا کاری",correct:!1},{text:"هاوارخوازییا ئاگرکوژەکی ل دەمێ مەترسییەکا کوژەک",correct:!0},{text:"ب دووماهی هاتنا کاری",correct:!1},{text:"پشکنینا ڕادیۆیێ",correct:!1}],explanation:"Mayday پەیڤا نێڤدەولەتی یا هاوارخوازیێ یە دەمێ ژیانا ئاگرکوژەکی د مەترسییەکا گران دا بیت و پێدڤی ب هاریکارییا بلەز هەبیت."},{question:"جیاوازییا سەرەکی د ناڤبەرا VHF و UHF دا چییە؟",options:[{text:"VHF باشترە بۆ ناڤ ئاڤاهییان",correct:!1},{text:"UHF باشترە بۆ ناڤچەیێن ڤەکری",correct:!1},{text:"VHF باشترە بۆ ناڤچەیێن ڤەکری و UHF باشترە بۆ ناڤ ئاڤاهییان",correct:!0},{text:"چ جیاوازی نینە",correct:!1}],explanation:"شەپۆلێن VHF درێژترن و ل ناڤچەیێن ڤەکری باشتر دگەهن، بەلێ UHF ب ساناهیتر د ناڤ ئاڤاهییان دا دچیت."}]},{id:27,code:"CBRN-2600",icon:"Radiation",accent:"#ca8a04",title:"بەرگری دژی ماددەیێن کوژەک (CBRN)",subtitle:"Chemical, Biological, Radiological & Nuclear Defense",summary:"ستراتیژییێن پاراستنێ دژی مەترسییێن کیمیایی، بایۆلۆژی، تیشکدەر و ئەتۆمی، ئاستێن PPE، و ڕێکارێن پاقژکرنێ (Decontamination).",blocks:[{body:"زاراوەیێ CBRN ئاماژەیە بۆ چار جۆرێن مەترسییێن کوژەک: کیمیایی، بایۆلۆژی، تیشکدەر (Radiological) و ئەتۆمی (Nuclear). ئەڤ مۆدیوولە بۆ ئەفسەر و ئەندازیاران هاتییە ئامادەکرن دا کو بزانن چەوا ڕووبەڕووی حالەتێن نەئاسایی ببن. ل ڤێرە ئەم دێ باسێ فیزیایا تیشکدانێ، کیمیایا ماددەیێن دەماری، و پرۆتۆکۆلێن پاقژکرنا ب کۆم ل دویڤ ستانداردێن نێڤدەولەتی کەین."},{heading:"١. مەترسییێن کیمیایی (Chemical Agents)",body:"ماددەیێن کیمیایی ل دویڤ کارتێکرنا وان ل سەر لەشی دهێنە دابەشکرن:",points:["ماددەیێن دەماری (Nerve Agents): وەک Sarin و VX؛ سیستەمێ دەماران پەک دئێخن. نیشانێن وان ب SLUDGEM دهێنە ناسین (بچووکبوونا بیبیکا چاڤی، فرمێسک، میزکرن، زکچوون، و گرژبوونا ماسولکەیان).","ماددەیێن خەندقێنەر (Choking Agents): وەک کلۆر و فۆسجین؛ زیانا گران دگەهیننە سییان.","ماددەیێن بلقکەر (Blister Agents): وەک غازا خەردەلی؛ دبنە ئەگەرێ سۆتنەکا کیمیایی یا توند ل سەر پێست، چاڤ و سییان.","ماددەیێن خوینێ (Blood Agents): وەک سیانید؛ ڕێگرییێ ل خانەیان دکەن کو ئۆکسجینێ بکار بینن."]},{heading:"٢. مەترسییێن بایۆلۆژی و میکرۆبی (Biological Threats)",body:"بکارئینانا بەکتریا، ڤایرۆس و ژەهرێن زیندی وەک چەک:",points:["بەکتریا: وەک ئانسراکس (Anthrax) و تاعوون (Plague)؛ سپۆرێن ئانسراکسێ دشێن بۆ ماوەیەکێ گەلەک درێژ د ژینگەهێ دا بمینن.","ڤایرۆس: وەک ئیبۆلا و ڤایرۆسێ Smallpox؛ کو دشێن د ناڤبەرا مرۆڤان دا بەلاڤ ببن.","ژەهرێن زیندی (Toxins): وەک ڕیسین (Ricin) کو ژ تۆڤێن ڕووەکێ Castor دهێتە بەرهەمئینان و ژەهرەکا گەلەک کوژەکە.","ڕێکار: بکارئینانا فلتەرێن HEPA و ژوورێن فشارا نێگەتیڤ بۆ جوداکرنا تووشبوویان."]},{heading:"٣. فیزیایا تیشکدانێ و پاراستنا ئەتۆمی",body:"تێگەهشتن ژ سێ بنەمایێن پاراستنێ: دەم، مەودا، و پارێزەر:",points:["جۆرێن تیشکێ: Alpha ب پەڕەکا کاغەزێ ڕادوەستیت، Beta پێدڤی ب پلاستیک یان ئەلەمنیۆمێ هەیە، بەلێ Gamma تەنێ ب ماددەیێن چڕ و ستوور وەک سرب (Lead)، کۆنکریت یان ئاخێ کێم دبیت.","بۆمبا پیس (Dirty Bomb): تەقەمەنییەکا ئاسایی یە کو ماددەیێن تیشکدەر تێدا هەنە بۆ پیسکرنا ناڤچەیەکێ، نە تەقینەکا ئەتۆمی یە.","بنەمایێ TDS: کێمکرنا دەمێ مانێ نێزیکی سەرچاڤەیێ (Time)، زێدەکرنا مەودای (Distance)، و بکارئینانا پارێزەری (Shielding)."]},{heading:"٤. ئاستێن جلوبەرگێن پاراستنێ (PPE Levels)",body:"بەرگرییا شارستانی دڤێت بزانیت کیش جل ل کیش دەمی بکار بینیت:",points:["Level A: بلندترین پاراستن؛ جلەکێ تەمام داخستی (Gas-tight) دگەل ئامێرێ هەناسێ یێ سەربەخۆ (SCBA) د ناڤ جلی دا.","Level B: بلندترین پاراستنا هەناسێ (SCBA) دگەل جلەکێ دژی پژاندنا شلەمەنیان، بەلێ جل غازێ ناگریت.","Level C: ماسکا ب فلتەر (Air-Purifying Respirator) و جلێ کیمیایی؛ تەنێ دەمێ ماددە و چڕییا وێ دیار بیت و ئۆکسجین بەس بیت.","Level D: جلوبەرگێن کاری یێن ئاسایی (Uniform) دگەل دەستکێشان؛ بێ مەترسییا کیمیایی یا هەناسێ."]},{heading:"٥. پرۆتۆکۆلا پاقژکرنێ (Decontamination)",body:"پرۆسەیا لادانا ماددێ پیسکەر ژ سەر لەشی و کەرەستەیان:",points:["قۆناغ: ژێکرنا جلان (کو ل دویڤ ڕێنماییێن نێڤدەولەتی نێزیکی ٨٠–٩٠٪ ژ پیسبوونێ لادبەت)، شوشتن ب ئاڤ و سابوونێ، و پشکنین؛ بۆ پیسبوونا تیشکدەر ب ئامێرێ Geiger Counter.","ناڤچە (Zones): ناڤچەیا گەرم (Hot Zone) کو پیس بوویە، ناڤچەیا نیڤ-گەرم (Warm Zone) جهێ پاقژکرنێ، و ناڤچەیا سار (Cold Zone) جهێ فەرماندەیی و تیمێن پزیشکی.","ئاراستەیا بای: ناڤچەیا پاقژ و بنکەیا فەرماندەییێ هەردەم دڤێت ل لایێ هاتنا بای (Upwind) و ل جهەکێ بلندتر بن."]}],media:[{kind:"video",src:"media/videos/uni_27_cbrn_ppe.mp4",title:"ئاستێن پاراستنێ",description:"چەوانیا لبەرکرنا دروست یا جلێ Level A"},{kind:"image",src:"media/images/uni_27_radiation_chart.png",title:"جۆرێن تیشکدانێ",description:"شیکارکرنا شیانا دەرباسبوونا تیشکێن گاما و بێتا"}],quiz:[{question:"کیش ئاستێ PPE پاراستنا تەمام دژی غاز و بەرکەفتنا کیمیایی دابین دکەت؟",options:[{text:"Level D",correct:!1},{text:"Level C",correct:!1},{text:"Level B",correct:!1},{text:"Level A",correct:!0}],explanation:"Level A جلەکێ تەمام داخستی یە و مرۆڤی ژ غاز و شلەمەنییێن کیمیایی یێن کوژەک دپارێزیت."},{question:"ل دویڤ بنەمایێ TDS، تو چەوا دشێی مەترسییا تیشکدانێ ل سەر لەشێ خوە کێم بکەی؟",options:[{text:"ب کێمکرنا دەمێ مانێ و زێدەکرنا مەودای ژ سەرچاڤەیێ",correct:!0},{text:"ب ڤەخوارنا ئاڤێ",correct:!1},{text:"ب ڕەڤینا بێ ئاراستە",correct:!1},{text:"ب بکارئینانا ماسکەکا سادە",correct:!1}],explanation:"دەم (Time)، مەودا (Distance) و پارێزەر (Shielding) سێ بنەمایێن زانستی نە بۆ پاراستنا مرۆڤی ژ تیشکدانێ."}]},{id:28,code:"INVEST-2700",icon:"Search",accent:"#d97706",title:"ڤەکۆلین ل ئەگەرێن ئاگری",subtitle:"Scientific Fire & Arson Investigation",summary:"زانستێ دیتنا سەرچاڤەیا ئاگری، شیکارکرنا نیشانێن سۆتنێ، و ڕێبازا NFPA 921.",blocks:[{body:"ڤەکۆلین ل ئەگەرێن ئاگری زانستەکێ تێکەلە ژ کارێ پۆلیسی و ئەندازیاری. ئارمانج دیتنا ڕاستییا ڕووداوی یە: ئەرێ ئاگر ب ڕێکەفت (Accidental) بوویە یان ب ئەنقەست (Arson)؟ ئەڤ مۆدیوولە پشت ب ڕێنماییا NFPA 921 (Guide) دبەستیت کو ڕێبازا زانستی (Scientific Method) بۆ کۆمکرن و شیکارکرنا بەلگەیان دیار دکەت."},{heading:"١. دیارکرنا سەرچاڤەیا دەستپێکێ (Origin Determination)",body:"دیتنا وێ خالێ یا کو ئاگر لێ دەست پێ کرییە:",points:["V-Pattern: نیشانەکا ب شێوەیێ پیتا V ل سەر دیواران دروست دبیت و ئاراستەیا ئاگری ژ خوارێ بەرەڤ سەری نیشان ددەت. بنێ ڤێ نیشانێ گەلەک جاران نێزیکی سەرچاڤەیا ئاگری یە.","نزمترین خالا سۆتنێ: چونکی گەرمی بەرەڤ سەری دچیت، نزمترین جهێ کو زیانا سۆتنێ لێ هەی گەلەک جاران نێزیکی جهێ دەستپێکێ یە (بەلێ پشتی Flashover ئەڤ نیشانە دشێن بهێنە گوهۆڕین).","Calcination: گوهۆڕینێن کیمیایی ل سەر دیوارێن گەچی (Gypsum) کو نیشان ددەن کا ئاگر چەند و بۆ چ ماوەیەکێ ل وی جهی مایە."]},{heading:"٢. ماددەیێن لەزکەر (Accelerants)",body:"دیتنا ئاگرێ ب ئەنقەست ب ڕێکا پاشماوەیێن سۆتەمەنیێ:",points:["هایدرۆکاربۆن (Hydrocarbons): دیتنا پاشماوەیێن بەنزین، گازوایل یان نەفتێ د ناڤ کاڤلان دا.","سەیێن بێهنکرنێ: تیمێن ڤەکۆلینێ سەیێن ڕاهێنای (K9) بکار دئینن کو د دەمەکێ کورت دا بێهنا ماددەیێن لەزکەر دبینن؛ بەلێ ل دویڤ NFPA 921، هەر ئاماژەیەکا سەیی دڤێت ب شیکارکرنا تاقیگەهی بهێتە پشتڕاستکرن.","شیکارکرنا تاقیگەهی: بکارئینانا ئامێرێ Gas Chromatography–Mass Spectrometry (GC-MS) بۆ پشتڕاستبوون ژ هەبوونا ماددەیێن کیمیایی د نموونەیێن کاڤل و ئاخێ دا."]},{heading:"٣. نیشانێن ئاگرێ ب ئەنقەست (Arson Indicators)",body:"هندەک نیشان گۆمانێ ل سەر حالەتێن تاوانکاری دروست دکەن:",points:["چەند سەرچاڤە: ئەگەر ئاگر ژ چەند جهان پێکڤە دەست پێ کربیت، بێ پەیوەندی د ناڤبەرا وان دا.","ژ کار ئێخستنا سیستەمان: ئەگەر سیستەمێ Sprinkler یان ئاگەهدارکرنێ پێشوەخت هاتبیتە ڕاوەستاندن.","Trailer: هەبوونا هێلەکا سۆتەمەنیێ یان قوماشی ل سەر عەردی بۆ گەهاندنا ئاگری ژ ژوورەکێ بۆ یا دی."]},{heading:"٤. پاراستنا بەلگەیان (Chain of Custody)",body:"ڕێکارێن یاسایی دا کو بەلگە ل دادگەهێ بهێنە قبوولکرن:",points:["زنجیرەیا پاراستنێ: تۆمارکرنا هەر کەسەکێ دەست دایە بەلگەیەکێ، ژ دەمێ دیتنێ هەتا دگەهیتە تاقیگەهـ و دادگەهێ.","تۆمارکرن: گرتنا وێنەیێن نێزیک (Macro) بۆ نیشانێن هوور، و کێشانا نەخشەیا (Sketch) جهێ ڕووداوی.","تێکچوونا بەلگەیان (Spoliation): هشیاری ژ تێکچوونا بەلگەیان ل دەمێ ڤەمراندنا ئاگری؛ ئاگرکوژ دڤێت ئاگەهداری نیشانێن سۆتنێ بن و پشتی ڤەمراندنێ جهی نەگوهۆڕن."]}],media:[{kind:"video",src:"media/videos/uni_28_fire_patterns.mp4",title:"نیشانێن سۆتنێ",description:"شیکارکرنا جیاوازییا د ناڤبەرا V-pattern و Clean Burn دا"},{kind:"image",src:"media/images/uni_28_arson_dog.jpg",title:"سەیێن K9",description:"ڕۆلێ سەیێن ڕاهێنای د دیتنا ماددەیێن لەزکەر دا"}],quiz:[{question:"نیشانا (V-Pattern) ل سەر دیوارێ ئاڤاهی نیشانا چییە؟",options:[{text:"ئاراستەیا دەرکەفتنا خەلکی",correct:!1},{text:"ئاراستەیا بەلاڤبوونا ئاگری ژ سەرچاڤەیێ بەرەڤ سەری",correct:!0},{text:"تێکچوونا کارەبایێ",correct:!1},{text:"پلەیا ساربوونا ئاگری",correct:!1}],explanation:"ئەڤ نیشانە دیار دکەت کا ئاگر ژ کیرێ دەست پێ کرییە و بەرەڤ کیش لای چوویە، و هاریکارییا ڤەکۆلەران دکەت جهێ دەستپێکێ ببینن."},{question:"بۆچی «زنجیرەیا پاراستنێ» (Chain of Custody) د ڤەکۆلینێ دا گرنگە؟",options:[{text:"بۆ جوانییا ڕاپۆرتێ",correct:!1},{text:"دا کو بەلگە ل دادگەهێ بهێنە قبوولکرن و نەهێنە گوهۆڕین",correct:!0},{text:"بۆ لەزکرنا ئاگرکوژاندنێ",correct:!1},{text:"چ گرنگی نینە",correct:!1}],explanation:"ئەگەر زنجیرەیا پاراستنێ بپچڕیت، پارێزەر دشێن ل دادگەهێ بێژن کو بەلگە هاتییە گوهۆڕین و دۆسیە دشێت بهێتە ڕەتکرن."}]},{id:29,code:"COMM-2800",icon:"RadioTower",accent:"#2563eb",title:"سیستەمێن پەیوەندیکرنێ و پرۆتۆکۆلا ڕادیۆیێ",subtitle:"Emergency Communications & Radio Protocols",summary:"پرۆتۆکۆلێن ئاخفتنێ ب ڕادیۆیێ، کەنالێن تەنگاڤیێ، زمانێ ڕوون (Plain Language)، و پاراستنا پەیوەندییان ل دەمێ کارەساتان.",blocks:[{body:"پەیوەندی ئێکە ژ گرنگترین تشتان ل دەمێ کارەساتان. بێ پەیوەندییەکا باش، هەماهەنگی نابیت و تیم نەشێن پێکڤە کار بکەن. ئەڤ مۆدیوولە چەوانیا بکارئینانا ڕادیۆ و سیستەمێن پەیوەندیێ ل دەمێ تەنگاڤیێ نیشان ددەت."},{heading:"١. بنەمایێن پەیوەندیکرنا ڕادیۆیی",body:"ڕێسایێن سەرەکی یێن ئاخفتنێ ب ڕادیۆیێ:",points:["پێشی گوهداری بکە، پاشان باخڤە: بەری ئاخفتنێ پشتڕاست ببە کو کەنال ڤالایە.","پەیڤێن بەرسڤێ: «وەرگرت»، «تێگەهشتم»، «بەلێ».","ئەلفوبێیا دەنگی (Phonetic Alphabet): Alfa، Bravo، Charlie...","کورت و ڕوون: پەیاما خوە کورت و ڕوون بکە.","دووبارەکرن: پەیامێن گرنگ (جه، ژمارە، فەرمان) دووبارە بکە یان ژ وەرگری بخوازە دووبارە بکەت."]},{heading:"٢. زمانێ ڕوون ل جهێ کۆدان (Plain Language)",body:"ل دویڤ NIMS/ICS، ل ڕووداوێن کو چەند دەزگەهـ تێدا بەشدار دبن، ئاخفتن ب زمانەکێ سادە و ڕوون دبیت. کۆدێن دەهـ (Ten-codes) سیستەمەکێ کەڤن (Legacy) و ناڤخۆیی نە، و واتایا وان ژ دەزگەهەکێ بۆ یێ دی جودایە. نموونە:",points:["ل جهێ کۆدا کەڤن «10-4» بێژە: «وەرگرت» یان «تێگەهشتم».","ل جهێ «10-33» بێژە: «تەنگاڤی، پێدڤی ب هاریکارییا بلەز هەیە» (بۆ مەترسییا ژیانا ئاگرکوژەکی: Mayday).","ل جهێ «10-9» بێژە: «دووبارە بکە».","ل جهێ «10-20» جهێ خوە ب ناڤ و نیشان بێژە، بۆ نموونە: «ئەز ل نهۆما سێیێ، لایێ باکووری مە».","Over: پەیاما من ب دووماهی هات و چاڤەڕێی بەرسڤێ مە / Out: ئاخفتن ب دووماهی هات."]},{heading:"٣. سیستەمێن پەیوەندیێ",body:"جۆرێن سیستەمێن پەیوەندیێ:",points:["VHF/UHF: ڕادیۆیێن دەستی و ترمبێلان یێن ئاسایی.","سەتەلایت (Satellite): بۆ دەمێ تۆرێن عەردی کار ناکەن.","Push-to-Talk (PTT): ئاخفتن ب پێلێکرنا دوگمەیەکێ ب ڕێکا ڕادیۆ یان ئەپلیکەیشنێن مۆبایلێ.","Repeater: ئامێرێ بەهێزکرن و دووبارە بەلاڤکرنا سیگنالێ بۆ مەودایەکێ درێژتر.","Mesh Network: تۆرەکا خوە-ڕێکخەر کو هەر ئامێرەک پەیامان دگەهینیتە ئامێرێ دی."]},{heading:"٤. هەماهەنگی ل دەمێ کارەساتان",body:"چەوانیا هەماهەنگییا تیمان:",points:["کەنالێ هەماهەنگیێ: کەنالەکێ هەڤپشک یێ دیارکری بۆ هەمی تیمێن د ڕووداوی دا، ل دویڤ پلانا پەیوەندییان.","کەنالێ فەرماندەییێ (Command Channel): تەنێ سەرکردەیێن یەکەیان و فەرماندەیێ ڕووداوی ل سەر ڤی کەنالی دئاخڤن.","ڕاپۆرتێن ب دەمێ دیارکری: وەک PAR (Personnel Accountability Report) ل دویڤ پلانا ڕووداوی یان ل دەمێ گوهۆڕینێن گرنگ.","هاوارخوازی: Mayday سێ جاران دهێتە گۆتن (Mayday, Mayday, Mayday)، و هەمی کەس کەنالێ ڤالا دکەن.","GPS: شوپاندنا جهێ هەر تیمەکێ."]},{heading:"٥. ڕێکێن یەدەک دەمێ تۆر کار ناکەن",body:"دەمێ پەیوەندییا ئاسایی کار ناکەت:",points:["پەیامبەر (Runners): کەسێن پەیامان ب دەست یان ب نڤیسینێ دگەهینن.","خالا کۆمبوونێ یا پێشوەخت: هەمی تیم ل دەمێ دیارکری دزڤڕنە جهەکێ ڕێککەفتی.","GPS Tracker: ئامێرێ شوپاندنا جهی بۆ هەر تیمەکێ.","نیشانێن ڕووناهیێ: ب چرا یان فلاشێ، ب تایبەتی ب شەڤ.","نیشانێن دەنگی: دەنگێن دیارکری یێن فیکە یان زەنگێ کو هەمی تیم واتایا وان دزانن."]}],media:[{kind:"video",src:"media/videos/uni_28_radio.mp4",title:"بکارئینانا ڕادیۆیێ",description:"چەوانیا ئاخفتنێ ب ڕادیۆیێ"},{kind:"image",src:"media/images/uni_28_phonetic.png",title:"ئەلفوبێیا دەنگی",description:"ئەلفوبێیا دەنگی (Phonetic Alphabet) ب نموونەیان"},{kind:"video",src:"media/videos/uni_28_coordination.mp4",title:"هەماهەنگی",description:"هەماهەنگییا تیمان"}],quiz:[{question:"کۆدا کەڤن «10-4» ل دویڤ زمانێ ڕوون یێ NIMS چەوا دهێتە گۆتن؟",options:[{text:"تەنگاڤی",correct:!1},{text:"وەرگرت / تێگەهشتم",correct:!0},{text:"جهێ من",correct:!1},{text:"دووبارە بکە",correct:!1}],explanation:"10-4 کۆدەکا کەڤنە ب واتایا «وەرگرت»؛ ل دویڤ NIMS/ICS، ل جهێ کۆدێ ب زمانەکێ ڕوون دبێژن «وەرگرت» یان «تێگەهشتم»، چونکی کۆد ل هەمی دەزگەهان ب ئێک واتا نینن."},{question:"پەیڤا «Mayday» کەنگی دهێتە بکارئینان؟",options:[{text:"بۆ سلاڤکرنێ",correct:!1},{text:"تەنگاڤییا گران: ژیانا کەسەکی د مەترسیێ دایە و پێدڤی ب هاریکاریێ هەیە",correct:!0},{text:"ب دووماهی هاتنا کاری",correct:!1},{text:"پشوودان",correct:!1}],explanation:"Mayday پەیڤا تەنگاڤییا گرانە: یانی ژیانا کەسەکی (ب تایبەتی ئاگرکوژەکی) د مەترسیێ دایە و پێدڤی ب هاریکارییا بلەز هەیە."}]},{id:30,code:"LOG-2900",icon:"Package",accent:"#059669",title:"لۆجیستیک و ڕێڤەبرنا سەرچاڤەیان ل کارەساتان",subtitle:"Disaster Logistics & Supply Chain Management",summary:"دابینکرنا خوارن، دەرمان و کەرەستەیان بۆ هزاران کەسان، و ڕێڤەبرنا کۆگەهـ و ڤەگوهاستنێ.",blocks:[{body:"لۆجیستیکا کارەساتان زانستێ گەهاندنا کەرەستە و خزمەتگوزارییان یە بۆ خەلکێ پێدڤی، د دەمەکێ کورت دا و ب شێوەیەکێ دادپەروەر. ئەڤ مۆدیوولە بۆ سەرکردە و ڕێڤەبەران گرنگە کو دڤێت بزانن چەوا سەرچاڤەیان ڕێڤە ببەن."},{heading:"١. پلاندانانا لۆجیستیکی",body:"ئامادەکارییا پێشوەخت:",points:["کۆگەهـ: دیارکرنا جهێن هەلگرتنا کەرەستەیان بەری کارەساتێ.","لیستا کەرەستەیان: خوارن، ئاڤ، دەرمان، چادر و بەتانی.","ڤەگوهاستن: ترمبێل، فڕۆکە و ئامرازێن دی.","تیم: کارمەندێن لۆجیستیکێ یێن ڕاهێنای.","پەیوەندی: گرێبەست و پەیوەندی دگەل دابینکەران."]},{heading:"٢. ڕێڤەبرنا کۆگەهێ",body:"چەوانیا هەلگرتن و دابەشکرنا کەرەستەیان:",points:["ژمارتن (Inventory): ژمارتن و تۆمارکرنا هەمی کەرەستەیان.","کۆدکرن: کۆدەکێ تایبەت بۆ هەر جۆرەکێ کەرەستەیان.","بەسەرچوون: چاڤدێرییا ڕێکەفتا بەسەرچوونا خوارن و دەرمانان (یێ بەری هەمیان بەسەردچیت، بەری هەمیان دهێتە دابەشکرن).","پاراستن: ژ گەرمی، سەرما و شێداریێ.","ئاسایش: ڕێگرتن ل دزی و زیانێ."]},{heading:"٣. ڤەگوهاستن و دابەشکرن",body:"گەهاندنا کەرەستەیان بۆ جهێ پێدڤی:",points:["ترمبێل: بۆ ناڤ باژێر و ناڤچەیێن نێزیک.","فڕۆکە: بۆ جهێن دوور یان دابڕای.","هەلیکۆپتەر: بۆ جهێن چیایی و ڕێک گرتی.","خالێن دابەشکرنێ: جهێن دیارکری و ئاشکەرا بۆ دابەشکرنا کەرەستەیان.","تۆمارکرن: کێ وەرگرت، چ وەرگرت و چەند."]},{heading:"٤. زنجیرەیا دابینکرنێ (Supply Chain)",body:"هەماهەنگی دگەل دابینکەران:",points:["دابینکەر: کۆمپانی و ڕێکخراوێن دابینکرنێ.","داخواز: چەوانیا داخوازکرنا کەرەستەیان (Requisition).","گەهاندن: دیارکرنا دەم و جهێ گەهاندنێ.","دارایی: بودجە و پارەدان.","شوپاندن (Tracking): چاڤدێرییا کەرەستەیان ژ دابینکەری هەتا وەرگری."]},{heading:"٥. ڕێڤەبرنا پەناگەهان",body:"خزمەتگوزارییێن پەناگەهان (ل دویڤ ستانداردێن Sphere):",points:["چادر: دانان و ڕێکخستنا پەناگەهێ.","خوارن: دابینکرنا خوارنێ بۆ هزاران کەسان.","ئاڤ: لایێ کێم ١٥ لیتر ئاڤا پاقژ بۆ هەر کەسەکی د ڕۆژێ دا.","توالێت و دەستشۆر: ب ژمارەیەکا بەس و جهێ سەلامەت بۆ ژن و زارۆکان.","ساخلەمی: خزمەتگوزارییا پزیشکی و هەوارهاتنا ئێکێ."]}],media:[{kind:"video",src:"media/videos/uni_29_logistics.mp4",title:"لۆجیستیکا کارەساتان",description:"بنەمایێن لۆجیستیکێ"},{kind:"image",src:"media/images/uni_29_warehouse.png",title:"کۆگەهـ",description:"ڕێڤەبرنا کۆگەهێ"},{kind:"video",src:"media/videos/uni_29_distribution.mp4",title:"دابەشکرن",description:"دابەشکرنا کەرەستەیان"}],quiz:[{question:"لۆجیستیکا کارەساتان چییە؟",options:[{text:"ڤەمراندنا ئاگری",correct:!1},{text:"گەهاندنا کەرەستە و خزمەتگوزاری بۆ خەلکێ پێدڤی",correct:!0},{text:"هەوارهاتنا ئێکێ",correct:!1},{text:"ڕزگارکرن",correct:!1}],explanation:"لۆجیستیکا کارەساتان زانستێ گەهاندنا کەرەستە و خزمەتگوزارییان یە (خوارن، ئاڤ، دەرمان) بۆ خەلکێ پێدڤی."},{question:"بۆچی چاڤدێرییا بەسەرچوونا خوارن و دەرمانان گرنگە؟",options:[{text:"بۆ ڕەنگی",correct:!1},{text:"بۆ پاراستنا ساخلەمییا خەلکی",correct:!0},{text:"بێ مفایە",correct:!1},{text:"بۆ لەزێ",correct:!1}],explanation:"خوارن و دەرمانێن بەسەرچووی دشێن زیانێ بگەهیننە ساخلەمییا خەلکی، ژبەرهندێ چاڤدێرییا ڕێکەفتا بەسەرچوونێ گەلەک گرنگە."}]},{id:31,code:"TUNNEL-3000",icon:"Construction",accent:"#57534e",title:"سەلامەتییا تونێلان و جهێن ژێرعەردی",subtitle:"Tunnel & Underground Space Safety",summary:"داینامیکا ئاگری ل جهێن داخستی و ژێرعەردی، ڕزگارکرن ل تونێلێن درێژ، و کارتێکرنا دوکێلێ.",blocks:[{body:"تونێل و جهێن ژێرعەردی (وەک تونێلێن ڕێکان، کان و گەراجێن ژێرعەردی) خودان مەترسییێن تایبەتن. ئاگر ل ڤان جهان گەلەک مەترسیدارترە چونکی هەواگوهۆڕین سنووردارە، دەرکەفتن زەحمەتە و دوکێل ب لەز کۆم دبیت. ئەڤ مۆدیوولە بۆ تونێلێن ڕێکان و گەراجێن ژێرعەردی ل باژێرێن هەرێمێ گرنگە (ستانداردێ سەرەکی: NFPA 502)."},{heading:"١. تایبەتمەندییێن تونێلان",body:"تونێل چەوا ژ ئاڤاهییەکێ ئاسایی جودایە:",points:["هەوا: هەواگوهۆڕینا سروشتی سنووردارە و ئاگر ب لەز ئۆکسجینێ بکار دئینیت.","دەرکەفتن: گەلەک جاران تەنێ دوو سەر هەنە، و ل تونێلێن نوو دەرگەهێن تەنگاڤیێ یێن ناڤبەری (Cross-passages) هەنە.","دوکێل: ل بن سەقفێ نزم ب لەز بەلاڤ دبیت و بەرەڤ دوو ئاراستەیان یان ل دویڤ هەواگوهۆڕینێ دچیت.","گەرمی: دیوار و سەقف گەرمیێ دزڤڕینن و گەرمی کۆم دبیت.","درێژی: دشێت چەند کیلۆمەتران بیت، و ئەڤە دەمێ گەهشتنا تیمان درێژ دکەت."]},{heading:"٢. داینامیکا ئاگری ل تونێلان",body:"ئاگر ل تونێلی چەوا ڕەفتار دکەت:",points:["بەلاڤبوون: ل تونێلێن خودان هەواگوهۆڕینا درێژاهی، دوکێل و گەرمی ب ئاراستەیا بای دچن؛ خەلکێ لایێ دی (Upstream) ژ دوکێلێ دهێنە پاراستن.","چینبوونا دوکێلێ (Stratification): ل دەستپێکێ دوکێل ل بن سەقفی چینەکێ دروست دکەت و هەوایێ پاقژ ل خوارێ دمینیت؛ بایێ زێدە یان ئاڤا ڕژاندی دشێت ڤێ چینێ تێک بدەت.","Backlayering: دوکێل ل بن سەقفی بەرەڤاژی ئاراستەیا هەواگوهۆڕینێ دزڤڕیت، دەمێ لەزا هەوایێ ژ لەزا سنووری (Critical Velocity) کێمتر بیت.","Longitudinal Ventilation: هەواگوهۆڕینا درێژاهی ب پانکەیێن تایبەت (Jet Fans) کو دوکێلێ بەرەڤ ئێک ئاراستە دپالدەن.","لەزا گەشەکرنێ: ئاگرێ ترمبێلان و بارهەلگران ل تونێلی دشێت ب لەز گەرمییەکا گەلەک بلند دروست بکەت."]},{heading:"٣. سیستەمێن سەلامەتییا تونێلان",body:"کەرەستەیێن پاراستنێ:",points:["سیستەمێ ئاگەهدارکرنێ: هەستەڤەرێن گەرمی و دوکێلێ، و زەنگ.","ئاگرکوژاندن: سیستەمێن ئاڤێ یێن ئۆتۆماتیکی (Deluge یان Water Mist) و دەرچوونێن ئاڤێ بۆ ئاگرکوژان.","هەواگوهۆڕین: پانکەیێن تایبەت بۆ دەرئێخستن و کۆنترۆلکرنا دوکێلێ.","دەرکەفتنا تەنگاڤیێ: دەرگەهێن تایبەت و ڕێڕەوێن پاراستی ب نیشانێن ڕووناهیدار.","پەیوەندی: سیستەمێ ڕادیۆیێ ل ناڤ تونێلی و تەلەفۆنێن تەنگاڤیێ."]},{heading:"٤. ڕزگارکرن ل تونێلان",body:"چەوانیا ڕزگارکرنا کەسان:",points:["ڕێڕەوا پیادەیان: ڕێکا تایبەت یا دەرکەفتنێ ب پێیان.","ئاراستەیا دەرکەفتنێ: هەردەم بەرەڤ هەوایێ پاقژ و دوور ژ دوکێلێ.","SCBA: ئامێرێ هەناسێ یێ سەربەخۆ بۆ هەمی ئاگرکوژێن دچنە ناڤ تونێلی.","خالا پۆلێنکرنا برینداران (Triage): ل دەرڤەی تونێلی و ل جهەکێ سەلامەت.","هاتنوچوون: گرتنا ڕێکێ بۆ ترمبێلان ب هەماهەنگی دگەل پۆلیسا هاتنوچوونێ."]},{heading:"٥. ڕاهێنان و پلاندانان",body:"ئامادەکارییا پێشوەخت:",points:["پلانا تەنگاڤیێ: بۆ هەر تونێلەکێ پلانەکا تایبەت.","ڕاهێنان: ڕاهێنانێن دەرکەفتنێ یێن خولی.","نەخشە: نەخشەیا تونێلی بۆ تیمێن ئاگرکوژاندنێ.","هەماهەنگی: دگەل پۆلیس و ئەمبوولانسێ.","ئەزموون: وەرگرتنا وانەیان ژ ڕووداوێن بەری نوکە."]}],media:[{kind:"video",src:"media/videos/uni_30_tunnel_fire.mp4",title:"ئاگرێ تونێلی",description:"داینامیکا ئاگری ل تونێلان"},{kind:"image",src:"media/images/uni_30_ventilation.png",title:"هەواگوهۆڕین",description:"سیستەمێ هەواگوهۆڕینا تونێلی"},{kind:"video",src:"media/videos/uni_30_evacuation.mp4",title:"دەرکەفتن",description:"دەرکەفتن ژ تونێلی"}],quiz:[{question:"بۆچی ئاگر ل تونێلان ژ ئاڤاهییەکێ ئاسایی مەترسیدارترە؟",options:[{text:"هەواگوهۆڕین سنووردارە، دەرکەفتن زەحمەتە، و دوکێل کۆم دبیت",correct:!0},{text:"چ جیاوازی نینە",correct:!1},{text:"ئاڤاهییێن ئاسایی خرابترن",correct:!1},{text:"حالەتەکێ ئاسایی یە",correct:!1}],explanation:"د تونێلی دا هەواگوهۆڕین سنووردارە، دەرکەفتن کێمن و دوورن، و دوکێل ل بن سەقفێ نزم ب لەز کۆم دبیت؛ ئەڤە هەمی مەترسیێ زێدە دکەن."},{question:"Backlayering چییە؟",options:[{text:"هەواگوهۆڕین",correct:!1},{text:"زڤڕینا دوکێلێ بەرەڤاژی ئاراستەیا هەواگوهۆڕینێ",correct:!0},{text:"ڕزگارکرن",correct:!1},{text:"ئاگرکوژاندن",correct:!1}],explanation:"Backlayering دیاردەیەکە کو تێدا دوکێل ل بن سەقفی بەرەڤاژی ئاراستەیا هەواگوهۆڕینێ دزڤڕیت، دەمێ لەزا هەوایێ بەس نەبیت؛ ئەڤە بۆ خەلک و تیمان گەلەک مەترسیدارە."}]},{id:32,code:"UNI-332",icon:"FireExtinguisher",accent:"#dc2626",title:"تەمرینکا ئاگری — ڕاهێنانا تەمام",subtitle:"Fire Extinguisher — Complete Training (PASS)",summary:"ناسینا هەمی جۆرێن تەمرینکان، پۆلێن ئاگری ل دویڤ NFPA و EN 2، ڕێکارا P.A.S.S ب درێژی، و پشکنین و چاککرنا تەمرینکان.",blocks:[{body:"تەمرینکا ئاگری (Fire Extinguisher) ئامێرەکێ سەرەکی یە بۆ ڤەمراندنا ئاگرێن بچووک د قۆناغا دەستپێکێ دا. ل زانکۆ و تاقیگەهێن ڤەکۆلینێ، ماددەیێن کیمیایی و ئامێرێن کارەبایێ مەترسییا ئاگری بلند دکەن. هەر قوتابی و مامۆستایەک دڤێت بشێت تەمرینکێ ب لەز و ب دروستی بکار بینیت. تەمرینکێن دەستی تەنێ بۆ چەند چرکەیان کار دکەن (نێزیکی ١٠–٢٠ چرکەیان بۆ قەبارەیێن بچووک)، ژبەرهندێ دڤێت ب لەز و ب دروستی بهێنە بکارئینان. ئەگەر ئاگر مەزن بوو یان دوکێل ڕێکا دەرکەفتنێ گرت، تەمرینکێ بهێلە، دەرکەڤە و پەیوەندیێ ب ١١٥ بکە."},{heading:"١. پۆلێن ئاگری (Fire Classes) ل دویڤ NFPA",body:"ل دویڤ سیستەمێ ئەمریکی NFPA (NFPA 10)، ئاگر دبیتە پێنج پۆل. ل سیستەمێ ئەورووپی EN 2: پۆلا B تەنێ شلەمەنی نە، پۆلا C غازن، کارەبا پۆلەکا جودا نینە، و ڕۆنێ مەتبەخێ پۆلا F یە:",points:["پۆلا A (ماددەیێن ڕەق): دار، کاغەز، قوماش، پلاستیک. تەمرینک: ئاڤ، تۆزا ABC، کەف (Foam).","پۆلا B (شلەمەنی و غازێن سۆتێنەر): بەنزین، نەفت، ڕۆن، ئەلکهول، سۆلڤێنتێن تاقیگەهێ. تەمرینک: CO₂، تۆزا ABC، کەف. (چ جاران ئاڤێ بکار نەئینە!).","پۆلا C (ئامێرێن کارەبایێ یێن ب کارەبا ڤە): سویچ، ترانسفۆرمەر، پانێل، مۆلیدە، سێرڤەر. تەمرینک: CO₂، تۆزا ABC، Clean Agent. (ئاڤ و کەف قەدەغەنە!) ئەگەر سەلامەت بیت، پێشی کارەبایێ ببڕە.","پۆلا D (کانزایێن سۆتێنەر): مەگنیسیۆم، تۆزا ئەلەمنیۆمێ، تیتانیۆم، لیتیۆم (کانزا). تەمرینک: تۆزا تایبەت یا پۆلا D. (ئاڤ دشێت کارلێکەکا توند و تەقین چێبکەت!) تێبینی: ئاگرێ باترییێن لیتیۆم-ئایۆن پۆلا D نینە؛ ئاڤ و سارکرنا بەردەوام پێشنیار دهێتە کرن.","پۆلا K (ڕۆنێن مەتبەخێ؛ ل EN 2 پۆلا F): ڕۆن و دوهنێن چێشتلێنانێ. تەمرینک: Wet Chemical (ل دویڤ BS EN 3 و BS 7863 ب ڕەنگێ زەر). (ئاڤ ڕۆنێ سۆتی دپەڕینیت و ئاگری بەلاڤ دکەت!)."]},{heading:"٢. جۆرێن تەمرینکان و ڕەنگێن وان",body:"ل دویڤ ستانداردێ ئەورووپی BS EN 3، لەشێ تەمرینکێ سۆرە و پارچەیەکا ڕەنگکری نیشانا جۆری یە (ل NFPA ڕەنگ نیشانا جۆری نینە؛ لێڤکێ (Label) بخوینە):",points:["تەمرینکا ئاڤێ (Water): سۆر. تەنێ بۆ پۆلا A (دار، کاغەز). چ جاران بۆ کارەبایێ یان ڕۆنی بکار نەئینە!","تەمرینکا CO₂: ڕەش. بۆ پۆلا B و ئامێرێن کارەبایێ. غازەکا گەلەک سار دەردکەڤیت و لوولەیا وێ (Horn) گەلەک سار دبیت؛ دەستێ خوە ل لوولەیێ نەدە، دێ دەستێ تە سۆژیت (قەرسین). مەودایێ بکارئینانێ: ١–٢ مەتر. ل ژوورێن بچووک پشتی بکارئینانێ ژوورێ بهێلە.","تەمرینکا تۆزا ABC (Dry Powder): شین. بۆ پۆلێن A، B و C (نە بۆ D و نە بۆ K/F). بەلاڤترین جۆرە. کێماسی: دیتنێ کێم دکەت و ئامێران پیس دکەت.","تەمرینکا کەفێ (Foam/AFFF): کرێمی. بۆ پۆلێن A و B. کەفێ ل سەر شلەمەنیێ بەلاڤ دکەت و ئۆکسجینێ دبڕیت. بۆ کارەبایێ بکار نەئینە! تێبینی: کەفا AFFF ماددەیێن PFAS تێدا هەنە و ل گەلەک وەلاتان ب کەفا بێ فلۆر (Fluorine-Free) دهێتە گوهۆڕین.","تەمرینکا Clean Agent: بۆ پۆلێن B و C (هندەک جۆر بۆ A ژی) - بۆ ئامێرێن هەستیار، تاقیگەهـ و ژوورێن سێرڤەران. چ پاشماوە ناهێلیت.","تەمرینکا تایبەت (Class D): بۆ کانزایێن سۆتێنەر - تۆزەکا تایبەت تێدایە (ب گشتی لێڤکا وێ زەر یان شینە؛ ل دویڤ لێڤکێ بکار بینە)."]},{heading:"٣. ڕێکارا P.A.S.S ب درێژی",body:"ئەڤە ڕێکارا نێڤدەولەتی یە بۆ بکارئینانا تەمرینکێ؛ ژ مەودایەکێ سەلامەت دەست پێ بکە و ڕێکا دەرکەفتنێ ل پشت خوە بهێلە و چ جاران پشتا خوە نەدە ئاگری:",points:["P = Pull (بکێشە): مسمارا سەلامەتیێ (Safety Pin) بکێشە. ئەڤ مسمارە ناهێلیت تەمرینک ب خەلەتی کار بکەت.","A = Aim (ئاراستە بکە): لوولەیا تەمرینکێ بەرەڤ بنێ ئاگری بگرە، نە بەرەڤ گڕێ سەری!","S = Squeeze (فشار بدە): دەستکا تەمرینکێ ب هێز فشار بدە دا کو ماددە دەرکەڤیت.","S = Sweep (بلڤینە): لوولەیێ چەپ و ڕاست ل سەر بنێ ئاگری بلڤینە هەتا ئاگر ب تەمامی ڤەدمریت، و چاڤدێریێ بکە دا کو دووبارە گڕ نەگریت."]},{heading:"٤. پشکنین و چاککرنا تەمرینکان (NFPA 10)",body:"هەر هەیڤ دڤێت ئەڤ خالە ب پشکنینەکا دیتنی بهێنە پشکنین:",points:["فشارا ناڤ تەمرینکێ (Pressure Gauge): دڤێت دەرزیکا پێڤەرێ ل ناڤچەیا کەسک بیت.","مسمارا سەلامەتیێ: دڤێت ل جهێ خوە بیت و مۆر (Seal) نەشکەستی بیت.","لوولە (Nozzle/Hose): نابیت شکەستی یان گرتی بیت.","لەشێ تەمرینکێ: نابیت ژەنگی، قەلشی یان زیانلێکەفتی بیت، و دڤێت ل جهێ خوە و ب ساناهی بهێتە گەهشتن.","چاککرنا سالانە (Annual Maintenance) ژ لایێ کەسەکێ شارەزا ڤە؛ و تاقیکرنا هایدرۆستاتیکی (Hydrostatic Test) ل دویڤ دەمێن دیارکری: هەر ٥ سالان بۆ ئاڤ، کەف، CO₂ و Wet Chemical، و هەر ١٢ سالان بۆ پترییا تەمرینکێن تۆزێ. ئەڤە گوهۆڕین نینە؛ تەمرینک تەنێ دهێتە گوهۆڕین ئەگەر د پشکنین یان تاقیکرنێ دا سەرنەکەفت؛ بەلێ تەمرینکێن ئێکجاری (Non-rechargeable) پشتی ١٢ سالان ژ ڕێکەفتا چێکرنێ دهێنە لادان."]},{heading:"٥. مەترسییێن تایبەت ل زانکۆیان",body:"زانکۆ جهێن هەستیارن ژبەر:",points:["تاقیگەهێن کیمیایی: سۆلڤێنت و ئەلکهول (پۆلا B)، و هندەک کانزایێن چالاک (پۆلا D).","ژوورێن سێرڤەران و IT: ئامێرێن ب کارەبا ڤە (پۆلا C ل NFPA): Clean Agent یان CO₂.","مەتبەخێن زانکۆیێ: ڕۆنێ چێشتلێنانێ (پۆلا K ل NFPA / F ل EN 2).","کتێبخانە و ئەرشیڤ: کاغەز و دار (پۆلا A).","جهێ دانانێ: تەمرینکان نێزیکی دەرگەهـ و ڕێڕەوان دانێ؛ ل دویڤ NFPA 10، مەودایێ چوونێ بۆ گەهشتن ب تەمرینکەکێ ل جهێن پۆلا A نابیت ژ ٢٣ مەتران (٧٥ پێ) پتر بیت، و ل جهێن پۆلا B کێمترە (٩–١٥ مەتر)."]}],media:[{kind:"video",src:"media/videos/uni_fire_ext.mp4",title:"تەمرینکا ئاگری",description:"ڕێکارا P.A.S.S و جۆرێن تەمرینکان"}],quiz:[{question:"تەمرینکا CO₂ (ڕەش) بۆ کیش پۆلێن ئاگری (ل دویڤ NFPA) گونجایە؟",options:[{text:"A و D",correct:!1},{text:"B و C",correct:!0},{text:"A و K",correct:!1},{text:"D و K",correct:!1}],explanation:"CO₂ بۆ شلەمەنییێن سۆتێنەر (B) و ئامێرێن کارەبایێ (C) گونجایە چونکی کارەبا ناگەهینیت و پاشماوە ناهێلیت."},{question:"ل ڕێکارا P.A.S.S، لوولەیا تەمرینکێ دڤێت بەرەڤ کیرێ بیت؟",options:[{text:"سەرێ گڕێ",correct:!1},{text:"بنێ ئاگری",correct:!0},{text:"دووری ئاگری",correct:!1},{text:"سەقف",correct:!1}],explanation:"هەردەم لوولەیێ بەرەڤ بنێ ئاگری ئاراستە بکە، چونکی سۆتەمەنی ل وێرێ یە و ئاگر ژ وێرێ دهێتە ڤەمراندن."},{question:"ل تاقیگەها زانکۆیێ ئاگرەکێ شلەمەنییەکا کیمیایی یا سۆتێنەر چێبوو؛ تو کیش تەمرینکێ بکار دئینی؟",options:[{text:"ئاڤ (سۆر)",correct:!1},{text:"CO₂ یان ABC (ڕەش/شین)",correct:!0},{text:"تۆزا تایبەت یا پۆلا D",correct:!1},{text:"Wet Chemical",correct:!1}],explanation:"ئاگرێ شلەمەنییێن سۆتێنەر پۆلا B یە: CO₂ یان تۆزا ABC گونجاینە. ئەگەر ئاگر مەزن بوو، جهی بهێلە و پەیوەندیێ ب ١١٥ بکە."}]}],t={lessons:e};export{t as default,e as lessons};
